    var html_stack: [128]syntax.Tag = undefined; var depth: usize = 0;
    var table_stack: [64]usize = undefined; var tables: usize = 0;
    var at: usize = 0;
    var root_table_opening: ?[]const u8 = null;
    var root_table_end: ?usize = null;
