const PageStyleData = struct {
    authored_sources: []const profile.Source,
    context_sources: []const profile.Source,
    figure_alternative_sources: ?[]const profile.Source = null,
    page: RawPage,
    scope: profile.BoundedTextClassScope,
    outer: ObservedOuterContext,
    observed_nodes: []const ObservedSiblingNode = &.{},
    observed_html: []const u8 = "",
    figure_styles: []const FigureStyleProof = &.{},
    deferred_ready_styles: bool = false,
    figure_assets: []const compiler.FigureObservedAsset = &.{},
    block_renditions: ?FigureBlockRenditions = null,
    source_custom_elements: []const profile.SourceCustomElementProof = &.{},
    authored_element_styles: []const AuthoredElementStyleProof = &.{},
};

const FloatingTablePageContext = struct { styles: *const profile.Profile, nodes: []const profile.ObservedStyleNode, root: u32 };

const SelectedFloatingTable = struct {
    page_contexts: []const FloatingTablePageContext,
    opening_start: usize,
    opening_end: usize,
    contexts: []const profile.TableContainingDirectionContext,
    link_contexts: []const profile.TableContainingDirectionContext = &.{},
};

const FloatingTableAnchor = struct {
    table: Inventory,
    cell: Inventory,
    text: []const u8,
    opening_start: usize = 0,
    opening_end: usize = 0,
    row: usize,
    slot: usize,
    observed_table: ?usize = null,
};

fn floatingTableLiteralText(a: A, raw: []const u8) !?[]const u8 {
    var text: std.ArrayList(u8) = .empty;
    var at: usize = 0;
    var small = false;
    while (at < raw.len) {
        if (raw[at] != '<') { try text.append(a, raw[at]); at += 1; continue; }
        const tag = syntax.tagAt(raw, at) orelse return null;
        if (std.mem.trim(u8, tag.attrs, " \t\r\n/").len != 0) return null;
        if (tag.is("br") and !tag.closing) { try text.append(a, ' '); }
        else if (tag.is("small") and !tag.self_closing and tag.closing == small) { small = !small; }
        else return null;
        at = tag.end;
    }
    if (small) return null;
    // Coarsen whitespace only in the all-occurrence ambiguity signature.
    // The source and rendered cell bodies are never rewritten by this proof.
    var normalized: std.ArrayList(u8) = .empty;
    var space = false;
    for (text.items) |byte| {
        if (std.ascii.isWhitespace(byte)) { space = normalized.items.len != 0; continue; }
        if (space) try normalized.append(a, ' ');
        space = false; try normalized.append(a, byte);
    }
    return rootTableLiteralText(a, normalized.items);
}

fn floatingTableSourceAnchors(a: A, source: []const u8) ![]const FloatingTableAnchor {
    if (source.len > 4 * 1024 * 1024) return &.{};
    var anchors: std.ArrayList(FloatingTableAnchor) = .empty;
    var scan: syntax.OpaqueScan = .{};
    var table: ?struct { attrs: Inventory, start: usize, end: usize, row: usize = 0, slot: usize = 0 } = null;
    var at: usize = 0;
    while (at < source.len) {
        if (scan.protectedEnd(source, at, null)) |end| { at = end; continue; }
        if (source[at] == '<') {
            const tag = syntax.tagAt(source, at) orelse return &.{};
            at = tag.end; continue;
        }
        if (source[at] == '[' or source[at] == '{') {
            if (!(at == 0 or source[at - 1] == '\n') or !std.mem.startsWith(u8, source[at..], "{|")) {
                if (syntax.balanced(source, at)) |pair| { at = pair.end; continue; }
            }
        }
        if (at != 0 and source[at - 1] != '\n') { at += 1; continue; }
        const stop = std.mem.indexOfScalarPos(u8, source, at, '\n') orelse source.len;
        const line = std.mem.trimEnd(u8, source[at..stop], "\r");
        const next = if (stop < source.len) stop + 1 else stop;
        if (std.mem.startsWith(u8, line, "{|")) {
            if (table != null) return &.{};
            const attrs = (try rootTableAttributes(a, line[2..])) orelse { at = next; continue; };
            table = .{ .attrs = attrs, .start = at, .end = at + line.len };
        } else if (std.mem.startsWith(u8, line, "|}")) {
            table = null;
        } else if (table) |*owner| {
            if (std.mem.startsWith(u8, line, "|-")) { owner.row += 1; owner.slot = 0; }
            else if (line.len != 0 and (line[0] == '|' or line[0] == '!')) {
                if (std.mem.startsWith(u8, line, "|+") or std.mem.indexOf(u8, line, "||") != null or std.mem.indexOf(u8, line, "!!") != null) { table = null; at = next; continue; }
                const slot = owner.slot; owner.slot += 1;
                if (line[0] == '!') { at = next; continue; }
                const raw = line[1..];
                const separator = std.mem.indexOfScalar(u8, raw, '|');
                const attrs = if (separator) |bar| (try rootTableAttributes(a, raw[0..bar])) orelse { at = next; continue; }
                    else (try rootTableAttributes(a, "")) orelse return invalid;
                const body = if (separator) |bar| raw[bar + 1..] else raw;
                const text = (try floatingTableLiteralText(a, body)) orelse { at = next; continue; };
                if (text.len != 0) try anchors.append(a, .{ .table = owner.attrs, .cell = attrs, .text = text,
                    .opening_start = owner.start, .opening_end = owner.end, .row = owner.row, .slot = slot });
                if (anchors.items.len > 4096) return &.{};
            }
        }
        at = next;
    }
    return anchors.toOwnedSlice(a);
}

fn floatingTableObservedAnchor(a: A, html: []const u8, nodes: []const ObservedSiblingNode, index: usize) !?FloatingTableAnchor {
    const cell = nodes[index];
    if (!cell.tag.is("td")) return null;
    const row = cell.parent orelse return null;
    if (!nodes[row].tag.is("tr")) return null;
    var table = nodes[row].parent orelse return null;
    if (nodes[table].tag.is("tbody")) table = nodes[table].parent orelse return null;
    if (!nodes[table].tag.is("table")) return null;
    const text = (try floatingTableLiteralText(a, html[cell.tag.end..cell.inner_end orelse return null])) orelse return null;
    if (text.len == 0) return null;
    var row_ordinal: usize = 0;
    var previous = nodes[row].previous;
    while (previous) |before| { if (!nodes[before].tag.is("tr")) return null; row_ordinal += 1; previous = nodes[before].previous; }
    var slot: usize = 0; previous = cell.previous;
    while (previous) |before| { if (!nodes[before].tag.is("td") and !nodes[before].tag.is("th")) return null; slot += 1; previous = nodes[before].previous; }
    return .{ .table = nodes[table].attributes, .cell = cell.attributes, .text = text, .row = row_ordinal, .slot = slot, .observed_table = table };
}

fn floatingTableAnchorEqual(a: FloatingTableAnchor, b: FloatingTableAnchor) bool {
    return sameSiblingAttributes(a.table, b.table) and sameSiblingAttributes(a.cell, b.cell) and equal(a.text, b.text);
}

fn floatingTableOrdinaryOpening(source: []const u8, opening: usize) bool {
    var at: usize = 0; var scan: syntax.OpaqueScan = .{};
    while (at < source.len and at <= opening) {
        if (at == opening) return true;
        if (scan.protectedEnd(source, at, null)) |end| { at = end; continue; }
        if (source[at] == '<') {
            const tag = syntax.tagAt(source, at) orelse return false;
            at = tag.end; continue;
        }
        if (source[at] == '[' or source[at] == '{') {
            if (syntax.balanced(source, at)) |pair| { at = pair.end; continue; }
            if (std.mem.startsWith(u8, source[at..], "{{")) return false;
        }
        at += 1;
    }
    return false;
}

fn floatingTableObservedOwner(anchors: []const FloatingTableAnchor, observed: []const ?FloatingTableAnchor, anchor: FloatingTableAnchor) ?usize {
    var owner: ?usize = null;
    var source_matches: usize = 0; var observed_matches: usize = 0;
    for (anchors) |other| if (floatingTableAnchorEqual(anchor, other)) {
        source_matches += 1;
        if (other.opening_start != anchor.opening_start) return null;
        var matching_slots: usize = 0;
        for (observed) |candidate| if (candidate) |known| if (floatingTableAnchorEqual(other, known) and known.row == other.row and known.slot == other.slot) { matching_slots += 1; };
        if (matching_slots != 1) return null;
    };
    for (observed) |candidate| if (candidate) |known| if (floatingTableAnchorEqual(anchor, known)) {
        observed_matches += 1;
        const current = known.observed_table orelse return null;
        if (owner) |prior| { if (prior != current) return null; }
        else owner = current;
    };
    if (source_matches != observed_matches) return null;
    return owner;
}

fn floatingTableExistingContexts(a: A, figures: []const SelectedFigureStyle) ![]const FloatingTablePageContext {
    if (figures.len != 0 and figures[0].contexts.len >= 2) {
        const result = try a.alloc(FloatingTablePageContext, 2);
        for (result, 0..) |*out, index| { const context = figures[0].contexts[index]; out.* = .{ .styles = context.styles, .nodes = context.nodes, .root = context.root }; }
        return result;
    }
    return &.{};
}

fn selectFloatingTableStyles(a: A, parent: *const profile.Profile, stored: *const PageStyleData, source: []const u8,
    figures: []const SelectedFigureStyle) ![]const SelectedFloatingTable {
    // Old no-operation Books have no authenticated alternate GET-head set.
    // This optional policy declines; it cannot manufacture that authority or
    // turn otherwise valid page-style selection into an error.
    if (stored.figure_alternative_sources == null) return &.{};
    const anchors = try floatingTableSourceAnchors(a, source);
    if (anchors.len == 0) return &.{};
    const html = try selectedStoredHtml(a, stored);
    const observed = try a.alloc(?FloatingTableAnchor, stored.observed_nodes.len);
    for (observed, 0..) |*out, index| out.* = try floatingTableObservedAnchor(a, html, stored.observed_nodes, index);
    var result: std.ArrayList(SelectedFloatingTable) = .empty;
    var page_contexts: ?[]const FloatingTablePageContext = null;
    for (anchors) |anchor| {
        if (!floatingTableOrdinaryOpening(source, anchor.opening_start)) continue;
        var done = false;
        for (result.items) |known| if (known.opening_start == anchor.opening_start) { done = true; break; };
        if (done) continue;
        // Census every matching source/DOM occurrence before the physical-root
        // eligibility check. A matching nested/foreign Table cannot disappear.
        const owner = floatingTableObservedOwner(anchors, observed, anchor) orelse continue;
        if (stored.observed_nodes[owner].parent != 0) continue;
        if (page_contexts == null) {
            const existing = try floatingTableExistingContexts(a, figures);
            if (existing.len != 0) page_contexts = existing else {
                const complete = try a.alloc(FloatingTablePageContext, 2);
                for (complete, 0..) |*out, arm| {
                    const styles = try figureContextStyles(a, parent, stored, arm != 0);
                    out.* = .{ .styles = styles, .nodes = try figureObservedGraph(a, styles, stored, arm != 0), .root = @intCast(stored.outer.ancestors.len) };
                }
                page_contexts = complete;
            }
        }
        const root: u32 = @intCast(stored.outer.ancestors.len);
        const contexts = try a.alloc(profile.TableContainingDirectionContext, 2);
        const link_contexts = try a.alloc(profile.TableContainingDirectionContext, 2);
        for (contexts, 0..) |*out, arm| {
            const full = page_contexts.?[arm];
            const original = full.nodes;
            if (full.root != root or root + owner >= original.len) return invalid;
            const nodes = try a.alloc(profile.ObservedStyleNode, root + 2);
            @memcpy(nodes[0..root + 1], original[0..root + 1]);
            link_contexts[arm] = .{ .styles = full.styles, .nodes = original, .root = root, .table = @intCast(root + owner) };
            const table = original[root + owner];
            nodes[root + 1] = .{ .tag = table.tag, .attributes = table.attributes, .parent = root,
                .empty = table.empty, .has_text = table.has_text, .custom_environment = table.custom_environment };
            out.* = .{ .styles = full.styles, .nodes = nodes, .root = root, .table = root + 1 };
        }
        try result.append(a, .{ .opening_start = anchor.opening_start, .opening_end = anchor.opening_end, .contexts = contexts, .link_contexts = link_contexts, .page_contexts = page_contexts.? });
        if (result.items.len > 64) return invalid;
    }
    return result.toOwnedSlice(a);
}

fn intrinsicTableTextSignature(a: A, text: []const u8) ![]const u8 {
    var result: std.ArrayList(u8) = .empty;
    var space = false;
    for (text) |byte| {
        if (std.mem.indexOfScalar(u8, " \t\n\r\x0c", byte) != null) { space = result.items.len != 0; continue; }
        if (space) try result.append(a, ' ');
        space = false; try result.append(a, byte);
    }
    return result.toOwnedSlice(a);
}

fn intrinsicTableCapturedCellText(a: A, html: []const u8, node: ObservedSiblingNode) !?[]const u8 {
    if (!node.tag.is("td") and !node.tag.is("th")) return null;
    const end = node.inner_end orelse return null;
    if (node.tag.end > end or end > html.len) return null;
    var text: std.ArrayList(u8) = .empty;
    var at = node.tag.end;
    while (at < end) {
        if (html[at] == '<') {
            const tag = syntax.tagAt(html, at) orelse return null;
            if (tag.end > end or tag.isOpaque()) return null;
            if (tag.is("br") or tag.is("center")) try text.append(a, ' ');
            at = tag.end;
        } else {
            const stop = @min(std.mem.indexOfScalarPos(u8, html, at, '<') orelse end, end);
            const decoded = decodedAttribute(a, html[at..stop]) catch |err| switch (err) {
                error.OutOfMemory => return err, else => return null,
            };
            try text.appendSlice(a, decoded); at = stop;
        }
    }
    return try intrinsicTableTextSignature(a, text.items);
}

fn intrinsicTableDirectTextSignature(a: A, text: []const u8, leading: bool, trailing: bool) ![]const u8 {
    const spaces = " \t\n\r\x0c";
    var selected = text;
    if (leading) selected = std.mem.trimStart(u8, selected, spaces);
    if (trailing) selected = std.mem.trimEnd(u8, selected, spaces);
    var result: std.ArrayList(u8) = .empty;
    var space = false;
    for (selected) |byte| {
        const current = std.mem.indexOfScalar(u8, spaces, byte) != null;
        if (!current or !space) try result.append(a, if (current) ' ' else byte);
        space = current;
    }
    return result.toOwnedSlice(a);
}

fn intrinsicTableCapturedNodeEnd(html: []const u8, node: ObservedSiblingNode) ?usize {
    if (node.tag.is("br") or node.tag.is("wbr")) return node.tag.end;
    const inner_end = node.inner_end orelse return null;
    if (inner_end < node.tag.end or inner_end >= html.len) return null;
    const close = syntax.tagAt(html, inner_end) orelse return null;
    if (!close.closing or !std.ascii.eqlIgnoreCase(close.name, node.tag.name)) return null;
    return close.end;
}

fn intrinsicTableCapturedTextRunMatches(a: A, html: []const u8, nodes: []const ObservedSiblingNode,
    root: u32, cell: u32, run: compiler.Renderer.IntrinsicTableSourceTextRun) !bool
{
    if (cell < root or run.subject < cell or run.subject - root >= nodes.len) return false;
    const parent_index = run.subject - root;
    const parent = nodes[parent_index];
    // The witness must remain inside the particular matched real CELL.
    var ancestor: ?usize = parent_index; var depth: usize = 0;
    while (ancestor != cell - root) {
        const index = ancestor orelse return false;
        if (index >= nodes.len or depth == 16) return false;
        const next = nodes[index].parent orelse return false;
        if (next >= index) return false;
        ancestor = next; depth += 1;
    }
    const void_node = parent.tag.is("br") or parent.tag.is("wbr");
    const inner_end = if (void_node) parent.tag.end else parent.inner_end orelse return false;
    if (parent.tag.end > inner_end or inner_end > html.len) return false;
    var start = parent.tag.end;
    var end = inner_end;
    if (run.previous_child) |subject| {
        if (subject <= run.subject or subject < root or subject - root >= nodes.len) return false;
        const child = nodes[subject - root];
        if (child.parent != parent_index or child.start < parent.tag.end) return false;
        start = intrinsicTableCapturedNodeEnd(html, child) orelse return false;
    }
    if (run.next_child) |subject| {
        if (subject <= run.subject or subject < root or subject - root >= nodes.len) return false;
        const child = nodes[subject - root];
        if (child.parent != parent_index or child.start < parent.tag.end) return false;
        end = child.start;
    }
    if (start > end or end > inner_end or std.mem.indexOfScalar(u8, html[start..end], '<') != null) return false;
    const decoded = decodedAttribute(a, html[start..end]) catch |err| switch (err) {
        error.OutOfMemory => return err, else => return false,
    };
    // Only the outer CELL boundary may discard indentation/ending LF. A
    // space beside an inline child stays owned by its exact direct-text gap.
    const cell_boundary = run.subject == cell and (parent.tag.is("td") or parent.tag.is("th"));
    const leading = cell_boundary and run.previous_child == null;
    const trailing = cell_boundary and run.next_child == null;
    return equal(try intrinsicTableDirectTextSignature(a, run.text, leading, trailing),
        try intrinsicTableDirectTextSignature(a, decoded, leading, trailing));
}

fn intrinsicTableCapturedCellMatches(a: A, html: []const u8, nodes: []const ObservedSiblingNode,
    root: u32, cell: compiler.Renderer.IntrinsicTableSourceCellIdentity) !bool
{
    if (cell.subject < root or cell.subject - root >= nodes.len or cell.text_runs.len == 0) return false;
    const captured = (try intrinsicTableCapturedCellText(a, html, nodes[cell.subject - root])) orelse return false;
    if (!equal(try intrinsicTableTextSignature(a, cell.text), captured)) return false;
    for (cell.text_runs) |run| if (!try intrinsicTableCapturedTextRunMatches(a, html, nodes, root, cell.subject, run)) return false;
    return true;
}

fn intrinsicTableSourceOpenings(a: A, source: []const u8) ![]const usize {
    if (source.len > 4 * 1024 * 1024) return &.{};
    var result: std.ArrayList(usize) = .empty;
    var at: usize = 0; var scan: syntax.OpaqueScan = .{};
    while (at < source.len) {
        if (scan.protectedEnd(source, at, null)) |end| { at = end; continue; }
        if ((at == 0 or source[at - 1] == '\n') and std.mem.startsWith(u8, source[at..], "{|")) {
            if (result.items.len == 64) return &.{};
            try result.append(a, at); at += 2; continue;
        }
        if (source[at] == '<') {
            const tag = syntax.tagAt(source, at) orelse return &.{};
            at = tag.end; continue;
        }
        if (source[at] == '[' or source[at] == '{') {
            if (syntax.balanced(source, at)) |pair| { at = pair.end; continue; }
            if (std.mem.startsWith(u8, source[at..], "{{")) return &.{};
        }
        at += 1;
    }
    return result.toOwnedSlice(a);
}

// Reuse the selected diagnostic environment only in test builds. This does
// not turn a null compiler context into a source/ownership proof context.
extern "c" fn getenv(name: [*:0]const u8) ?[*:0]const u8;
fn intrinsicTableIssueTraceEnabled(context: compiler.Context) bool {
    if (!@import("builtin").is_test) return false;
    if (context.table_viewport_trace) return true;
    const raw = getenv("WIKIDICT_TABLE_VIEWPORT_TRACE") orelse return false;
    // Diagnostic parsing must not introduce a new issuer error or replace its
    // original result for malformed environment values.
    return compiler.tableViewportTraceEnabled(std.mem.span(raw)) catch false;
}

const IntrinsicTableIssueTrace = struct {
    enabled: bool,
    openings: usize = 0,
    captured_tables: usize = 0,
    geometry_refusals: usize = 0,
    candidates: usize = 0,
    opening: ?usize = null,
    candidate: ?u32 = null,
    head: ?usize = null,
    identity_calls: usize = 0,
    identity_refusals: usize = 0,
    captured_cell_checks: usize = 0,
    captured_cell_refusals: usize = 0,
    selected: usize = 0,
    last_pair_stage: []const u8 = "not_entered",

    fn refused(self: @This(), comptime stage: []const u8) []const SelectedFloatingTable {
        if (self.enabled) std.debug.print("KU_INTRINSIC_REFUSAL stage={s} openings={d} captured_tables={d} geometry_refusals={d} candidates={d} opening={any} candidate={any} head={any} identity_calls={d} identity_refusals={d} captured_cell_checks={d} captured_cell_refusals={d} selected={d} last_pair_stage={s}\n", .{
            stage, self.openings, self.captured_tables, self.geometry_refusals, self.candidates,
            self.opening, self.candidate, self.head, self.identity_calls, self.identity_refusals,
            self.captured_cell_checks, self.captured_cell_refusals, self.selected, self.last_pair_stage,
        });
        return &.{};
    }
};

fn selectIntrinsicTableStyles(a: A, ns: *const namespaces.Registry, parent: *const profile.Profile,
    stored: *const PageStyleData, source: []const u8, context: compiler.Context) ![]const SelectedFloatingTable
{
    var trace: IntrinsicTableIssueTrace = .{ .enabled = intrinsicTableIssueTraceEnabled(context) };
    if (stored.figure_alternative_sources == null) return trace.refused("alternative_sources");
    const openings = try intrinsicTableSourceOpenings(a, source);
    trace.openings = openings.len;
    if (openings.len == 0) return trace.refused("source_openings");
    var has_candidate = false;
    for (stored.observed_nodes) |node| if (node.tag.is("table") and node.attributes.get("border") != null and
        node.attributes.get("cellpadding") != null and node.attributes.get("cellspacing") != null) { has_candidate = true; break; };
    if (!has_candidate) return trace.refused("captured_family");
    const html = try selectedStoredHtml(a, stored);
    const root: u32 = @intCast(stored.outer.ancestors.len);
    const pages = try a.alloc(FloatingTablePageContext, 2);
    for (pages, 0..) |*out, arm| {
        const styles = try figureContextStyles(a, parent, stored, arm != 0);
        out.* = .{ .styles = styles, .nodes = try figureObservedGraph(a, styles, stored, arm != 0), .root = root };
    }
    var candidates: std.ArrayList(u32) = .empty;
    for (stored.observed_nodes, 0..) |node, index| {
        if (!node.tag.is("table")) continue;
        const full: profile.TableContainingDirectionContext = .{ .intrinsic_viewport = true,
            .styles = pages[0].styles, .nodes = pages[0].nodes, .root = root, .table = @intCast(root + index) };
        trace.captured_tables += 1;
        if (profile.observedIntrinsicTableGeometry(full) == null) { trace.geometry_refusals += 1; continue; }
        // A same-family nested/foreign owner must not vanish from the census.
        // This first source family admits only actual parser-root children.
        trace.candidate = @intCast(index);
        if (node.parent != 0 or candidates.items.len == 64) return trace.refused("candidate_parent_or_limit");
        try candidates.append(a, @intCast(index));
        trace.candidates = candidates.items.len;
    }
    if (candidates.items.len == 0) return trace.refused("candidate_geometry");
    var compile_context = context; compile_context.namespace_catalog = ns;
    // Forward only the existing diagnostic opt-in; source/proof context is unchanged.
    compile_context.table_viewport_trace = context.table_viewport_trace or trace.enabled;
    const counts = try a.alloc(usize, candidates.items.len); @memset(counts, 0);
    var selected: std.ArrayList(SelectedFloatingTable) = .empty;
    for (openings) |opening| {
        trace.opening = opening; trace.candidate = null; trace.head = null;
        const opening_end = std.mem.indexOfScalarPos(u8, source, opening, '\n') orelse return trace.refused("opening_line");
        const tag: syntax.Tag = .{ .name = "table", .attrs = std.mem.trimEnd(u8, source[opening + 2 .. opening_end], "\r"),
            .end = opening_end, .closing = false, .self_closing = false };
        const attrs = inventory(a, tag) catch |err| switch (err) { error.OutOfMemory => return err, else => return trace.refused("opening_attributes") };
        if (profile.intrinsicTableLegacyGeometry(try figureObservedAttributes(a, attrs)) == null) { trace.last_pair_stage = "source_geometry"; continue; }
        var owner: ?usize = null;
        for (candidates.items, 0..) |index, ordinal| {
            trace.candidate = index;
            var both = true;
            for (pages, 0..) |page, head| {
                trace.head = head;
                trace.identity_calls += 1;
                const full: profile.TableContainingDirectionContext = .{ .intrinsic_viewport = true,
                    .styles = page.styles, .nodes = page.nodes, .root = root, .table = root + index };
                const cells = (compiler.Renderer.intrinsicTableIdentityAlloc(a, source, opening, compile_context, full)
                    catch |err| switch (err) { error.OutOfMemory => return err, else => null }) orelse {
                    trace.identity_refusals += 1; trace.last_pair_stage = "source_identity";
                    both = false; break;
                };
                for (cells) |cell| {
                    trace.captured_cell_checks += 1;
                    if (!try intrinsicTableCapturedCellMatches(a, html, stored.observed_nodes, root, cell)) {
                        trace.captured_cell_refusals += 1; trace.last_pair_stage = "captured_cell_body";
                        both = false; break;
                    }
                }
                if (!both) break;
            }
            if (!both) continue;
            counts[ordinal] += 1;
            if (owner != null) return trace.refused("ambiguous_source_owner");
            owner = ordinal;
        }
        const ordinal = owner orelse return trace.refused("source_owner");
        const captured_index = candidates.items[ordinal];
        if (!floatingTableOrdinaryOpening(source, opening)) return trace.refused("ordinary_opening");
        const contexts = try a.alloc(profile.TableContainingDirectionContext, 2);
        const links = try a.alloc(profile.TableContainingDirectionContext, 2);
        for (pages, 0..) |page, arm| {
            const table = page.nodes[root + captured_index];
            const nodes = try a.alloc(profile.ObservedStyleNode, root + 2);
            @memcpy(nodes[0 .. root + 1], page.nodes[0 .. root + 1]);
            nodes[root + 1] = table;
            nodes[root + 1].known_previous_element_sibling = null;
            nodes[root + 1].known_next_element_sibling = null;
            nodes[root + 1].known_no_previous_element_sibling = false;
            nodes[root + 1].known_no_next_element_sibling = false;
            contexts[arm] = .{ .intrinsic_viewport = true, .styles = page.styles, .nodes = nodes, .root = root, .table = root + 1 };
            links[arm] = .{ .intrinsic_viewport = true, .styles = page.styles, .nodes = page.nodes, .root = root, .table = root + captured_index };
        }
        const end = std.mem.indexOfScalarPos(u8, source, opening, '\n') orelse return trace.refused("selected_opening_line");
        try selected.append(a, .{ .opening_start = opening, .opening_end = end,
            .contexts = contexts, .link_contexts = links, .page_contexts = pages });
        trace.selected = selected.items.len;
    }
    // Bijection, not ordinal pairing: every captured family member has one
    // complete source body and vice versa, across both authenticated heads.
    if (selected.items.len != candidates.items.len) return trace.refused("complete_bijection_count");
    for (counts) |count| if (count != 1) return trace.refused("complete_bijection_multiplicity");
    return selected.toOwnedSlice(a);
}

const InlineMissingProof = struct {
    token: []const u8, file: []const u8, label: []const u8, href: []const u8, title: []const u8, width: u32,
    table_opening: []const u8, row_opening: []const u8, cell_opening: []const u8,
    contexts: []const profile.InlineMissingContext,
};

fn inlineMissingLiteralParents(a: A, source: []const u8, start: usize, end: usize) !?struct {
    table: []const u8, row: []const u8, cell: []const u8,
    table_attributes: Inventory, row_attributes: Inventory, cell_attributes: Inventory,
} {
    if (start >= end or end > source.len) return null;
    var table: ?struct { start: usize, tag: syntax.Tag, pair: syntax.Pair } = null;
    var row: ?struct { start: usize, tag: syntax.Tag, pair: syntax.Pair } = null;
    var cell: ?struct { start: usize, tag: syntax.Tag, pair: syntax.Pair } = null;
    var cursor: usize = 0; var remaining: usize = 4096;
    while (std.mem.indexOfScalarPos(u8, source, cursor, '<')) |at| {
        if (at >= start) break;
        if (remaining == 0) return null;
        remaining -= 1;
        const tag = syntax.tagAt(source, at) orelse { cursor = at + 1; continue; };
        cursor = tag.end;
        if (tag.closing or tag.self_closing) continue;
        const pair = syntax.matchingTag(source, tag) orelse continue;
        if (!(tag.end <= start and pair.inner_end >= end)) continue;
        if (tag.isOpaque()) return null;
        if (tag.is("table")) {
            if (table != null) return null;
            table = .{ .start = at, .tag = tag, .pair = pair };
        } else if (tag.is("tr")) {
            if (row != null) return null;
            row = .{ .start = at, .tag = tag, .pair = pair };
        } else if (tag.is("td")) {
            if (cell != null) return null;
            cell = .{ .start = at, .tag = tag, .pair = pair };
        } else if (cell != null or row != null or table != null) return null;
    }
    const t = table orelse return null; const r = row orelse return null; const c = cell orelse return null;
    if (t.tag.end > r.start or r.pair.end > t.pair.inner_end or r.tag.end > c.start or c.pair.end > r.pair.inner_end or
        std.mem.trim(u8, source[c.tag.end..start], " \t\r\n").len != 0 or
        std.mem.trim(u8, source[end..c.pair.inner_end], " \t\r\n").len != 0) return null;
    const table_attributes = inventory(a, t.tag) catch |err| switch (err) { error.OutOfMemory => return error.OutOfMemory, else => return null };
    const row_attributes = inventory(a, r.tag) catch |err| switch (err) { error.OutOfMemory => return error.OutOfMemory, else => return null };
    const cell_attributes = inventory(a, c.tag) catch |err| switch (err) { error.OutOfMemory => return error.OutOfMemory, else => return null };
    for ([_]Inventory{table_attributes, row_attributes, cell_attributes}) |attributes| for (attributes.attributes) |attribute| {
        if (!equal(attribute.name, "class") and !equal(attribute.name, "id") and !equal(attribute.name, "style") and
            !equal(attribute.name, "lang") and !equal(attribute.name, "dir")) return null;
    };
    return .{ .table = source[t.start..t.tag.end], .row = source[r.start..r.tag.end], .cell = source[c.start..c.tag.end],
        .table_attributes = table_attributes, .row_attributes = row_attributes, .cell_attributes = cell_attributes };
}

fn selectInlineMissingStyles(a: A, ns: *const namespaces.Registry, registry: ?*const sizing.Registry,
    parent: *const profile.Profile, stored: *const PageStyleData, source: []const u8, selected_context: ?compiler.Context) ![]const InlineMissingProof
{
    const context = selected_context orelse return &.{};
    const files = registry orelse return &.{};
    if (!files.file_authority or !std.mem.eql(u8, &files.namespace_catalog.source_sha256, &ns.source_sha256) or
        context.namespace_catalog != ns or context.image_options == null or context.figure_sizing == null or
        (context.figure_sizing.?.source_context orelse return &.{}).missing_media_profile != .f45897 or stored.observed_nodes.len > 512) return &.{};
    var result: std.ArrayList(InlineMissingProof) = .empty; defer result.deinit(a);
    var primary_styles: ?*const profile.Profile = null; var alternative_styles: ?*const profile.Profile = null;
    var primary: ?[]profile.FigureObservedNode = null; var alternative: ?[]profile.FigureObservedNode = null;
    const shift: u32 = @intCast(stored.outer.ancestors.len);
    const html = stored.observed_html; const nodes = stored.observed_nodes;
    for (nodes, 0..) |label_node, label_index| {
        if (!label_node.tag.is("span") or !equal(label_node.attributes.get("class") orelse "", "mw-file-element mw-broken-media")) continue;
        const anchor_index = label_node.parent orelse continue; const anchor = nodes[anchor_index];
        const wrapper_index = anchor.parent orelse continue; const wrapper = nodes[wrapper_index];
        if (!wrapper.tag.is("span") or !equal(wrapper.attributes.get("typeof") orelse "", "mw:Error mw:File")) continue;
        if (!anchor.tag.is("a") or !equal(anchor.attributes.get("class") orelse "", "new") or
            wrapper.attributes.attributes.len != 1 or anchor.attributes.attributes.len != 3 or label_node.attributes.attributes.len != 2 or
            wrapper.first_child != anchor_index or anchor.first_child != label_index or label_node.first_child != null or
            anchor.previous != null or label_node.previous != null or wrapper.tag.end != anchor.start or anchor.tag.end != label_node.start) continue;
        const label_end = label_node.inner_end orelse continue;
        const label_close = syntax.tagAt(html, label_end) orelse continue;
        const anchor_close = syntax.tagAt(html, anchor.inner_end orelse continue) orelse continue;
        const wrapper_close = syntax.tagAt(html, wrapper.inner_end orelse continue) orelse continue;
        if (!label_close.closing or !label_close.is("span") or label_close.end != anchor.inner_end or
            !anchor_close.closing or !anchor_close.is("a") or anchor_close.end != wrapper.inner_end or
            !wrapper_close.closing or !wrapper_close.is("span")) continue;
        const cell_index = wrapper.parent orelse continue; const cell = nodes[cell_index];
        const row_index = cell.parent orelse continue; const row = nodes[row_index];
        const group_index = row.parent orelse continue; const group = nodes[group_index];
        const table_index = group.parent orelse continue; const table = nodes[table_index];
        if (!cell.tag.is("td") or !row.tag.is("tr") or !group.tag.is("tbody") or !table.tag.is("table") or
            group.attributes.attributes.len != 0 or cell.first_child != wrapper_index or wrapper.previous != null or
            std.mem.trim(u8, html[cell.tag.end..wrapper.start], " \t\r\n").len != 0 or
            std.mem.trim(u8, html[wrapper_close.end..cell.inner_end orelse continue], " \t\r\n").len != 0) continue;
        const file = (try missingAnchorFile(a, ns, anchor.attributes)) orelse continue;
        if (!try sizing.Registry.isMissingFile(files, a, file)) continue;
        const label = try decodedAttribute(a, html[label_node.tag.end..label_end]);
        const width = positiveAttribute(label_node.attributes, "data-width") catch continue;
        const href = anchor.attributes.get("href") orelse continue;
        if (label.len == 0 or std.mem.indexOfAny(u8, label, "\x00\r\n\t<>&[]{}") != null or
            (!std.mem.startsWith(u8, href, "//") and !std.mem.startsWith(u8, href, "https://"))) continue;
        var token_start: ?usize = null; var token_end: usize = 0; var options: []const u8 = "";
        var scan: usize = 0; var count: usize = 0; var examined: usize = 0;
        while (std.mem.indexOfPos(u8, source, scan, "[[")) |start| {
            scan = start + 2; examined += 1; if (examined > 16384) return invalid;
            var iterator: encoder.document_ir.InlineIterator = .{ .input = source, .cursor = start, .renderer_boundaries = true };
            const node = iterator.next() orelse continue;
            if (node.kind != .link) continue;
            const target = (try compiler.figureObservationFileTargetAlloc(a, node.target, context)) orelse continue;
            const canonical = canonicalFile(a, ns, target) catch |err| switch (err) { error.OutOfMemory => return error.OutOfMemory, else => continue };
            if (!equal(canonical, file)) continue;
            count += 1;
            if (!node.link_has_pipe or node.link_empty_label or node.link_label_restored_close or node.trail.len != 0) continue;
            token_start = start; token_end = iterator.cursor; options = node.text;
        }
        if (count != 1) continue;
        const start = token_start orelse continue;
        const parsed = compiler.inlineMissingOptions(options, context) orelse continue;
        if (parsed.width != width or !equal(parsed.label, label)) continue;
        const parents = (try inlineMissingLiteralParents(a, source, start, token_end)) orelse continue;
        if (!outerSameAttributes(parents.cell_attributes, cell.attributes, false) or
            !outerSameAttributes(parents.row_attributes, row.attributes, false) or
            !outerSameAttributes(parents.table_attributes, table.attributes, false)) continue;
        // A unique source operation must also have a unique captured action:
        // identical-file siblings cannot borrow each other's parent or label.
        var captured_count: usize = 0;
        for (nodes) |candidate| if (candidate.tag.is("a")) {
            const owner = candidate.parent orelse continue;
            if (!nodes[owner].tag.is("span") or
                !profile.Profile.hasClass(nodes[owner].attributes.get("typeof") orelse "", "mw:Error") or
                !profile.Profile.hasClass(nodes[owner].attributes.get("typeof") orelse "", "mw:File")) continue;
            if (try missingAnchorFile(a, ns, candidate.attributes)) |canonical| if (equal(canonical, file)) { captured_count += 1; };
        };
        if (captured_count != 1) continue;
        if (primary == null) {
            primary_styles = try figureContextStyles(a, parent, stored, false);
            alternative_styles = try figureContextStyles(a, parent, stored, true);
            primary = try figureObservedGraph(a, primary_styles.?, stored, false);
            alternative = try figureObservedGraph(a, alternative_styles.?, stored, true);
        }
        const contexts = try a.alloc(profile.InlineMissingContext, 2);
        for ([_][]profile.FigureObservedNode{ primary.?, alternative.? }, 0..) |graph, arm| {
            contexts[arm] = .{ .styles = if (arm == 0) primary_styles.? else alternative_styles.?, .nodes = graph,
                .root = shift, .wrapper = shift + @as(u32, @intCast(wrapper_index)), .anchor = shift + @as(u32, @intCast(anchor_index)),
                .label = shift + @as(u32, @intCast(label_index)) };
        }
        if (!profile.inlineMissingContextValid(contexts[0]) or !profile.inlineMissingContextValid(contexts[1])) continue;
        try result.append(a, .{ .token = source[start..token_end], .file = file, .label = label, .href = href, .title = anchor.attributes.get("title").?, .width = width,
            .table_opening = parents.table, .row_opening = parents.row, .cell_opening = parents.cell, .contexts = contexts });
        if (result.items.len > 64) return invalid;
    }
    return result.toOwnedSlice(a);
}

const OrdinaryActionGroupSpelling = struct {
    external_source: bool,
    explicit_label: bool,
    target: []const u8,
    label: []const u8,
    trail: []const u8,
};

// A complete ordinary operation includes its link trail. The normal tokenizer
// and namespace resolver retain ownership of spelling and destination rules.
fn ordinaryActionGroupSpelling(a: A, selected: *const SelectedPageStyles,
    operation: compiler.OrdinaryActionGroupOperation) !?OrdinaryActionGroupSpelling
{
    const owner = selected.ordinary_link_page orelse return null;
    const start = std.math.sub(usize, @intFromPtr(operation.token.ptr), @intFromPtr(selected.source.ptr)) catch return null;
    if (operation.token.len == 0 or start >= selected.source.len or operation.token.len > selected.source.len - start or
        !equal(operation.token, selected.source[start..][0..operation.token.len])) return null;
    var parser: encoder.document_ir.InlineIterator = .{ .input = selected.source[start..],
        .renderer_boundaries = true, .link_trail = owner.context.link_trail };
    const item = parser.next() orelse return null;
    if (parser.cursor != operation.token.len or item.target.len == 0) return null;
    if (item.kind == .link) {
        const pair = syntax.balanced(operation.token, 0) orelse return null;
        if (item.link_empty_label or item.link_label_restored_close or pair.end > operation.token.len or
            pair.end + item.trail.len != operation.token.len) return null;
        const destination = (try compiler.literalSourceLinkDestinationAlloc(a, selected.namespace_catalog, item.target)) orelse return null;
        if (!equal(destination.target, operation.target) or destination.external != operation.external or
            operation.interwiki != destination.external) return null;
        return .{ .external_source = false, .explicit_label = item.link_has_pipe,
            .target = item.target, .label = item.text, .trail = item.trail };
    }
    if (item.kind != .external_link or !operation.external or operation.interwiki or item.trail.len != 0 or
        item.external_label_prefix.len != 0 or !equal(item.target, operation.target) or
        !encoder.document_ir.validExternalUrl(item.target) or
        std.mem.indexOfAny(u8, item.target, "<>\\\x00\r\n\t ") != null) return null;
    const explicit_label = item.text.ptr != item.target.ptr;
    if (explicit_label and (item.text.len == 0 or operation.token[0] != '[' or operation.token[operation.token.len - 1] != ']')) return null;
    return .{ .external_source = true, .explicit_label = explicit_label,
        .target = item.target, .label = item.text, .trail = "" };
}

fn ordinaryActionGroupExternalHref(source: []const u8, explicit_label: bool, attrs: Inventory) ?[]const u8 {
    const href = attrs.get("href") orelse return null;
    if (!equal(attrs.get("class") orelse return null, if (explicit_label) "external text" else "external free")) return null;
    if (attrs.get("rel")) |rel| if (!equal(rel, "nofollow")) return null;
    for (attrs.attributes) |attribute| {
        if (!equal(attribute.name, "href") and !equal(attribute.name, "class") and
            !equal(attribute.name, "rel") and !equal(attribute.name, "data-mw-original-href")) return null;
    }
    const original = attrs.get("data-mw-original-href");
    if (equal(href, source)) {
        if (original) |value| if (!equal(value, source)) return null;
        return href;
    }
    // This is the same literal upgrade witness used by selectedGetBareLinkEnd.
    // No host, path, query, fragment, or percent-decoding rewrite is inferred.
    if (!std.mem.startsWith(u8, source, "http://") or !std.mem.startsWith(u8, href, "https://") or
        !equal(href[8..], source[7..]) or !equal(original orelse return null, source)) return null;
    return href;
}

fn ordinaryActionGroupCapturedTarget(a: A, selected: *const SelectedPageStyles,
    operation: compiler.OrdinaryActionGroupOperation, spelling: OrdinaryActionGroupSpelling,
    node: ObservedSiblingNode, html: []const u8) !?[]const u8
{
    if (!node.tag.is("a") or node.tag.closing or node.tag.self_closing or node.inner_end == null) return null;
    const pair = syntax.matchingTag(html, node.tag) orelse return null;
    const closing = currentLiteralHtmlTagAt(html, pair.inner_end) orelse return null;
    if (node.start >= pair.end or pair.end > html.len or node.inner_end.? != pair.inner_end or
        !closing.closing or closing.attrs.len != 0) return null;
    const owner = selected.ordinary_link_page orelse return null;
    if (!spelling.external_source) {
        if (!try noteInlineCorrespondsIn(a, selected.namespace_catalog, operation.token, html[node.start..pair.end],
            0, false, true, owner.context, null)) return null;
        return operation.target;
    }
    const href = ordinaryActionGroupExternalHref(spelling.target, spelling.explicit_label, node.attributes) orelse return null;
    if (spelling.explicit_label) {
        if (!try noteInlineCorrespondsIn(a, selected.namespace_catalog, spelling.label,
            html[node.tag.end..pair.inner_end], 0, true, true, owner.context, null)) return null;
    } else {
        if (node.first_child != null) return null;
        const label = decodedAttribute(a, html[node.tag.end..pair.inner_end]) catch |err| switch (err) {
            error.OutOfMemory => return err, else => return null,
        };
        if (!equal(label, spelling.label) or !equal(spelling.label, spelling.target)) return null;
    }
    return href;
}

// Only the neutral inline descendants admitted by the current rich sampler are
// flattened here. Ruby, script metrics, media and line breaks need their own
// structured correspondence and are deliberately not reduced to plain text.
fn ordinaryActionGroupCapturedText(a: A, raw: []const u8) !?[]const u8 {
    if (raw.len > 65536) return null;
    var out: std.ArrayList(u8) = .empty;
    defer out.deinit(a);
    var at: usize = 0;
    var depth: usize = 0;
    while (at < raw.len) {
        if (raw[at] == '<') {
            const tag = currentLiteralHtmlTagAt(raw, at) orelse return null;
            var supported = false;
            for ([_][]const u8{ "b", "strong", "i", "em", "span" }) |name| if (tag.is(name)) { supported = true; break; };
            if (!supported or tag.self_closing) return null;
            if (tag.closing) {
                if (depth == 0 or tag.attrs.len != 0) return null;
                depth -= 1;
            } else {
                if (depth == 16) return null;
                _ = syntax.matchingTag(raw, tag) orelse return null;
                depth += 1;
            }
            at = tag.end;
        } else {
            const end = std.mem.indexOfScalarPos(u8, raw, at, '<') orelse raw.len;
            const value = decodedAttribute(a, raw[at..end]) catch |err| switch (err) {
                error.OutOfMemory => return err, else => return null,
            };
            if (!std.unicode.utf8ValidateSlice(value) or std.mem.indexOfAny(u8, value, "\x00\r\n\t\x0c") != null) return null;
            try out.appendSlice(a, value);
            at = end;
        }
    }
    if (depth != 0 or out.items.len == 0) return null;
    return try out.toOwnedSlice(a);
}

fn ordinaryActionGroupStyleClone(a: A, original: profile.ObservedPlainInlineLinkStyle) !profile.ObservedPlainInlineLinkStyle {
    var result = original;
    result.font.language = try a.dupe(u8, original.font.language);
    result.font.classes = try a.dupe(u8, original.font.classes);
    if (original.font.font_family) |family| switch (family) {
        .sans_serif => {},
        .stack => |stack| {
            var copied = stack;
            const names = try a.alloc([]const u8, stack.names.len);
            for (names, stack.names) |*name, source| name.* = try a.dupe(u8, source);
            copied.names = names;
            result.font.font_family = .{ .stack = copied };
        },
    };
    inline for (.{ "normal", "hover", "active", "hover_active", "visited", "visited_hover", "visited_active", "visited_hover_active" }) |name|
        @field(result.paint, name).foreground = try a.dupe(u8, @field(original.paint, name).foreground);
    if (original.paint.focus_outline) |outline| {
        if (outline.color.value) |value| result.paint.focus_outline.?.color.value = try a.dupe(u8, value);
    }
    return result;
}

const OrdinaryActionGroupSupSource = struct {
    token: []const u8,
    opening_len: usize,
    body_len: usize,
    classes: []const u8,
};

fn ordinaryActionGroupSupSource(a: A, operation: compiler.OrdinaryActionGroupOperation,
    spelling: OrdinaryActionGroupSpelling) !?OrdinaryActionGroupSupSource
{
    if (spelling.trail.len != 0 or spelling.label.len == 0 or spelling.label[0] != '<') return null;
    const tag = syntax.tagAt(spelling.label, 0) orelse return null;
    if (!tag.is("sup") or tag.closing or tag.self_closing) return null;
    const pair = syntax.matchingTag(spelling.label, tag) orelse return null;
    if (pair.end != spelling.label.len or pair.inner_end <= tag.end) return null;
    const closing = syntax.tagAt(spelling.label, pair.inner_end) orelse return null;
    if (!closing.closing or closing.attrs.len != 0) return null;
    const start = @intFromPtr(spelling.label.ptr);
    const base = @intFromPtr(operation.token.ptr);
    if (start < base or start - base > operation.token.len or spelling.label.len > operation.token.len - (start - base)) return null;
    const attrs = (try siblingSourceAttributes(a, tag)) orelse return null;
    for (attrs.attributes) |attribute| if (!equal(attribute.name, "class")) return null;
    const body = spelling.label[tag.end..pair.inner_end];
    // This receipt is the complete text-only SUP body. Nested HTML, wiki
    // actions, formatting markers and generated constructs retain their routes.
    if (std.mem.indexOfAny(u8, body, "<>[]{}\r\n\t\x0c") != null or std.mem.indexOf(u8, body, "''") != null) return null;
    const text_value = (try ordinaryActionGroupCapturedText(a, body)) orelse return null;
    if (std.mem.trim(u8, text_value, " \t\r\n").len == 0) return null;
    return .{ .token = spelling.label, .opening_len = tag.end, .body_len = pair.inner_end - tag.end,
        .classes = attrs.get("class") orelse "" };
}

fn ordinaryActionGroupFontEqual(left: encoder.presentation_types.InlineFontSnapshot,
    right: encoder.presentation_types.InlineFontSnapshot) bool
{
    if (!equal(left.language, right.language) or !equal(left.classes, right.classes) or
        (left.font_family == null) != (right.font_family == null)) return false;
    if (left.font_family) |family| {
        const other = right.font_family.?;
        if (std.meta.activeTag(family) != std.meta.activeTag(other)) return false;
        switch (family) {
            .sans_serif => {},
            .stack => |stack| {
                if (stack.fallback != other.stack.fallback or stack.names.len != other.stack.names.len) return false;
                for (stack.names, other.stack.names) |one, two| if (!equal(one, two)) return false;
            },
        }
    }
    var normalized = left;
    normalized.language = right.language;
    normalized.classes = right.classes;
    normalized.font_family = right.font_family;
    return std.meta.eql(normalized, right);
}

fn ordinaryActionGroupFontClone(a: A, original: encoder.presentation_types.InlineFontSnapshot) !encoder.presentation_types.InlineFontSnapshot {
    var result = original;
    result.language = try a.dupe(u8, original.language);
    result.classes = try a.dupe(u8, original.classes);
    if (original.font_family) |family| switch (family) {
        .sans_serif => {},
        .stack => |stack| {
            var copied = stack;
            const names = try a.alloc([]const u8, stack.names.len);
            for (names, stack.names) |*name, source| name.* = try a.dupe(u8, source);
            copied.names = names;
            result.font_family = .{ .stack = copied };
        },
    };
    return result;
}

fn ordinaryActionGroupSupClasses(actual: []const u8, source_classes: []const u8, interwiki: bool) bool {
    var values = std.mem.tokenizeAny(u8, actual, " \t\r\n\x0c");
    while (values.next()) |value| if (!(interwiki and equal(value, "extiw")) and !profile.Profile.hasClass(source_classes, value)) return false;
    values = std.mem.tokenizeAny(u8, source_classes, " \t\r\n\x0c");
    while (values.next()) |value| if (!profile.Profile.hasClass(actual, value)) return false;
    return !interwiki or profile.Profile.hasClass(actual, "extiw");
}

fn ordinaryActionGroupSupFont(actual: encoder.presentation_types.InlineFontSnapshot,
    parent: encoder.presentation_types.InlineFontSnapshot, source_classes: []const u8, interwiki: bool) bool
{
    if (!encoder.presentation_types.validInlineFontSnapshot(actual) or !encoder.presentation_types.validInlineFontSnapshot(parent) or
        !actual.superscript or actual.subscript or actual.small or actual.code or !actual.font_normalized or
        parent.superscript or parent.subscript or parent.small or parent.code or !parent.font_normalized or parent.classes.len != 0 or
        !ordinaryActionGroupSupClasses(actual.classes, source_classes, interwiki)) return false;
    var css_base = actual;
    css_base.superscript = false;
    css_base.classes = parent.classes;
    return ordinaryActionGroupFontEqual(css_base, parent);
}

fn ordinaryActionGroupLineHeightEqual(left: profile.AuthoredElementLineHeight, right: profile.AuthoredElementLineHeight) bool {
    if (std.meta.activeTag(left) != std.meta.activeTag(right)) return false;
    return switch (left) {
        .multiplier => |value| std.math.isFinite(value) and value >= 0 and value == right.multiplier,
        .font_relative => |value| std.math.isFinite(value) and value >= 0 and value == right.font_relative,
        else => false,
    };
}

const OrdinaryPlainLinkPage = struct {
    // Selection-owned storage outlives every temporary observation Renderer.
    // Callback allocators may be destroyed before final page compilation.
    allocator: A,
    stored: *const PageStyleData,
    parent: *const profile.Profile,
    selected_profile: *const profile.Profile,
    context: compiler.Context,
    original_source: []const u8,
    namespace_sha256: [32]u8,
    contexts: ?[]const profile.ObservedInlineLinkPaintContext = null,
    html: ?[]const u8 = null,
    cache: std.ArrayList(Entry) = .empty,
    action_group_parent_snapshot: ?profile.ObservedStyleInventorySnapshot = null,
    action_group_selected_snapshot: ?profile.ObservedStyleInventorySnapshot = null,
    action_group_entries: std.ArrayList(*ActionGroupEntry) = .empty,
    action_group_context_snapshots: []const ActionGroupContextSnapshot = &.{},
    focus_capture: ?FocusCapture = null,
    const ActionGroupEntry = struct {
        token: []const u8,
        native_target: []const u8,
        external: bool,
        interwiki: bool,
        source_image: *const profile.PageSourceImage,
        source_snapshot: []const u8,
        observation: compiler.OrdinaryActionGroupObservation,
        script: ?*ActionGroupScriptEntry = null,
    };

    const ActionGroupScriptEntry = struct {
        source: OrdinaryActionGroupSupSource,
        declaring_parent_font: encoder.presentation_types.InlineFontSnapshot,
        line_height: profile.AuthoredElementLineHeight,
    };

    fn actionGroupContextsCurrent(self: *const OrdinaryPlainLinkPage) bool {
        const parent = self.action_group_parent_snapshot orelse return false;
        const selected = self.action_group_selected_snapshot orelse return false;
        return parent.current() and selected.current() and self.actionGroupGraphsCurrent();
    }

    const ActionGroupContextSnapshot = struct {
        context: profile.ObservedInlineLinkPaintContext,
        styles: profile.ObservedStyleInventorySnapshot,
        nodes: []const profile.ObservedStyleNode,
    };

    fn captureActionGroupContexts(self: *OrdinaryPlainLinkPage) !void {
        if (self.action_group_parent_snapshot != null or self.action_group_selected_snapshot != null or
            self.action_group_context_snapshots.len != 0) return invalid;
        const contexts = self.contexts orelse return invalid;
        if (contexts.len != 2) return invalid;
        const a = self.allocator;
        var parent = try profile.ObservedStyleInventorySnapshot.init(a, self.parent);
        errdefer parent.deinit();
        var selected = try profile.ObservedStyleInventorySnapshot.init(a, self.selected_profile);
        errdefer selected.deinit();
        const copies = try a.alloc(ActionGroupContextSnapshot, contexts.len);
        var initialized: usize = 0;
        errdefer for (copies[0..initialized]) |*copy| copy.styles.deinit();
        for (contexts, copies) |context, *copy| {
            var styles = try profile.ObservedStyleInventorySnapshot.init(a, context.styles);
            errdefer styles.deinit();
            const nodes = try a.dupe(profile.ObservedStyleNode, context.nodes);
            for (context.nodes, nodes) |node, *out| {
                out.tag = try a.dupe(u8, node.tag);
                const attributes = try a.alloc(profile.FigureObservedAttribute, node.attributes.len);
                for (node.attributes, attributes) |attribute, *result| result.* = .{
                    .name = try a.dupe(u8, attribute.name), .value = try a.dupe(u8, attribute.value) };
                out.attributes = attributes;
                if (node.captured_entity_text) |value| out.captured_entity_text = try a.dupe(u8, value);
                if (node.custom_environment) |environment| {
                    const values = try a.alloc(profile.CustomBinding, environment.values.len);
                    for (environment.values, values) |entry, *result| {
                        result.* = .{ .name = try a.dupe(u8, entry.name), .value = entry.value };
                        if (entry.value == .known) result.value = .{ .known = try a.dupe(u8, entry.value.known) };
                    }
                    out.custom_environment = .{ .complete = environment.complete, .values = values };
                }
            }
            copy.* = .{ .context = context, .styles = styles, .nodes = nodes };
            initialized += 1;
        }
        self.action_group_parent_snapshot = parent;
        self.action_group_selected_snapshot = selected;
        self.action_group_context_snapshots = copies;
    }

    fn actionGroupGraphsCurrent(self: *const OrdinaryPlainLinkPage) bool {
        const contexts = self.contexts orelse return false;
        const snapshots = self.action_group_context_snapshots;
        if (snapshots.len != 2 or contexts.len != snapshots.len) return false;
        for (contexts, snapshots) |context, snapshot| {
            if (context.styles != snapshot.context.styles or context.root != snapshot.context.root or
                context.nodes.ptr != snapshot.context.nodes.ptr or context.nodes.len != snapshot.nodes.len or
                !snapshot.styles.current()) return false;
            for (context.nodes, snapshot.nodes) |actual, expected| {
                if (!equal(actual.tag, expected.tag) or actual.attributes.len != expected.attributes.len) return false;
                for (actual.attributes, expected.attributes) |left, right|
                    if (!equal(left.name, right.name) or !equal(left.value, right.value)) return false;
                if ((actual.captured_entity_text == null) != (expected.captured_entity_text == null) or
                    (actual.captured_entity_text != null and !equal(actual.captured_entity_text.?, expected.captured_entity_text.?))) return false;
                if ((actual.custom_environment == null) != (expected.custom_environment == null)) return false;
                if (actual.custom_environment) |left| {
                    const right = expected.custom_environment.?;
                    if (left.complete != right.complete or left.values.len != right.values.len) return false;
                    for (left.values, right.values) |l, r| {
                        if (!equal(l.name, r.name) or std.meta.activeTag(l.value) != std.meta.activeTag(r.value)) return false;
                        if (l.value == .known and !equal(l.value.known, r.value.known)) return false;
                    }
                }
                var normalized = actual;
                normalized.tag = expected.tag;
                normalized.attributes = expected.attributes;
                normalized.captured_entity_text = expected.captured_entity_text;
                normalized.custom_environment = expected.custom_environment;
                if (!std.meta.eql(normalized, expected)) return false;
            }
        }
        return true;
    }

    const FocusCapture = struct {
        html: []const u8,
        original_html: []const u8,
        live_nodes: []const ObservedSiblingNode,
        nodes: []const ObservedSiblingNode,
    };

    fn captureFocus(self: *OrdinaryPlainLinkPage) !void {
        const a = self.allocator;
        const html = self.html orelse return invalid;
        const nodes = try a.dupe(ObservedSiblingNode, self.stored.observed_nodes);
        for (nodes) |*node| {
            const attributes = try a.alloc(Attribute, node.attributes.attributes.len);
            for (node.attributes.attributes, attributes) |attribute, *out| out.* = .{
                .name = try a.dupe(u8, attribute.name), .value = try a.dupe(u8, attribute.value) };
            node.attributes = .{ .attributes = attributes };
        }
        self.focus_capture = .{ .html = html, .original_html = try a.dupe(u8, html),
            .live_nodes = self.stored.observed_nodes, .nodes = nodes };
    }

    fn focusCurrent(self: *const OrdinaryPlainLinkPage) bool {
        const snapshot = self.focus_capture orelse return false;
        const html = self.html orelse return false;
        const nodes = self.stored.observed_nodes;
        if (html.ptr != snapshot.html.ptr or html.len != snapshot.html.len or !equal(html, snapshot.original_html) or
            nodes.ptr != snapshot.live_nodes.ptr or nodes.len != snapshot.nodes.len) return false;
        for (nodes, snapshot.nodes) |actual, expected| {
            if (!std.meta.eql(actual.tag, expected.tag) or actual.start != expected.start or
                actual.parent != expected.parent or actual.previous != expected.previous or
                actual.first_child != expected.first_child or actual.inner_end != expected.inner_end or
                actual.attributes.attributes.len != expected.attributes.attributes.len) return false;
            for (actual.attributes.attributes, expected.attributes.attributes) |left, right|
                if (!equal(left.name, right.name) or !equal(left.value, right.value)) return false;
        }
        return true;
    }

    const Entry = struct { token: []const u8, target: []const u8, observation: compiler.OrdinaryLinkPaintObservation };

    fn create(a: A, ns: *const namespaces.Registry, parent: *const profile.Profile, selected: *const profile.Profile,
        stored: *const PageStyleData, source: []const u8, context: ?compiler.Context) !?*OrdinaryPlainLinkPage
    {
        const supplied = context orelse return null;
        if (supplied.namespace_catalog != ns or !equal(supplied.title, stored.page.title)) return null;
        const independent = try responseSource(a, ns, stored.page);
        if (!equal(independent.source, source)) return null;
        const result = try a.create(OrdinaryPlainLinkPage);
        result.* = .{ .allocator = a, .stored = stored, .parent = parent, .selected_profile = selected, .context = supplied,
            .original_source = try a.dupe(u8, independent.source), .namespace_sha256 = ns.source_sha256 };
        return result;
    }

    fn prepare(self: *OrdinaryPlainLinkPage) !void {
        if (self.contexts != null) return;
        const a = self.allocator;
        const contexts = try a.alloc(profile.ObservedInlineLinkPaintContext, 2);
        for (contexts, 0..) |*context, index| {
            const styles = try figureContextStyles(a, self.parent, self.stored, index != 0);
            const graph = try figureObservedGraph(a, styles, self.stored, index != 0);
            context.* = .{ .styles = styles, .nodes = graph, .root = @intCast(self.stored.outer.ancestors.len) };
        }
        self.html = try selectedStoredHtml(a, self.stored);
        self.contexts = contexts;
        try self.captureActionGroupContexts();
    }

    fn same(a: A, first: profile.ObservedPlainInlineLinkStyle, second: profile.ObservedPlainInlineLinkStyle) !bool {
        return equal(try std.json.Stringify.valueAlloc(a, first, .{}), try std.json.Stringify.valueAlloc(a, second, .{}));
    }
};

pub const SelectedPageStyles = struct {
    ordinary_link_page: ?*OrdinaryPlainLinkPage = null,
    inline_missing: []const InlineMissingProof = &.{},
    intrinsic_tables: []const SelectedFloatingTable = &.{},
    authored_element_original: []const u8 = "",
    authored_element_styles: []const SelectedAuthoredElementStyle = &.{},

    floating_tables: []const SelectedFloatingTable = &.{},
    prefix_table: ?*const SelectedPrefixTable = null,
    styles: *const profile.Profile,
    scope: profile.BoundedTextClassScope,
    source: []const u8,
    namespace_catalog: *const namespaces.Registry,
    file_registry: ?*const sizing.Registry = null,
    ready_behavior: ?*const namespaces.behavior_switches.Registry = null,
    figure_styles: []const SelectedFigureStyle = &.{},
    figure_assets: []const compiler.FigureObservedAsset = &.{},
    pub fn ordinaryLinkPaint(raw: ?*const anyopaque, a: A, operation: compiler.OrdinaryLinkPaintOperation) A.Error!?compiler.OrdinaryLinkPaintObservation {
        _ = a;
        const self: *const SelectedPageStyles = @ptrCast(@alignCast(raw orelse return null));
        return self.ordinaryLinkPaintIn(operation) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            else => return null,
        };
    }

    fn ordinaryLinkPaintIn(self: *const SelectedPageStyles,
        operation: compiler.OrdinaryLinkPaintOperation) !?compiler.OrdinaryLinkPaintObservation
    {
        const owner = self.ordinary_link_page orelse return null;
        // Graphs, styles, labels, font/paint strings and cache entries all escape
        // this call. Keep them in the same arena as their selected Book owner.
        const a = owner.allocator;
        if (operation.source.ptr != self.source.ptr or operation.source.len != self.source.len or
            operation.scope != &self.scope or self.scope.page_styles != self.styles or self.styles != owner.selected_profile or
            !equal(operation.title, owner.context.title) or !equal(operation.title, owner.stored.page.title) or
            !std.mem.eql(u8, &operation.namespace_sha256, &owner.namespace_sha256) or
            !std.mem.eql(u8, &self.namespace_catalog.source_sha256, &owner.namespace_sha256) or
            owner.context.namespace_catalog != self.namespace_catalog or !equal(self.source, owner.original_source)) return null;
        const start = std.math.sub(usize, @intFromPtr(operation.token.ptr), @intFromPtr(self.source.ptr)) catch return null;
        if (operation.token.len == 0 or start >= self.source.len or operation.token.len > self.source.len - start or
            !equal(operation.token, self.source[start..][0..operation.token.len]) or !std.mem.startsWith(u8, operation.token, "[[")) return null;
        const pair = syntax.balanced(operation.token, 0) orelse return null;
        if (pair.end != operation.token.len) return null;
        // Inspect the real following bytes too: a separately emitted trail
        // cannot borrow the one-Span source A's action/focus ownership.
        var parser: encoder.document_ir.InlineIterator = .{ .input = self.source[start..], .renderer_boundaries = true,
            .link_trail = owner.context.link_trail };
        const token = parser.next() orelse return null;
        if (token.kind != .link or token.link_has_pipe or token.link_empty_label or token.link_label_restored_close or
            token.trail.len != 0 or parser.cursor != operation.token.len or token.target.len == 0 or
            std.mem.indexOfAny(u8, token.target, "<>{}[]&'|#\t\r\n\x0c") != null) return null;
        {
            // Canonical target validation does not escape. Release its temporary
            // strings before lookup, including the common cache-hit path.
            var validation = std.heap.ArenaAllocator.init(a); defer validation.deinit();
            const destination = (try compiler.literalSourceLinkDestinationAlloc(validation.allocator(), self.namespace_catalog, token.target)) orelse return null;
            if (destination.external or !equal(destination.target, operation.target)) return null;
        }
        for (owner.cache.items) |entry| if (equal(entry.token, operation.token) and equal(entry.target, operation.target)) return self.focusObservation(operation.token, entry.observation);
        try owner.prepare();
        const contexts = owner.contexts orelse return null;
        const html = owner.html orelse return null;
        const samples = (try profile.observedInlineLinkViewportSamples(a, contexts)) orelse return null;
        var agreed: ?profile.ObservedPlainInlineLinkStyle = null;
        var label: ?[]const u8 = null;
        var matched: usize = 0;
        // Every matching captured A participates. Repeated equal tokens at
        // different locations cannot silently select a preferred font/paint.
        for (owner.stored.observed_nodes, 0..) |node, index| {
            if (!std.ascii.eqlIgnoreCase(node.tag.name, "a")) continue;
            if (node.inner_end == null) return null;
            const observed_pair = syntax.matchingTag(html, node.tag) orelse return null;
            if (observed_pair.inner_end != node.inner_end.? or node.start >= observed_pair.end or observed_pair.end > html.len) return null;
            if (!try noteInlineCorrespondsIn(a, self.namespace_catalog, operation.token, html[node.start..observed_pair.end],
                0, false, true, owner.context, null)) continue;
            if (node.first_child != null) return null;
            const text = (try noteInlineText(a, html[node.tag.end..observed_pair.inner_end])) orelse return null;
            if (text.len == 0 or std.mem.indexOfAny(u8, text, "<>&\t\r\n\x0c") != null) return null;
            if (label) |prior| { if (!equal(prior, text)) return null; } else label = text;
            const subject: u32 = @intCast(owner.stored.outer.ancestors.len + index);
            for (contexts) |context| for (samples) |sample| {
                const value = (try profile.resolveObservedPlainInlineLinkStyle(a, context, subject, sample.width)) orelse return null;
                if (agreed) |prior| { if (!try OrdinaryPlainLinkPage.same(a, prior, value)) return null; } else agreed = value;
            };
            matched += 1;
        }
        if (matched == 0) return null;
        const value = agreed orelse return null;
        const result: compiler.OrdinaryLinkPaintObservation = .{ .profile = self.styles,
             .label = label orelse return null, .font = value.font, .paint = value.paint, .wrap = value.wrap };
        // The token was proved to be an interval of the retained selected
        // source. The normalized target belongs to the caller and must be owned.
        const target = try a.dupe(u8, operation.target);
        errdefer a.free(target);
        try owner.cache.append(a, .{ .token = operation.token, .target = target, .observation = result });
        return self.focusObservation(operation.token, result);
    }

    fn focusObservation(self: *const SelectedPageStyles, token: []const u8,
        value: compiler.OrdinaryLinkPaintObservation) ?compiler.OrdinaryLinkPaintObservation
    {
        var result = value;
        const proof = self.scope.page_source_focus orelse return result;
        const owner = self.ordinary_link_page orelse return null;
        if (!owner.focusCurrent() or proof.root != self.scope.page_style_root or
            proof.complete_root != self.scope.page_style_complete_root or proof.source_image != self.scope.page_source_image) return null;
        const contexts = owner.contexts orelse return null;
        if (contexts.len != proof.graphs.len) return null;
        for (contexts, proof.graphs) |context, graph| {
            if (context.styles != graph.context.styles or context.root != graph.context.root or
                context.nodes.ptr != graph.context.nodes.ptr or context.nodes.len != graph.context.nodes.len) return null;
        }
        if (!profile.pageSourceFocusCurrent(proof)) return null;
        for (proof.actions, 0..) |action, ordinal| {
            if (action.token.ptr != token.ptr or action.token.len != token.len) continue;
            result.focus_proof = proof;
            result.focus_action = ordinal;
            return result;
        }
        return null;
    }

    fn selectSourceFocus(self: *SelectedPageStyles) !?*const profile.PageSourceFocusProof {
        const owner = self.ordinary_link_page orelse return null;
        const image = self.scope.page_source_image orelse return null;
        const root = self.scope.page_style_root orelse return null;
        const complete_root = self.scope.page_style_complete_root orelse return null;
        const a = owner.allocator;
        // The first supported domain contains only complete plain internal
        // wiki links. Unsupported source operations decline the whole census.
        var tokens: std.ArrayList([]const u8) = .empty;
        defer tokens.deinit(a);
        var targets: std.ArrayList([]const u8) = .empty;
        defer targets.deinit(a);
        var cursor: usize = 0;
        while (std.mem.indexOfPos(u8, self.source, cursor, "[[")) |start| {
            if (tokens.items.len == profile.page_source_focus_max_actions) return null;
            var parser: encoder.document_ir.InlineIterator = .{ .input = self.source[start..],
                .renderer_boundaries = true, .link_trail = owner.context.link_trail };
            const item = parser.next() orelse return null;
            if (item.kind != .link or item.link_has_pipe or item.link_empty_label or item.link_label_restored_close or
                item.trail.len != 0 or item.target.len == 0 or parser.cursor == 0 or
                std.mem.indexOfAny(u8, item.target, "<>{}[]&'|#\t\r\n\x0c") != null) return null;
            const token = self.source[start..][0..parser.cursor];
            const pair = syntax.balanced(token, 0) orelse return null;
            if (pair.end != token.len) return null;
            const destination = (try compiler.literalSourceLinkDestinationAlloc(a, self.namespace_catalog, item.target)) orelse return null;
            if (destination.external or destination.target.len == 0) return null;
            try tokens.append(a, token);
            try targets.append(a, destination.target);
            cursor = start + parser.cursor;
        }
        // The first Book transport closes its independent capture currentness
        // through at least one required operation callback at final consumption.
        if (tokens.items.len == 0) return null;
        try owner.prepare();
        const contexts = owner.contexts orelse return null;
        if (contexts.len != 2) return null;
        const html = owner.html orelse return null;
        var captures: std.ArrayList(usize) = .empty;
        defer captures.deinit(a);
        for (owner.stored.observed_nodes, 0..) |node, index| {
            if (!node.tag.is("a")) continue;
            if (node.attributes.get("href") == null) return null;
            if (captures.items.len == tokens.items.len or node.first_child != null) return null;
            try captures.append(a, index);
        }
        if (captures.items.len != tokens.items.len) return null;
        const actions = try a.alloc(profile.PageSourceFocusAction, tokens.items.len);
        for (tokens.items, targets.items, captures.items, actions) |token, target, index, *action| {
            const node = owner.stored.observed_nodes[index];
            const pair = syntax.matchingTag(html, node.tag) orelse return null;
            if (node.inner_end == null or node.inner_end.? != pair.inner_end or node.start >= pair.end or pair.end > html.len) return null;
            if (!try noteInlineCorrespondsIn(a, self.namespace_catalog, token, html[node.start..pair.end],
                0, false, true, owner.context, null)) return null;
            // This callback checks every equal captured spelling, complete
            // declaring font and all paint states at every sampled viewport.
            _ = (try self.ordinaryLinkPaintIn(.{ .source = self.source, .token = token, .target = target,
                .title = owner.context.title, .namespace_sha256 = owner.namespace_sha256, .scope = &self.scope })) orelse return null;
            const subject: u32 = @intCast(owner.stored.outer.ancestors.len + index);
            for (contexts) |context| {
                if (subject >= context.nodes.len or !std.ascii.eqlIgnoreCase(context.nodes[subject].tag, "a")) return null;
            }
            action.* = .{ .token = token, .subjects = .{ subject, subject } };
        }
        // Both graphs were constructed from the independently authenticated
        // API/GET inventory. Profile independently checks their complete A and
        // non-A focus-owner census and exact rule provenance before issuing.
        var value = (try profile.observedPageSourceFocusAlloc(a, self.styles, root, complete_root, image, contexts, actions)) orelse return null;
        errdefer value.deinit();
        const proof = try a.create(profile.PageSourceFocusProof);
        errdefer a.destroy(proof);
        try owner.captureFocus();
        proof.* = value;
        if (try profile.observedPageSourceInlineOwnerAlloc(a, proof)) |owner_style| {
            const retained = try a.create(profile.PageSourceInlineOwnerProof);
            retained.* = owner_style;
            self.scope.page_source_inline_owner = retained;
        }
        return proof;
    }

    pub fn ordinaryActionGroup(raw: ?*const anyopaque, a: A,
        operation: compiler.OrdinaryActionGroupOperation) A.Error!?compiler.OrdinaryActionGroupObservation
    {
        _ = a;
        const self: *const SelectedPageStyles = @ptrCast(@alignCast(raw orelse return null));
        return self.ordinaryActionGroupIn(operation) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory, else => return null,
        };
    }

    fn ordinaryActionGroupIn(self: *const SelectedPageStyles,
        operation: compiler.OrdinaryActionGroupOperation) !?compiler.OrdinaryActionGroupObservation
    {
        const owner = self.ordinary_link_page orelse return null;
        if (operation.source.ptr != self.source.ptr or operation.source.len != self.source.len or
            operation.scope != &self.scope or self.scope.page_styles != self.styles or self.styles != owner.selected_profile or
            !equal(operation.title, owner.context.title) or !equal(operation.title, owner.stored.page.title) or
            !std.mem.eql(u8, &operation.namespace_sha256, &owner.namespace_sha256) or
            !std.mem.eql(u8, &self.namespace_catalog.source_sha256, &owner.namespace_sha256) or
            owner.context.namespace_catalog != self.namespace_catalog or !equal(self.source, owner.original_source)) return null;
        const source_image = self.scope.page_source_image orelse return null;
        if (source_image.styles != self.styles or source_image.root != self.scope.page_style_root or
            source_image.source.ptr != self.source.ptr or source_image.source.len != self.source.len or
            !profile.pageSourceImageCurrent(source_image)) return null;
        var temporary = std.heap.ArenaAllocator.init(owner.allocator);
        defer temporary.deinit();
        const work = temporary.allocator();
        const spelling = (try ordinaryActionGroupSpelling(work, self, operation)) orelse return null;
        const script_source = try ordinaryActionGroupSupSource(work, operation, spelling);
        try owner.prepare();
        if (!owner.actionGroupContextsCurrent()) return null;
        if (owner.focus_capture == null) try owner.captureFocus();
        if (!owner.focusCurrent()) return null;
        const contexts = owner.contexts orelse return null;
        const html = owner.html orelse return null;
        if (contexts.len != 2) return null;
        const samples = (try profile.observedInlineLinkViewportSamples(work, contexts)) orelse return null;
        var agreed: ?profile.ObservedPlainInlineLinkStyle = null;
        var agreed_script: ?profile.ObservedInlineScriptConstraint = null;
        var label: ?[]const u8 = null;
        var target: ?[]const u8 = null;
        var matched: usize = 0;
        for (owner.stored.observed_nodes, 0..) |node, index| {
            if (!node.tag.is("a")) continue;
            const actual_target = (try ordinaryActionGroupCapturedTarget(work, self, operation, spelling, node, html)) orelse continue;
            const pair = syntax.matchingTag(html, node.tag) orelse return null;
            var label_body = html[node.tag.end..pair.inner_end];
            if (script_source != null) {
                const script_tag = currentLiteralHtmlTagAt(html, node.tag.end) orelse return null;
                if (!script_tag.is("sup") or script_tag.closing or script_tag.self_closing) return null;
                const script_pair = syntax.matchingTag(html, script_tag) orelse return null;
                if (script_pair.end != pair.inner_end) return null;
                label_body = html[script_tag.end..script_pair.inner_end];
            }
            const actual_label = (try ordinaryActionGroupCapturedText(work, label_body)) orelse return null;
            if (label) |prior| { if (!equal(prior, actual_label)) return null; } else label = actual_label;
            if (target) |prior| { if (!equal(prior, actual_target)) return null; } else target = actual_target;
            const shift = owner.stored.outer.ancestors.len;
            const subject: u32 = std.math.cast(u32, shift + index) orelse return null;
            var descendants: std.ArrayList(u32) = .empty;
            defer descendants.deinit(work);
            // Ordered raw interval membership is checked again against each
            // complete graph by Profile; it grants neither font nor ancestry.
            for (owner.stored.observed_nodes, 0..) |child, child_index| {
                if (child.start <= node.start or child.start >= pair.inner_end) continue;
                if (child.inner_end == null or child.inner_end.? > pair.inner_end) return null;
                try descendants.append(work, std.math.cast(u32, shift + child_index) orelse return null);
            }
            for (contexts) |context| for (samples) |sample| {
                const value = if (script_source != null) scripts: {
                    if (descendants.items.len != 1) return null;
                    const rich = (try profile.resolveObservedRichInlineLinkOwnerStyleWithScripts(work, context,
                        subject, descendants.items, descendants.items, sample.width)) orelse return null;
                    if (rich.scripts.len != 1 or rich.scripts[0].subject != descendants.items[0]) return null;
                    const constraint = rich.scripts[0];
                    if (!ordinaryActionGroupLineHeightEqual(constraint.line_height, constraint.line_height)) return null;
                    if (agreed_script) |prior| {
                        if (!ordinaryActionGroupFontEqual(prior.declaring_parent_font, constraint.declaring_parent_font) or
                            !ordinaryActionGroupLineHeightEqual(prior.line_height, constraint.line_height)) return null;
                    } else agreed_script = constraint;
                    break :scripts rich.owner;
                } else (if (descendants.items.len == 0)
                    try profile.resolveObservedPlainInlineLinkStyle(work, context, subject, sample.width)
                else try profile.resolveObservedRichInlineLinkOwnerStyle(work, context, subject,
                    descendants.items, sample.width)) orelse return null;
                if (agreed) |prior| { if (!try OrdinaryPlainLinkPage.same(work, prior, value)) return null; } else agreed = value;
            };
            matched += 1;
        }
        if (matched == 0 or !owner.focusCurrent() or !owner.actionGroupContextsCurrent()) return null;
        const value = agreed orelse return null;
        const final_label = label orelse return null;
        const final_target = target orelse return null;
        // Every same-spelling capture agreed. Source identity remains the exact
        // token interval, so distinct adjacent equal-target As never coalesce.
        var entry: ?*OrdinaryPlainLinkPage.ActionGroupEntry = null;
        for (owner.action_group_entries.items) |candidate| {
            if (candidate.token.ptr != operation.token.ptr or candidate.token.len != operation.token.len) continue;
            if (!equal(candidate.native_target, operation.target) or candidate.external != operation.external or
                candidate.interwiki != operation.interwiki or candidate.source_image != source_image or
                candidate.source_snapshot.ptr != source_image.snapshot.ptr or candidate.source_snapshot.len != source_image.snapshot.len) return null;
            const old = candidate.observation;
            if (!equal(old.label, final_label) or !equal(old.target, final_target) or
                !try OrdinaryPlainLinkPage.same(work, .{ .font = old.font, .paint = old.paint, .wrap = old.wrap }, value)) return null;
            if ((candidate.script == null) != (script_source == null)) return null;
            if (candidate.script) |held| {
                const current = script_source.?;
                const constraint = agreed_script orelse return null;
                if (held.source.token.ptr != current.token.ptr or held.source.token.len != current.token.len or
                    held.source.opening_len != current.opening_len or held.source.body_len != current.body_len or
                    !equal(held.source.classes, current.classes) or
                    !ordinaryActionGroupFontEqual(held.declaring_parent_font, constraint.declaring_parent_font) or
                    !ordinaryActionGroupLineHeightEqual(held.line_height, constraint.line_height) or
                    candidate.observation.scripts.len != 1) return null;
                const script_descriptor = candidate.observation.scripts[0];
                if (script_descriptor.source_receipt != @as(*const anyopaque, held) or script_descriptor.token.ptr != current.token.ptr or script_descriptor.token.len != current.token.len or
                    script_descriptor.opening_len != current.opening_len or script_descriptor.body_len != current.body_len) return null;
            } else if (candidate.observation.scripts.len != 0) return null;
            entry = candidate;
            break;
        }
        if (entry == null) {
            if (owner.action_group_entries.items.len == profile.page_source_focus_max_actions) return null;
            const owned = try ordinaryActionGroupStyleClone(owner.allocator, value);
            const created = try owner.allocator.create(OrdinaryPlainLinkPage.ActionGroupEntry);
            created.* = .{ .token = operation.token, .native_target = try owner.allocator.dupe(u8, operation.target),
                .external = operation.external, .interwiki = operation.interwiki, .source_image = source_image,
                .source_snapshot = source_image.snapshot,
                .observation = .{ .profile = self.styles, .source_receipt = created,
                    .label = try owner.allocator.dupe(u8, final_label), .target = try owner.allocator.dupe(u8, final_target),
                    .font = owned.font, .paint = owned.paint, .wrap = owned.wrap } };
            if (script_source) |source_value| {
                const constraint = agreed_script orelse return null;
                const held = try owner.allocator.create(OrdinaryPlainLinkPage.ActionGroupScriptEntry);
                var owned_source = source_value;
                owned_source.classes = try owner.allocator.dupe(u8, source_value.classes);
                held.* = .{ .source = owned_source,
                    .declaring_parent_font = try ordinaryActionGroupFontClone(owner.allocator, constraint.declaring_parent_font),
                    .line_height = constraint.line_height };
                const descriptors = try owner.allocator.alloc(compiler.OrdinaryActionGroupScript, 1);
                descriptors[0] = .{ .source_receipt = held, .token = source_value.token,
                    .opening_len = source_value.opening_len, .body_len = source_value.body_len };
                created.script = held;
                created.observation.scripts = descriptors;
            }
            try owner.action_group_entries.append(owner.allocator, created);
            entry = created;
        }
        var result = entry.?.observation;
        if (self.scope.page_source_focus) |proof| {
            if (!profile.pageSourceFocusCurrent(proof) or proof.styles != self.styles or proof.source_image != source_image or
                proof.root != self.scope.page_style_root or proof.complete_root != self.scope.page_style_complete_root) return null;
            for (proof.actions, 0..) |action, ordinal| {
                if (action.token.ptr != operation.token.ptr or action.token.len != operation.token.len) continue;
                result.focus_proof = proof;
                result.focus_action = ordinal;
                return result;
            }
            return null;
        }
        return result;
    }

    pub fn ordinaryActionGroupScript(raw: ?*const anyopaque, a: A,
        operation: compiler.OrdinaryActionGroupScriptOperation) A.Error!?compiler.OrdinaryActionGroupScriptObservation
    {
        const self: *const SelectedPageStyles = @ptrCast(@alignCast(raw orelse return null));
        return self.ordinaryActionGroupScriptIn(a, operation) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory, else => return null,
        };
    }

    fn ordinaryActionGroupScriptIn(self: *const SelectedPageStyles, a: A,
        operation: compiler.OrdinaryActionGroupScriptOperation) !?compiler.OrdinaryActionGroupScriptObservation
    {
        // Recompute the complete source/captured policy and its immutable
        // inventory joins before consuming any provisional child constraint.
        const observed = (try self.ordinaryActionGroupIn(operation.owner)) orelse return null;
        if (observed.source_receipt != operation.owner_receipt or observed.scripts.len != 1) return null;
        const owner = self.ordinary_link_page orelse return null;
        var matched: ?*const OrdinaryPlainLinkPage.ActionGroupScriptEntry = null;
        for (owner.action_group_entries.items) |entry| {
            if (entry.observation.source_receipt != observed.source_receipt) continue;
            if (matched != null) return null;
            const script = entry.script orelse return null;
            if (operation.script.source_receipt != @as(*const anyopaque, script) or operation.script.token.ptr != script.source.token.ptr or
                operation.script.token.len != script.source.token.len or operation.script.opening_len != script.source.opening_len or
                operation.script.body_len != script.source.body_len) return null;
            matched = script;
        }
        const held = matched orelse return null;
        if (!ordinaryActionGroupSupFont(operation.font, held.declaring_parent_font, held.source.classes,
            operation.owner.interwiki)) return null;
        const factor: f32 = switch (held.line_height) {
            .multiplier => |value| value,
            .font_relative => |value| value,
            else => return null,
        };
        if (!std.math.isFinite(factor) or factor < 0) return null;
        return .{ .source_receipt = held,
            .line_height = .{ .font_relative = .{ .factor = factor, .font = try ordinaryActionGroupFontClone(a, operation.font) } } };
    }

    fn selectRichSourceFocus(self: *SelectedPageStyles) !?*const profile.PageSourceFocusProof {
        const owner = self.ordinary_link_page orelse return null;
        const image = self.scope.page_source_image orelse return null;
        const root = self.scope.page_style_root orelse return null;
        const complete_root = self.scope.page_style_complete_root orelse return null;
        const a = owner.allocator;
        var operations: std.ArrayList(compiler.OrdinaryActionGroupOperation) = .empty;
        defer operations.deinit(a);
        var cursor: usize = 0;
        while (cursor < self.source.len) {
            if (std.mem.startsWith(u8, self.source[cursor..], "<!--")) {
                const end = std.mem.indexOfPos(u8, self.source, cursor + 4, "-->") orelse return null;
                cursor = end + 3;
                continue;
            }
            if (self.source[cursor] == '<') if (syntax.tagAt(self.source, cursor)) |tag| {
                if (!tag.closing and !tag.self_closing and tag.isOpaque()) {
                    const pair = syntax.matchingTag(self.source, tag) orelse return null;
                    cursor = pair.end;
                } else cursor = tag.end;
                continue;
            };
            const internal = std.mem.startsWith(u8, self.source[cursor..], "[[");
            const external = std.mem.startsWith(u8, self.source[cursor..], "[http://") or
                std.mem.startsWith(u8, self.source[cursor..], "[https://") or
                std.mem.startsWith(u8, self.source[cursor..], "http://") or
                std.mem.startsWith(u8, self.source[cursor..], "https://");
            if (!internal and !external) { cursor += 1; continue; }
            var parser: encoder.document_ir.InlineIterator = .{ .input = self.source[cursor..],
                .renderer_boundaries = true, .link_trail = owner.context.link_trail };
            const item = parser.next() orelse return null;
            if ((internal and item.kind != .link) or (!internal and item.kind != .external_link) or parser.cursor == 0) return null;
            const token = self.source[cursor..][0..parser.cursor];
            if (internal and item.target.len != 0 and item.target[0] != ':' and self.namespace_catalog.ofTitle(item.target).id == 14) {
                // The ordinary parser consumes complete hidden Category metadata
                // without an A. It cannot discharge a visible source occurrence.
                const pair = syntax.balanced(token, 0) orelse return null;
                if (item.link_empty_label or item.link_label_restored_close or
                    std.mem.trim(u8, item.target, " \t\r\n").len != item.target.len or
                    std.mem.indexOfAny(u8, item.target, "[]{}<>|&'#\r\n") != null or
                    self.namespace_catalog.ofTitle(item.target).text.len == 0 or
                    (item.link_has_pipe and try noteInlineText(a, item.text) == null)) return null;
                cursor += pair.end;
                continue;
            }
            if (operations.items.len == profile.page_source_focus_max_actions) return null;
            var operation: compiler.OrdinaryActionGroupOperation = .{ .source = self.source, .token = token,
                .target = item.target, .external = !internal, .interwiki = false,
                .title = owner.context.title, .namespace_sha256 = owner.namespace_sha256, .scope = &self.scope };
            if (internal) {
                const destination = (try compiler.literalSourceLinkDestinationAlloc(a, self.namespace_catalog, item.target)) orelse return null;
                operation.target = destination.target;
                operation.external = destination.external;
                operation.interwiki = destination.external;
            }
            _ = (try ordinaryActionGroupSpelling(a, self, operation)) orelse return null;
            try operations.append(a, operation);
            cursor += parser.cursor;
        }
        if (operations.items.len == 0) return null;
        try owner.prepare();
        if (!owner.actionGroupContextsCurrent()) return null;
        const contexts = owner.contexts orelse return null;
        if (contexts.len != 2) return null;
        const html = owner.html orelse return null;
        var captures: std.ArrayList(usize) = .empty;
        defer captures.deinit(a);
        for (owner.stored.observed_nodes, 0..) |node, index| {
            if (!node.tag.is("a")) continue;
            if (node.attributes.get("href") == null or captures.items.len == operations.items.len) return null;
            try captures.append(a, index);
        }
        if (captures.items.len != operations.items.len) return null;
        const actions = try a.alloc(profile.PageSourceFocusAction, operations.items.len);
        for (operations.items, captures.items, actions) |operation, index, *action| {
            const spelling = (try ordinaryActionGroupSpelling(a, self, operation)) orelse return null;
            _ = (try ordinaryActionGroupCapturedTarget(a, self, operation, spelling, owner.stored.observed_nodes[index], html)) orelse return null;
            // Full source order and complete captured-A order are joined before
            // any declaration can be deferred. Each operation still revalidates
            // its own captured policy and final rendered owner independently.
            _ = (try self.ordinaryActionGroupIn(operation)) orelse return null;
            const subject: u32 = std.math.cast(u32, owner.stored.outer.ancestors.len + index) orelse return null;
            action.* = .{ .token = operation.token, .subjects = .{ subject, subject } };
            // Only the complete source/HTML correspondence above may transport
            // this normalization metadata. Each observed arm must agree with
            // that same source-bound capture before Profile sees the receipt.
            if (owner.stored.observed_nodes[index].attributes.get("data-mw-original-href")) |original| {
                if (!spelling.external_source or !equal(original, spelling.target)) return null;
                for (contexts, 0..) |context, arm| {
                    if (subject >= context.nodes.len) return null;
                    var captured: ?[]const u8 = null;
                    for (context.nodes[subject].attributes) |attribute| {
                        if (!equal(attribute.name, "data-mw-original-href")) continue;
                        if (captured != null) return null;
                        captured = attribute.value;
                    }
                    if (!equal(captured orelse return null, original)) return null;
                    action.original_hrefs[arm] = captured;
                }
            }
        }
        if (!owner.focusCurrent() or !owner.actionGroupContextsCurrent()) return null;
        var value = (try profile.observedPageSourceFocusAlloc(a, self.styles, root, complete_root, image, contexts, actions)) orelse return null;
        errdefer value.deinit();
        const proof = try a.create(profile.PageSourceFocusProof);
        errdefer a.destroy(proof);
        proof.* = value;
        if (try profile.observedPageSourceInlineOwnerAlloc(a, proof)) |owner_style| {
            const retained = try a.create(profile.PageSourceInlineOwnerProof);
            retained.* = owner_style;
            self.scope.page_source_inline_owner = retained;
        }
        return proof;
    }

    pub fn inlineMissing(raw: ?*const anyopaque, a: A, operation: compiler.InlineMissingOperation) A.Error!?compiler.InlineMissingObservation {
        const self: *const SelectedPageStyles = @ptrCast(@alignCast(raw orelse return null));
        if (operation.source.ptr != self.source.ptr or operation.source.len != self.source.len or
            !equal(self.source, self.authored_element_original)) return null;
        const file = canonicalFile(a, self.namespace_catalog, operation.file) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory, else => return null,
        };
        for (self.inline_missing) |proof| {
            if (operation.token.ptr != proof.token.ptr or operation.token.len != proof.token.len or !equal(file, proof.file)) continue;
            return .{ .profile = self.styles, .label = proof.label, .href = proof.href, .title = proof.title, .data_width = proof.width,
                .table_opening = proof.table_opening, .row_opening = proof.row_opening, .cell_opening = proof.cell_opening,
                .contexts = proof.contexts };
        }
        return null;
    }

    pub fn authoredElementStyle(raw: ?*const anyopaque, a: A, operation: compiler.AuthoredElementStyleOperation) A.Error!?compiler.AuthoredElementStyleObservation {
        _ = a;
        const self: *const SelectedPageStyles = @ptrCast(@alignCast(raw orelse return null));
        if (operation.source.ptr != self.source.ptr or operation.source.len != self.source.len or
            !equal(self.source, self.authored_element_original)) return null;
        for (self.authored_element_styles) |selected| {
            if (!equal(selected.proof.tag, "hr")) return null;
            const range = selected.proof.range;
            const element = self.source[range.start..range.end];
            if (operation.element.ptr != element.ptr or operation.element.len != element.len) continue;
            return .{ .profile = self.styles, .contexts = selected.contexts };
        }
        return null;
    }

    pub fn floatingTable(raw: ?*const anyopaque, a: A, source: []const u8, opening: usize) A.Error!?compiler.TableContainingDirectionObservation {
        _ = a;
        const self: *const SelectedPageStyles = @ptrCast(@alignCast(raw orelse return null));
        return self.tableObservation(source, opening, self.floating_tables);
    }

    fn tableObservation(self: *const SelectedPageStyles, source: []const u8, opening: usize,
        tables: []const SelectedFloatingTable) A.Error!?compiler.TableContainingDirectionObservation
    {
        if (source.ptr != self.source.ptr or source.len != self.source.len or !equal(source, self.authored_element_original)) return null;
        for (tables) |known| if (opening == known.opening_start) {
            if (known.opening_end > source.len or !std.mem.startsWith(u8, source[opening..known.opening_end], "{|")) return null;
            var motion: ?compiler.TableStaticMotionObservation = null;
            if (self.scope.page_static_motion) |proof| if (proof.styles == self.styles and proof.root == self.scope.page_style_root and
                proof.source.ptr == self.source.ptr and proof.source.len == self.source.len and
                known.page_contexts.len == known.contexts.len) {
                var coherent = true;
                for (known.contexts, known.page_contexts) |context, full| if (context.styles != full.styles or context.root != full.root) { coherent = false; break; };
                if (coherent) motion = .{ .proof = proof, .contexts = known.contexts };
            };
            return .{ .contexts = known.contexts, .link_contexts = known.link_contexts, .parents = &.{}, .static_motion = motion };
        };
        return null;
    }

    pub fn intrinsicTable(raw: ?*const anyopaque, a: A, source: []const u8, opening: usize) A.Error!?compiler.TableContainingDirectionObservation {
        _ = a;
        const self: *const SelectedPageStyles = @ptrCast(@alignCast(raw orelse return null));
        return self.tableObservation(source, opening, self.intrinsic_tables);
    }
    pub fn tableIntrinsicSource(self: *const SelectedPageStyles) ?compiler.TableContainingDirectionSource {
        if (self.intrinsic_tables.len == 0) return null;
        return .{ .intrinsic_viewport = true, .source = self.source, .context = self, .observe = intrinsicTable };
    }

    fn prefixTable(raw: ?*const anyopaque, a: A, source: []const u8, opening: usize) A.Error!?compiler.TableContainingDirectionObservation {
        const self: *const SelectedPageStyles = @ptrCast(@alignCast(raw orelse return null));
        return SelectedPrefixTable.observe(self.prefix_table orelse return null, a, source, opening);
    }
    fn prefixPreflight(raw: ?*const anyopaque, source: []const u8) ?compiler.ObservedTextClassScope {
        const self: *const SelectedPageStyles = @ptrCast(@alignCast(raw orelse return null));
        const prefix = self.prefix_table orelse return null;
        if (source.ptr != self.source.ptr or source.len != self.source.len or
            prefix.source.ptr != source.ptr or prefix.source.len != source.len or self.scope.page_styles != self.styles) return null;
        return .{ .source = self.source, .scope = &self.scope };
    }
    pub fn tablePrefixSource(self: *const SelectedPageStyles) ?compiler.TableContainingDirectionSource {
        var result = (self.prefix_table orelse return null).capability();
        result.context = self;
        result.observe = prefixTable;
        result.preflight_scope = prefixPreflight;
        return result;
    }
    pub fn figureStyle(raw: ?*const anyopaque, a: A, operation: compiler.FigureStyleOperation) A.Error!?compiler.FigureStyleObservation {
        const self: *const SelectedPageStyles = @ptrCast(@alignCast(raw orelse return null));
        if (operation.source.ptr != self.source.ptr or operation.source.len != self.source.len or
            (operation.layout_kind == .table_caption and operation.format != .thumbnail) or
            (operation.layout_kind == .block_media and operation.format != .framed)) return null;
        const canonical = canonicalFile(a, self.namespace_catalog, operation.file) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            else => return null,
        };
        defer a.free(canonical);
        for (self.figure_styles) |selected| {
            const proof = selected.proof;
            if (operation.layout_kind != proof.layout_kind) continue;
            const token = self.source[proof.range.start..proof.range.end];
            const options = self.source[proof.options_start..proof.options_end];
            const caption = self.source[proof.caption_start..(if (proof.empty_caption) proof.caption_start else proof.options_end)];
            if (operation.token.ptr != token.ptr or operation.token.len != token.len or
                operation.options.ptr != options.ptr or operation.options.len != options.len or
                operation.caption.ptr != caption.ptr or operation.caption.len != caption.len or
                !equal(canonical, proof.canonical_file)) continue;
            if (proof.observed_canonical_file) |observed_file| {
                const files = self.file_registry orelse return null;
                const behavior = self.ready_behavior orelse return null;
                if (!std.mem.eql(u8, &behavior.namespace_sha256, &self.namespace_catalog.source_sha256)) return null;
                const resolved = readyFigureCanonicalFile(a, self.namespace_catalog, files, canonical) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory, else => return null,
                };
                defer a.free(resolved);
                if (!equal(observed_file, resolved)) return null;
            }
            const block: ?compiler.FigureBlockMediaObservation = if (proof.block_renditions) |pair| .{
                .preferred_width = proof.block_preferred_width orelse return null,
                .natural_width = pair[0].width, .natural_height = pair[0].height,
                .renditions = .{ pair[0].identity, pair[1].identity },
            } else null;
            return .{ .profile = self.styles, .contexts = selected.contexts, .assets = self.figure_assets, .block_media = block };
        }
        return null;
    }
};

pub const Book = struct {
    arena: std.heap.ArenaAllocator,
    namespace_sha256: [32]u8,
    defaults_sha256: [32]u8,
    default_width: u32,
    pages: []const Page,
    // Borrowed authenticated normal input, retained through worker completion.
    file_registry: ?*const sizing.Registry = null,
    table_roots: []const PreparedTableRoot = &.{},
    missing_link_paint: ?encoder.presentation_types.MissingLinkPaint = null,
    pub fn init(parent: A, bytes: []const u8, ns: *const namespaces.Registry, registry: *const sizing.Registry, defaults_sha256: [32]u8, default_width: u32) !Book {
        if (bytes.len == 0 or bytes.len > max_input or default_width == 0 or !registry.file_authority) return invalid;
        var arena = std.heap.ArenaAllocator.init(parent);
        errdefer arena.deinit();
        const a = arena.allocator();
        const shape = try std.json.parseFromSliceLeaky(Value, a, bytes, .{ .allocate = .alloc_always });
        // Preserve strict legacy shape refusal. V10 adds only exact Missing
        // operations to the independent V9 poster/SVG join, checked below.
        if (shape == .object) {
            if (shape.object.get("schema")) |schema_value| {
                if (schema_value == .string and !equal(schema_value.string, "wikidict.figure-page-observations.v8") and
                    !equal(schema_value.string, "wikidict.figure-page-observations.v10") and
                    !equal(schema_value.string, "wikidict.figure-page-observations.v11")) {
                    if (shape.object.get("pages")) |page_values| {
                        if (page_values == .array) {
                            for (page_values.array.items) |page_value| {
                                if (page_value == .object and (page_value.object.contains("figure_style_operations") or
                                    page_value.object.contains("figure_style_assets"))) return error.UnknownField;
                            }
                        }
                    }
                }
            }
        }
        if (shape == .object) if (shape.object.get("schema")) |schema_value| {
            if (schema_value == .string and !equal(schema_value.string, "wikidict.figure-page-observations.v8"))
                if (shape.object.get("pages")) |page_values| if (page_values == .array)
                    for (page_values.array.items) |page_value| if (page_value == .object and
                        (page_value.object.contains("authored_style_operations") or page_value.object.contains("authored_head_context"))) return error.UnknownField;
        };
        const doc = try std.json.parseFromValueLeaky(Document, a, shape, .{});
        // v7 composes independent Missing and SVG-language proofs. It does not
        // manufacture a page context or authorize general stylesheets.
        // V9 composes existing independent proofs; it grants no v8-only source
        // operation or image-map authority and cannot merely relabel a v5 Book.
        // V10 adds only source-bound Missing operations to the complete V9
        // conjunction. Ready assets and image maps retain their existing gates.
        const missing_operation_contract = equal(doc.schema, "wikidict.figure-page-observations.v10");
        const poster_svg_contract = missing_operation_contract or equal(doc.schema, "wikidict.figure-page-observations.v9");
        const relation_style_contract = equal(doc.schema, "wikidict.figure-page-observations.v11");
        const image_map_contract = equal(doc.schema, "wikidict.figure-page-observations.v8");
        const combined_contract = relation_style_contract or image_map_contract or poster_svg_contract or equal(doc.schema, "wikidict.figure-page-observations.v7");
        const table_roots = if (doc.table_roots) |roots| blk: {
            if ((!image_map_contract and !relation_style_contract) or roots.len == 0 or roots.len > max_pages) return invalid;
