// Build-only observation of the selected outer insertion context. The supplied
// API parser body remains authoritative; this never imports the GET body.
pub const RawOuterContext = struct {
    // Explicit source selection, never an equivalence between API and GET roots.
    selected_body: ?enum { full_get_root, current_get_literal } = null,
    current_identity: ?CurrentOuterIdentity = null,
    profile: []const u8,
    receipt: []const u8 = "",
    response: []const u8,
};
const OuterObservedNode = struct { tag: []const u8, attributes: Inventory };
const OuterObservedPrefix = struct {
    configuration_program: ?[]const u8 = null,
    configuration_programs: usize = 0,
    body_open_end: usize = 0,
    root_start: ?usize = null,
    root_open_end: ?usize = null,
    ancestors: []const OuterObservedNode,
    root: ?Inventory = null,
    generator: []const u8,
};
// Full skin markup uses ordinary boolean attributes. Keep this parser local;
// the older supplied-body attribute domain remains unchanged.
fn outerInventory(a: A, tag: syntax.Tag) !Inventory {
    return outerInventoryReturned(a, tag, false);
}
fn outerInventoryReturned(a: A, tag: syntax.Tag, returned_html: bool) !Inventory {
    var attrs: std.ArrayList(Attribute) = .empty;
    var at: usize = 0;
    while (at < tag.attrs.len) {
        if (!htmlClassSpace(tag.attrs[at])) return invalid;
        while (at < tag.attrs.len and htmlClassSpace(tag.attrs[at])) : (at += 1) {}
        if (at == tag.attrs.len) break;
        const start = at;
        while (at < tag.attrs.len and attributeNameByte(tag.attrs[at])) : (at += 1) {}
        if (at == start or attrs.items.len >= 64) return invalid;
        const name = tag.attrs[start..at];
        for (attrs.items) |old| if (std.ascii.eqlIgnoreCase(old.name, name)) return invalid;
        const after_name = at;
        while (at < tag.attrs.len and htmlClassSpace(tag.attrs[at])) : (at += 1) {}
        var value: []const u8 = "";
        if (at < tag.attrs.len and tag.attrs[at] == '=') {
            at += 1;
            while (at < tag.attrs.len and htmlClassSpace(tag.attrs[at])) : (at += 1) {}
            if (at == tag.attrs.len or (tag.attrs[at] != '"' and tag.attrs[at] != '\'')) return invalid;
            const quote = tag.attrs[at]; at += 1; const begin = at;
            while (at < tag.attrs.len and tag.attrs[at] != quote) : (at += 1) if (tag.attrs[at] == '<' or (!returned_html and tag.attrs[at] == '>') or tag.attrs[at] == 0) return invalid;
            if (at == tag.attrs.len) return invalid;
            value = try decodedAttribute(a, tag.attrs[begin..at]); at += 1;
        } else at = after_name;
        try attrs.append(a, .{ .name = name, .value = value });
    }
    return .{ .attributes = try attrs.toOwnedSlice(a) };
}
fn outerVoidTag(tag: syntax.Tag) bool {
    for ([_][]const u8{ "area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "param", "source", "track", "wbr" }) |name|
        if (tag.is(name)) return true;
    return false;
}
fn outerRawTextEnd(html: []const u8, tag: syntax.Tag) !usize {
    var at = tag.end;
    while (at < html.len) : (at += 1) {
        if (html[at] != '<' or at + 2 + tag.name.len >= html.len or html[at + 1] != '/' or
            !std.ascii.eqlIgnoreCase(html[at + 2 .. at + 2 + tag.name.len], tag.name)) continue;
        const next = html[at + 2 + tag.name.len];
        if (next != '>' and next != '/' and !htmlClassSpace(next)) continue;
        const close = syntax.tagAt(html, at) orelse return invalid;
        if (!close.closing or close.self_closing or close.attrs.len != 0 or !std.ascii.eqlIgnoreCase(close.name, tag.name)) return invalid;
        return close.end;
    }
    return invalid;
}
// Only a completely explicit lexical prefix is accepted. No HTML error repair,
// implicit parent insertion, or guessed closure can supply an ancestor class.
fn observedOuterPrefix(a: A, html: []const u8, parser_root: bool) !OuterObservedPrefix {
    if (html.len == 0 or html.len > max_response or !std.unicode.utf8ValidateSlice(html) or std.mem.indexOfScalar(u8, html, 0) != null) return invalid;
    var stack: [128]OuterObservedNode = undefined;
    var depth: usize = 0;
    var at: usize = 0;
    var configuration_program: ?[]const u8 = null;
    var configuration_programs: usize = 0;
    var generator: ?[]const u8 = null;
    var html_seen = false;
    var body_seen = false;
    var body_open_end: usize = 0;
    var elements: usize = 0;
    while (at < html.len) {
        if (std.mem.startsWith(u8, html[at..], "<!--")) {
            const end = std.mem.indexOfPos(u8, html, at + 4, "-->") orelse return invalid;
            if (std.mem.indexOf(u8, html[at + 4 .. end], "--") != null) return invalid;
            at = end + 3; continue;
        }
        if (html.len - at >= 15 and std.ascii.eqlIgnoreCase(html[at .. at + 15], "<!DOCTYPE html>")) {
            if (html_seen or depth != 0) return invalid;
            at += 15; continue;
        }
        if (html[at] != '<') {
            if (depth == 0 and !htmlClassSpace(html[at])) return invalid;
            at += 1; continue;
        }
        const tag = syntax.tagAt(html, at) orelse return invalid;
        if (tag.end <= at or tag.end > html.len) return invalid;
        const inv = try outerInventory(a, tag);
        if (tag.closing) {
            if (inv.attributes.len != 0 or tag.self_closing or depth == 0 or !std.ascii.eqlIgnoreCase(stack[depth - 1].tag, tag.name)) return invalid;
            depth -= 1; at = tag.end; continue;
        }
        elements += 1;
        if (elements > 16384) return invalid;
        if (tag.is("html")) {
            if (html_seen or depth != 0) return invalid;
            html_seen = true;
        } else if (!html_seen or depth == 0) return invalid;
        if (tag.is("body")) {
            if (body_seen or depth != 1 or !equal(stack[0].tag, "html")) return invalid;
            body_seen = true;
            body_open_end = tag.end;
        }
        if (tag.is("meta") and equal(inv.get("name") orelse "", "generator")) {
            if (generator != null or body_seen) return invalid;
            generator = inv.get("content") orelse return invalid;
        }
        if (profile.Profile.hasClass(inv.get("class") orelse "", "mw-parser-output")) {
            if (!parser_root or !body_seen or !tag.is("div") or tag.self_closing) return invalid;
            return .{ .configuration_program = configuration_program, .configuration_programs = configuration_programs, .ancestors = try a.dupe(OuterObservedNode, stack[0..depth]), .root = inv, .generator = generator orelse return invalid, .body_open_end = body_open_end, .root_start = at, .root_open_end = tag.end };
        }
        if (tag.is("script") or tag.is("style")) {
            if (tag.self_closing) return invalid;
            const end = try outerRawTextEnd(html, tag);
            if (tag.is("script") and depth == 2 and equal(stack[1].tag, "head")) {
                const close = std.mem.lastIndexOfScalar(u8, html[tag.end..end], '<') orelse return invalid;
                const program = html[tag.end..][0..close];
                if (std.mem.indexOf(u8, program, "RLCONF=") != null) {
                    configuration_programs += 1;
                    if (tag.attrs.len == 0) configuration_program = program;
                }
            }
            at = end; continue;
        }
        if (!outerVoidTag(tag)) {
            if (tag.self_closing or depth == stack.len) return invalid;
            stack[depth] = .{ .tag = tag.name, .attributes = inv }; depth += 1;
        }
        at = tag.end;
    }
    if (parser_root or !html_seen or !body_seen or depth != 2 or !equal(stack[0].tag, "html") or !equal(stack[1].tag, "body")) return invalid;
    return .{ .configuration_program = configuration_program, .configuration_programs = configuration_programs, .ancestors = try a.dupe(OuterObservedNode, stack[0..depth]), .generator = generator orelse return invalid, .body_open_end = body_open_end };
}
fn outerSameAttributes(left: Inventory, right: Inventory, omit_class: bool) bool {
    var left_count: usize = 0;
    var right_count: usize = 0;
    for (left.attributes) |attr| {
        if (omit_class and equal(attr.name, "class")) continue;
        left_count += 1;
        if (!equal(attr.value, right.get(attr.name) orelse return false)) return false;
    }
    for (right.attributes) |attr| { if (!(omit_class and equal(attr.name, "class"))) right_count += 1; }
    return left_count == right_count;
}
fn outerRootClassesCompatible(left: []const u8, right: []const u8) bool {
    for ([_][2][]const u8{ .{ left, right }, .{ right, left } }) |pair| {
        var it = std.mem.tokenizeAny(u8, pair[0], " \t\r\n\x0c");
        while (it.next()) |name| {
            // SkinVector22 adds this finite TOC state while building template
            // data after the API has emitted headhtml. Both states are retained.
            if (equal(name, "vector-toc-available") or equal(name, "vector-toc-not-available")) continue;
            if (!profile.Profile.hasClass(pair[1], name)) return false;
        }
    }
    return true;
}
fn appendOuterClasses(a: A, result: *std.ArrayList(u8), classes: []const u8) !void {
    if (classes.len > 65536) return invalid;
    var it = std.mem.tokenizeAny(u8, classes, " \t\r\n\x0c");
    while (it.next()) |name| {
        if (name.len > 1024) return invalid;
        for (name) |byte| if (byte < 0x20 or byte == 0x7f) return invalid;
        if (profile.Profile.hasClass(result.items, name)) continue;
        if (result.items.len + name.len + 1 > 65536) return invalid;
        if (result.items.len != 0) try result.append(a, ' ');
        try result.appendSlice(a, name);
    }
}
fn uniqueCounterRootClass(a: A, stored: *const PageStyleData, source: []const u8) !?[]const u8 {
    const outer = stored.page.outer_context orelse return null;
    const start = stored.outer.root_start orelse return null;
    const end = stored.outer.root_open_end orelse return null;
    if (start >= end or end > outer.response.len or
        !std.mem.endsWith(u8, std.mem.trim(u8, outer.response, " \t\r\n"), "</html>")) return null;
    // Counters extend to following siblings. Census the entire authenticated
    // GET, not just the API body and its selected ancestor chain. Only this
    // exact validated root opening is omitted from the outside inventory.
    var outside: std.ArrayList(u8) = .empty; defer outside.deinit(a);
    for ([_][]const u8{ source, outer.response[0..start], outer.response[end..] }) |bytes| if (bytes.len != 0)
        appendAuthoredSourceClasses(a, &outside, bytes) catch |err| {
            if (err == error.InvalidFigurePageObservations) return null;
            return err;
        };
    for (stored.observed_nodes[1..]) |node| try appendOuterClasses(a, &outside, node.attributes.get("class") orelse "");
    for (stored.outer.ancestors) |node| try appendOuterClasses(a, &outside, node.attributes.get("class") orelse "");
    const get = stored.outer.root_attributes orelse return null;
    const primary = stored.observed_nodes[0].attributes;
    var unique: std.ArrayList(u8) = .empty; defer unique.deinit(a);
    var names = std.mem.tokenizeAny(u8, get.get("class") orelse "", " \t\r\n\x0c");
    while (names.next()) |name| {
        if (!profile.Profile.hasClass(primary.get("class") orelse "", name) or profile.Profile.hasClass(outside.items, name)) continue;
        if (name.len == 0 or name.len > 128) continue;
        var simple = true;
        for (name) |byte| if (!std.ascii.isAlphanumeric(byte) and byte != '-' and byte != '_') { simple = false; break; };
        if (simple) try appendOuterClasses(a, &unique, name);
    }
    return if (unique.items.len != 0) try unique.toOwnedSlice(a) else null;
}
// The selected Page.source is authenticated Book-arena storage. Counter
// currentness may share it on pages that still owe positive row-color owners.
fn observedSourcePlainLinkLabels(a: A, ns: *const namespaces.Registry, source: []const u8) !?*const profile.SourcePlainLinkLabels {
    if (source.len == 0 or source.len > 4 * 1024 * 1024) return null;
    if (std.mem.indexOfScalar(u8, source, '&') == null) return null;
    if (!std.unicode.utf8ValidateSlice(source) or std.mem.indexOfScalar(u8, source, 0) != null) return null;
    var labels: std.ArrayList(profile.SourcePlainLinkLabel) = .empty;
    defer labels.deinit(a);
    var cursor: usize = 0;
    var validation = std.heap.ArenaAllocator.init(a); defer validation.deinit();
    while (profile.nextSourcePlainLinkLabel(source, ns, &cursor)) |label| {
        if (labels.items.len == 64) return null;
        // Qualify the ordinary displayed-link role with the maintained target
        // resolver. Balanced File/Category options alone lend no label evidence.
        const target = source[label.start + 2..label.label_start - 1];
        _ = (try compiler.literalSourceLinkDestinationAlloc(validation.allocator(), ns, target)) orelse return null;
        try labels.append(a, label);
    }
    if (cursor > source.len or labels.items.len == 0) return null;
    const proof = try a.create(profile.SourcePlainLinkLabels);
    proof.* = .{ .source = source, .namespace_catalog = ns, .namespace_sha256 = ns.source_sha256,
        .interwiki_rows = ns.interwiki_rows, .interwiki_magic = ns.interwiki_magic,
        .labels = try labels.toOwnedSlice(a) };
    if (!profile.sourcePlainLinkLabelsCurrent(proof, source)) return null;
    return proof;
}

fn selectedPageSourceImage(a: A, styles: *const profile.Profile, root: *const profile.TextElement,
    source: []const u8, retained: []const u8, rows: ?*const profile.ClosedRowColorProof) !?*const profile.PageSourceImage
{
    return selectedPageSourceImageWithLabels(a, styles, root, source, retained, rows, null);
}
fn selectedPageSourceImageWithLabels(a: A, styles: *const profile.Profile, root: *const profile.TextElement,
    source: []const u8, retained: []const u8, rows: ?*const profile.ClosedRowColorProof,
    labels: ?*const profile.SourcePlainLinkLabels) !?*const profile.PageSourceImage
{
    if (!equal(source, retained)) return null;
    var snapshot = retained;
    // The zero-owner variant already owns an independent image. Reuse that
    // allocation as bytes only; its absence/consumption contract stays separate.
    if (rows) |row| if (row.styles == styles and row.root == root and
        row.source.ptr == source.ptr and row.source.len == source.len) {
        if (row.absent_source) |owned| snapshot = owned;
    };
    const value: profile.PageSourceImage = .{ .styles = styles, .root = root,
        .source = source, .snapshot = snapshot, .plain_link_labels = labels,
        .plain_link_namespace = if (labels) |label_proof| .{ .catalog = label_proof.namespace_catalog, .sha256 = label_proof.namespace_sha256 } else null };
    if (!profile.pageSourceImageCurrent(&value)) return null;
    const result = try a.create(profile.PageSourceImage); result.* = value;
    return result;
}

fn observedUnobservedPageCounters(a: A, stored: *const PageStyleData, styles: *const profile.Profile,
    root: *const profile.TextElement, source: []const u8, source_image: ?*const profile.PageSourceImage,
    figures: []const SelectedFigureStyle, context: ?compiler.Context) !?profile.UnobservedCounterResetProof
{
