    for (0..8192) |_| try repeated.appendSlice(a, "class=x ");
    try std.testing.expectEqualStrings("shell root x", try completeObservedTextClassSuperset(a, scope, "shell", repeated.items));
    try repeated.appendSlice(a, "class=x ");
