            for (property) |byte| if (!std.ascii.isAlphabetic(byte) and byte != '-') return false;
            for (content) |byte| if (!std.ascii.isAlphanumeric(byte) and std.mem.indexOfScalar(u8, " #.,%+-", byte) == null) return false;
        }
