            const at = std.math.cast(usize, offset) orelse return 0;
            if (at >= self.bytes.len) return 0;
            const count = @min(destination.len, self.bytes.len - at);
            @memcpy(destination[0..count], self.bytes[at .. at + count]);
            return count;
        }
