    if (!std.unicode.utf8ValidateSlice(value) or std.mem.indexOfAny(u8, raw, "<{}\\\x00") != null or
        std.mem.indexOfAny(u8, value, "{}\\\x00") != null or std.mem.indexOf(u8, value, "[[") != null or
