// Build-only current stylesheet evidence shared by every prefix using these URLs.
// The original receipt remains an input; this never claims historical equality.
pub const TableDirectionResources = struct {
    responses: []const []const u8,
    receipt: []const u8,
};
pub const TableDirectionRoot = struct {
    nodes: []const profile.ObservedStyleNode,
    root: u32,
    sources: []const profile.Source,
};
fn tableDirectionReceiptBool(source: Value, name: []const u8) !bool {
    const value = try field(source, name);
    if (value != .bool) return invalid;
    return value.bool;
}
/// A lexical path to the served normal reading body. Only parent edges and
/// actual attributes are known. Sibling order, :empty and child inventories
/// retain their unknown defaults.
pub fn selectedArticleFontAncestors(a: A, ns: *const namespaces.Registry, html: []const u8, url: []const u8,
    sheets: []const profile.Source, page_id: u64, revision_id: u64, title: []const u8) ![]const profile.ObservedStyleNode {
    const outer = try observedOuterPrefix(a, html, true);
    const prefix = html[0 .. outer.root_open_end orelse return invalid];
    _ = try @import("page_language_prefix.zig").parseSelectedOldidAlloc(a, prefix, page_id, revision_id, 0, title);
    const domain = try missingStyleOrigin(a, ns.wiki);
    if (!std.mem.startsWith(u8, url, domain.origin) or url.len <= domain.origin.len or url[domain.origin.len] != '/') return invalid;
    var links: std.ArrayList([]const u8) = .empty;
    var responses: std.ArrayList([]const u8) = .empty;
    for (sheets) |sheet| if (std.mem.indexOfScalar(u8, sheet.base_url, '#') == null) {
        try links.append(a, sheet.base_url);
        try responses.append(a, sheet.css);
    };
    const closed = try sourceParentOwnedRootEnd(html, prefix);
    const ordered = try sourceParentStyleSourcesIn(a, ns, html, .{ .urls = links.items, .responses = responses.items }, true, url, closed);
    if (sheets.len != ordered.len) return invalid;
    var inline_count: usize = 0;
    for (sheets, ordered) |expected, observed| {
        const expected_url = if (observed.byte_start != 0) blk: {
            const token = try std.fmt.allocPrint(a, "{s}#inline-style-{d}", .{ url, inline_count });
            inline_count += 1;
            break :blk token;
        } else observed.base_url;
        if (!equal(expected_url, expected.base_url) or !equal(expected.css, observed.css)) return invalid;
    }
    const root = outer.root orelse return invalid;
    const nodes = try a.alloc(profile.ObservedStyleNode, outer.ancestors.len + 1);
    for (nodes, 0..) |*node, i| {
        const inv = if (i < outer.ancestors.len) outer.ancestors[i].attributes else root;
        for (inv.attributes) |attr| if (std.ascii.startsWithIgnoreCase(attr.name, "on")) return invalid;
        node.* = .{ .tag = if (i < outer.ancestors.len) outer.ancestors[i].tag else "div",
            .attributes = try figureObservedAttributes(a, inv), .parent = if (i == 0) null else @intCast(i - 1) };
    }
    return nodes;
}

pub fn selectedVectorSchemeClasses(a: A, html: []const u8, wiki: []const u8, nojs: []const u8) !?struct { day: []const u8, night: []const u8 } {
    if (wiki.len == 0 or wiki.len > 128) return null;
    for (wiki) |b| if (!std.ascii.isAlphanumeric(b) and b != '_') return null;
    var at: usize = 0;
    var head = false;
    var js: ?[]const u8 = null;
    while (std.mem.indexOfScalarPos(u8, html, at, '<')) |start| {
        if (std.mem.startsWith(u8, html[start..], "<!--")) {
            at = (std.mem.indexOfPos(u8, html, start + 4, "-->") orelse return null) + 3;
            continue;
        }
        if (std.ascii.startsWithIgnoreCase(html[start..], "<!doctype ")) {
            at = (std.mem.indexOfScalarPos(u8, html, start, '>') orelse return null) + 1;
            continue;
        }
        const tag = currentLiteralHtmlTagAt(html, start) orelse return null;
        at = tag.end;
        if (tag.is("head")) { if (tag.closing or head) return null; head = true; continue; }
        if (tag.is("html") or tag.is("meta") or tag.is("link") or tag.is("base")) continue;
        if (!head or tag.closing) return null;
        if (tag.is("title") or tag.is("style")) { at = try outerRawTextEnd(html, tag); continue; }
        if (!tag.is("script") or tag.self_closing or std.mem.trim(u8, tag.attrs," \r\t\n").len != 0) return null;
        const end = std.mem.indexOfPos(u8,html,at,"</script>") orelse return null;
        js=html[at..end]; break;
    }
    const script = js orelse return null;
    const start = "(function(){var className=\"";
    const boundary = "\";var cookie=document.cookie.match(/(?:^|; )";
    const operation = "mwclientpreferences=([^;]+)/);if(cookie){cookie[1].split('%2C').forEach(function(pref){className=className.replace(new RegExp('(^| )'+pref.replace(/-clientpref-\\w+$|[^\\w-]+/g,'')+'-clientpref-\\\\w+( |$)'),'$1'+pref+'$2');});}document.documentElement.className=className;}());";
    if (!std.mem.startsWith(u8, script, start)) return null;
    const end = std.mem.indexOfPos(u8, script, start.len, boundary) orelse return null;
    const day = script[start.len..end];
    if (day.len == 0 or day.len > 8192) return null;
    for (day) |b| if (!std.ascii.isAlphanumeric(b) and b != '-' and b != ' ' and b != '_') return null;
    var suffix = script[end + boundary.len..];
    if (!std.mem.startsWith(u8, suffix, wiki)) return null;
    suffix = suffix[wiki.len..];
    if (!std.mem.startsWith(u8, suffix, operation)) return null;
    var input = std.mem.tokenizeScalar(u8, nojs, ' ');
    var output = std.mem.tokenizeScalar(u8, day, ' ');
    var client: usize = 0; var theme_at: ?usize = null;
    while (input.next()) |old| {
        const new = output.next() orelse return null;
        if (equal(old, "client-nojs")) {
            if (!equal(new, "client-js")) return null;
            client += 1;
        } else if (!equal(old,new)) return null;
        if (std.mem.startsWith(u8, new, "skin-theme-clientpref-")) {
            if (!equal(new, "skin-theme-clientpref-day") or theme_at != null) return null;
            theme_at = @intFromPtr(new.ptr)-@intFromPtr(day.ptr);
        }
    }
    if (output.next() != null or client != 1) return null;
    const theme = theme_at orelse return null;
    const night = try std.mem.concat(a,u8,&.{day[0..theme],"skin-theme-clientpref-night",day[theme+"skin-theme-clientpref-day".len..]});
    return .{ .day = day, .night = night };
}

pub fn selectedArticleSchemeNodes(a: A, html: []const u8, wiki: []const u8, nodes: []const profile.ObservedStyleNode) !?struct {
    day: []const profile.ObservedStyleNode, night: []const profile.ObservedStyleNode,
} {
    if (nodes.len == 0 or nodes[0].parent != null or !equal(nodes[0].tag,"html")) return null;
    var root_class: ?usize = null;
    for (nodes[0].attributes, 0..) |attr, i| if (equal(attr.name,"class")) {
        if (root_class != null) return null;
        root_class = i;
    };
    const index = root_class orelse return null;
    const classes = (try selectedVectorSchemeClasses(a, html, wiki, nodes[0].attributes[index].value)) orelse return null;
    const day = try a.dupe(profile.ObservedStyleNode, nodes);
    const night = try a.dupe(profile.ObservedStyleNode, nodes);
    for ([_][]profile.ObservedStyleNode{ day, night }, [_][]const u8{ classes.day, classes.night }) |graph, class| {
        const attrs = try a.dupe(profile.FigureObservedAttribute, nodes[0].attributes);
        attrs[index].value = class;
        graph[0].attributes = attrs;
    }
    return .{ .day = day, .night = night };
}

pub fn selectedArticleStyleNodes(a: A, ns: *const namespaces.Registry, html: []const u8,
    ancestors: []const profile.ObservedStyleNode) !?[]const profile.ObservedStyleNode {
    const envelope = try observedOuterPrefix(a, html, true);
    const start = envelope.root_start orelse return null;
    const opening_end = envelope.root_open_end orelse return null;
    const limit = try sourceParentOwnedRootEnd(html, html[0..opening_end]);
    const body = html[start..limit];
    var elements: std.ArrayList(ObservedSiblingNode) = .empty;
    defer elements.deinit(a);
    var end: usize = 0;
    _ = try observedClassRootTokens(a, ns, body, &elements, &end, false, envelope.root, true, true, true);
    if (end != body.len) return null;
    return observedArticleStyleNodes(a, ancestors, elements.items);
}

fn observedArticleStyleNodes(a: A, ancestors: []const profile.ObservedStyleNode,
    nodes: []const ObservedSiblingNode) !?[]const profile.ObservedStyleNode {
    if (ancestors.len == 0 or ancestors.len > 32) return null;
    const offset = ancestors.len-1;
    if (offset+nodes.len > 16384) return null;
    const physical = try a.alloc(profile.ObservedStyleNode, offset+nodes.len);
    @memcpy(physical[0..offset], ancestors[0..offset]);
    for (nodes,0..) |n,i| {
        physical[offset+i] = .{ .tag=n.tag.name,.attributes=try figureObservedAttributes(a,n.attributes),
            .known_no_previous_element_sibling=n.parent!=null and n.previous==null, .known_previous_element_sibling=if(n.previous)|j| @intCast(offset+j) else null,
            .parent=if (n.parent) |j| @intCast(offset+j) else if (offset!=0) @intCast(offset-1) else null };
    }
    // Previous/next facts come from this same complete body. The unknown
    // siblings of outer skin ancestors stay unknown.
    for (nodes,0..) |n,i| if (n.parent != null) {
        const item=&physical[offset+i];
        item.known_no_next_element_sibling=true;
        if (n.previous) |j| {
            physical[offset+j].known_next_element_sibling=@intCast(offset+i);
            physical[offset+j].known_no_next_element_sibling=false;
        }
    };
    return physical;
}

// Inspect the served contents list itself. Both fragment spellings remain
// destinations of the single heading even when the skin omits it from this list.
fn headingAbsentFromContents(a: A, html: []const u8, root_start: usize, primary: []const u8, fallback: []const u8) !bool {
    var at: usize = 0;
    var menus: usize = 0;
    var active: usize = 0;
    var ordinary_anchor = false;
    while (at < root_start) {
        const start = std.mem.indexOfScalarPos(u8, html, at, '<') orelse break;
        if (start >= root_start) break;
        if (std.mem.startsWith(u8, html[start..], "<!--")) {
            at = (std.mem.indexOfPos(u8, html, start + 4, "-->") orelse return false) + 3;
            continue;
        }
        if (std.ascii.startsWithIgnoreCase(html[start..], "<!doctype ")) {
            at = (std.mem.indexOfScalarPos(u8, html, start, '>') orelse return false) + 1;
            continue;
        }
        const tag = currentLiteralHtmlTagAt(html,start) orelse return false;
        at = tag.end;
        if (!tag.closing and (tag.is("script") or tag.is("style") or tag.is("title") or tag.is("noscript"))) {
            at = try outerRawTextEnd(html,tag);
            continue;
        }
        if (tag.is("ul")) {
            if (tag.closing) {
                if (active > 0) active -= 1;
            } else {
                const attrs = try outerInventoryReturned(a,tag,true);
                if (equal(attrs.get("id") orelse "", "mw-panel-toc-list") and
                    profile.Profile.hasClass(attrs.get("class") orelse "", "vector-toc-contents")) {
                    if (active != 0 or menus != 0) return false;
                    menus += 1; active = 1;
                } else if (active != 0) active += 1;
            }
        } else if (active != 0 and tag.is("a") and !tag.closing) {
            const attrs = try outerInventoryReturned(a,tag,true);
            const href = attrs.get("href") orelse return false;
            if (href.len == 0 or href[0] != '#' or std.mem.indexOfAny(u8, href, "%&\r\n\t") != null) return false;
            if (equal(href[1..],primary) or equal(href[1..],fallback)) return false;
            ordinary_anchor = ordinary_anchor or href.len > 1;
        }
    }
    return menus == 1 and active == 0 and ordinary_anchor;
}
/// Closed ParserOutput heading and original parent chain from an already
/// authenticated selected oldid. Source expansion must still match each owner.
pub const WrappedHeadingObservation = struct {
    nodes: []const profile.ObservedStyleNode,
    body: u32, outer: u32, inner: u32, heading: u32, word: u32, sub: u32,
    title: []const u8, language: []const u8, primary: []const u8, fallback: []const u8,
};

fn headingElementChildren( html: []const u8, nodes: []const ObservedSiblingNode,
    parent: usize, comptime count: usize, allow_text: bool) ?[count]usize {
    var children: [count]usize = undefined;
    const node = nodes[parent];
    const end = node.inner_end orelse return null;
    var cursor = node.tag.end;
    var n: usize = 0;
    for (nodes[parent + 1..], parent + 1..) |next, index| {
        if (next.start >= end) break;
        if (next.parent != parent) continue;
        if (n == count or next.start < cursor or (!allow_text and
            std.mem.trim(u8, html[cursor..next.start], " \t\r\n").len != 0)) return null;
        const at = next.inner_end orelse return null;
        const close = syntax.tagAt(html, at) orelse return null;
        if (!close.closing or close.self_closing or close.attrs.len != 0 or !std.ascii.eqlIgnoreCase(close.name, next.tag.name)) return null;
        children[n] = index; n += 1; cursor = close.end;
    }
    if (n != count or cursor > end or (!allow_text and std.mem.trim(u8, html[cursor..end], " \t\r\n").len != 0)) return null;
    return children;
}
fn headingLeafText(html: []const u8, node: ObservedSiblingNode, expected: []const u8) bool {
    const end = node.inner_end orelse return false;
    return node.first_child == null and end >= node.tag.end and equal(html[node.tag.end..end], expected);
}
fn headingEntity(html: []const u8, node: ObservedSiblingNode, text: []const u8) bool {
    return node.tag.is("span") and node.attributes.attributes.len == 1 and
        equal(node.attributes.get("typeof") orelse return false, "mw:Entity") and headingLeafText(html, node, text);
}
fn phonosClass(node: ObservedSiblingNode, tag: []const u8, token: []const u8) bool {
    return node.tag.is(tag) and profile.Profile.hasClass(node.attributes.get("class") orelse "", token);
}

// The old worker preserves the label and file, but omits the localized
// accessible name and attribution action. Read them from the same served
// extension, verifying both are owned by that file before retaining them.
pub fn selectedPhonosAlloc(a: A, keep: A, ns: *const namespaces.Registry, html: []const u8, page_url: []const u8) !?[]profile.PhonosButton {
    // The caller binds this indexed oldid to the complete served article.
    // Keep the observed origin and href; a localized File title is not a
    // dictionary-entry destination.
    const domain = try missingStyleOrigin(a, ns.wiki);
    const prefix = try std.mem.concat(a, u8, &.{ domain.origin, "/w/index.php?" });
    if (!std.mem.startsWith(u8, page_url, prefix)) return null;
    const origin = page_url[0..domain.origin.len];
    if (std.mem.indexOf(u8, html, "mw:Extension/phonos") == null) return null;
    const envelope = try observedOuterPrefix(a, html, true);
    const base = envelope.root_start orelse return null;
    const opening = envelope.root_open_end orelse return null;
    const limit = try sourceParentOwnedRootEnd(html, html[0..opening]);
    const body = html[base..limit];
    var items: std.ArrayList(ObservedSiblingNode) = .empty;
    defer items.deinit(a);
    var end: usize = 0;
    _ = try observedClassRootTokens(a, ns, body, &items, &end, false, envelope.root, true, true, true);
    if (end != body.len) return null;
    const nodes = items.items;
    var buttons: std.ArrayList(profile.PhonosButton) = .empty;
    defer buttons.deinit(a);
    for (nodes, 0..) |node, index| {
        if (!equal(node.attributes.get("typeof") orelse "", "mw:Extension/phonos")) continue;
        if (!phonosClass(node, "span", "ext-phonos")) return null;
        const button = (try observedPhonosButton(a, ns, body, nodes, index, origin)) orelse return null;
        try buttons.append(a, button);
    }
    if (buttons.items.len == 0) return null;
    const retained = try keep.alloc(profile.PhonosButton, buttons.items.len);
    for (buttons.items, retained) |button, *entry| {
        entry.* = button;
        inline for (.{"file", "language", "caption_html", "caption", "accessible_name", "attribution_title", "attribution_target", "attribution_text"}) |name|
            @field(entry, name) = try keep.dupe(u8, @field(button, name));
    }
    return retained;
}

fn observedPhonosButton(a: A, ns: *const namespaces.Registry, body: []const u8,
    nodes: []const ObservedSiblingNode, owner: usize, origin: []const u8) !?profile.PhonosButton {
    const extension = try json(a, nodes[owner].attributes.get("data-mw") orelse return null);
    if (!equal(try string(extension, "name"), "phonos")) return null;
    const attrs = try field(extension, "attrs");
    const file = try string(attrs, "file");
    const lang = try string(attrs, "lang");
    const caption_html = try string(try field(extension, "body"), "extsrc");
    const children = headingElementChildren(body, nodes, owner, 2, false) orelse return null;
    const widget = nodes[children[0]];
    if (file.len == 0 or lang.len == 0 or !phonosClass(widget, "span", "ext-phonos-PhonosButton") or
        !phonosClass(widget, "span", "oo-ui-widget-enabled") or !phonosClass(widget, "span", "oo-ui-buttonElement-frameless") or
        !phonosClass(nodes[children[1]], "sup", "ext-phonos-attribution")) return null;
    const config = try json(a, widget.attributes.get("data-ooui") orelse return null);
    const data = try field(config, "data");
    const framed = try field(config, "framed");
    if (!equal(try string(config, "_"), "mw.Phonos.PhonosButton") or framed != .bool or framed.bool or
        !equal(try string(config, "icon"), "volumeUp") or !equal(try string(data, "lang"), lang) or
        !equal(try string(data, "file"), file) or !equal(try string(try field(config, "label"), "html"), caption_html)) return null;
    const button_id = (headingElementChildren(body, nodes, children[0], 1, false) orelse return null)[0];
    const button = nodes[button_id];
    const href = button.attributes.get("href") orelse return null;
    const name = button.attributes.get("aria-label") orelse return null;
    if (!phonosClass(button, "a", "oo-ui-buttonElement-button") or !equal(button.attributes.get("role") orelse "", "button") or
        !equal(button.attributes.get("tabindex") orelse "", "0") or name.len == 0 or !equal(button.attributes.get("title") orelse "", name) or
        !equal(try string(config, "href"), href)) return null;
    const prefix = "//upload.wikimedia.org/wikipedia/commons/transcoded/";
    if (!std.mem.startsWith(u8, href, prefix) or std.mem.indexOfAny(u8, href, "?#\\") != null) return null;
    var path = std.mem.splitScalar(u8, href[prefix.len..], '/');
    const bucket = path.next() orelse return null;
    const dir = path.next() orelse return null;
    const source_file = path.next() orelse return null;
    const stream = path.next() orelse return null;
    if (path.next() != null or bucket.len != 1 or dir.len != 2 or bucket[0] != dir[0] or
        !std.ascii.isHex(dir[0]) or !std.ascii.isHex(dir[1]) or !std.mem.startsWith(u8, stream, source_file) or
        !equal(stream[source_file.len..], ".mp3")) return null;
    const decoded_file = std.Uri.percentDecodeInPlace(try a.dupe(u8, source_file));
    const expected = try canonicalFile(a, ns, file);
    if (!equal(try canonicalFile(a, ns, decoded_file), expected)) return null;
    const runs = headingElementChildren(body, nodes, button_id, 3, false) orelse return null;
    if (!phonosClass(nodes[runs[0]], "span", "oo-ui-icon-volumeUp") or !headingLeafText(body, nodes[runs[0]], "") or
        !phonosClass(nodes[runs[1]], "span", "oo-ui-labelElement-label") or
        !phonosClass(nodes[runs[2]], "span", "oo-ui-indicatorElement-noIndicator") or !headingLeafText(body, nodes[runs[2]], "")) return null;
    const label_node = nodes[runs[1]];
    const inner = body[label_node.tag.end..label_node.inner_end orelse return null];
    if (!equal(inner, caption_html)) return null;
    const label = if (label_node.first_child == null) inner else child: {
        const id = (headingElementChildren(body, nodes, runs[1], 1, false) orelse return null)[0];
        const caption = nodes[id];
        if (!phonosClass(caption, "span", "e-audio") or caption.attributes.attributes.len != 1 or caption.first_child != null) return null;
        break :child body[caption.tag.end..caption.inner_end orelse return null];
    };
    if (label.len == 0 or std.mem.indexOfAny(u8, label, "&<>\r\n") != null) return null;
    const attribution = nodes[(headingElementChildren(body, nodes, children[1], 1, false) orelse return null)[0]];
    const title = attribution.attributes.get("title") orelse return null;
    const attribution_href = attribution.attributes.get("href") orelse return null;
    const link_file = (try fileHref(a, ns, attribution_href)) orelse return null;
    if (!attribution.tag.is("a") or attribution.attributes.attributes.len != 2 or ns.ofTitle(title).id != 6 or !equal(try canonicalFile(a, ns, title), expected) or
        !equal(link_file, expected) or !equal(ns.ofTitle(title).text, ns.ofTitle(expected).text) or
        !headingLeafText(body, attribution, "ⓘ")) return null;
    const attribution_target = try std.mem.concat(a, u8, &.{ origin, attribution_href });
    if (!encoder.presentation_types.validPhonosCreditDestination(attribution_target, title)) return null;
    return .{ .file = ns.ofTitle(expected).text, .language = lang, .caption_html = caption_html,
        .caption = label, .accessible_name = name, .attribution_title = title,
        .attribution_target = attribution_target, .attribution_text = "ⓘ" };
}

pub fn bindPhonos(a: A, source: []const u8, buttons: []const profile.PhonosButton) ![]const profile.SelectedPhonos {
    if (source.len > max_response or buttons.len == 0) return &.{};
    var pos: usize = 0;
    var result: std.ArrayList(profile.SelectedPhonos) = .empty;
    defer result.deinit(a);
    while (std.mem.indexOfPos(u8, source, pos, "<span")) |start| {
        pos = start + 5;
        const tag = syntax.tagAt(source, start) orelse continue;
        if (!tag.is("span") or tag.closing or tag.self_closing or std.mem.indexOf(u8, tag.attrs, "data-phonos-audio") == null) continue;
        const attrs = try inventory(a, tag);
        if (!equal(attrs.get("class") orelse "", "ext-phonos ext-phonos-PhonosButton")) continue;
        if (result.items.len == buttons.len) return &.{};
        const button = buttons[result.items.len];
        const pair = syntax.matchingTag(source, tag) orelse return &.{};
        if (attrs.attributes.len != 3 or !equal(attrs.get("data-phonos-audio") orelse "", button.file) or
            !equal(attrs.get("lang") orelse "", button.language) or !equal(source[tag.end..pair.inner_end], button.caption_html)) return &.{};
        try result.append(a, .{ .source = source[start..pair.end], .button = button });
        pos = pair.end;
    }
    return if (result.items.len == buttons.len) try result.toOwnedSlice(a) else &.{};
}

fn exampleObservedText(body: []const u8, nodes: []const ObservedSiblingNode, index: usize, value: profile.DescriptionExample.Text) bool {
    const parent = nodes[index];
    const children = headingElementChildren(body,nodes,index,1,true) orelse return false;
    const bold = nodes[children[0]];
    if (!bold.tag.is("b") or bold.attributes.attributes.len != 0 or !headingLeafText(body, bold, value.bold)) return false;
    const close = syntax.tagAt(body, bold.inner_end orelse return false) orelse return false;
    return equal(body[parent.tag.end..bold.start], value.before) and equal(body[close.end..parent.inner_end orelse return false], value.after);
}
fn descriptionNodeAttributes(node: ObservedSiblingNode, allowed: []const []const u8) bool {
    for (node.attributes.attributes) |attr| {
        var known=false;
        for(allowed) |name| if(equal(name,attr.name)) {known=true; break;};
        if(!known) return false;
    }
    return true;
}
/// Bind the actual OL, LI and their owned DL to the same example subtree.
/// The initial physical domain is a single decimal sense. Contiguous
/// multi-item lists remain representable without borrowing this proof.
fn originalOrderedDefinition(a: A, keep: A, ns: *const namespaces.Registry, html: []const u8,
    nodes: []const ObservedSiblingNode, dd: usize, sheets: *const profile.Profile,
    day: []const profile.ObservedStyleNode, night: []const profile.ObservedStyleNode, offset: u32) !?profile.OrderedDefinition {
    const dl = nodes[dd].parent orelse return null;
    const li = nodes[dl].parent orelse return null;
    const ol = nodes[li].parent orelse return null;
    const section = nodes[ol].parent orelse return null;
    if (!nodes[section].tag.is("section") or nodes[section].parent != 0 or !nodes[0].tag.is("div")) return null;
    if (!nodes[ol].tag.is("ol") or !nodes[li].tag.is("li") or !nodes[dl].tag.is("dl") or !nodes[dd].tag.is("dd")) return null;
    // Reversed, start, type or individual LI value require separate marker
    // policy. Do not manufacture a value from the parser's ordinary # index.
    for ([_]usize{ol,li,dl,dd}) |index| if (!descriptionNodeAttributes(nodes[index], &.{"id"})) return null;
    if ((headingElementChildren(html,nodes,ol,1,false) orelse return null)[0] != li or
        (headingElementChildren(html,nodes,dl,1,false) orelse return null)[0] != dd) return null;
    const children = headingElementChildren(html,nodes,li,2,false) orelse return null;
    if (children[1] != dl) return null;
    const link = nodes[children[0]];
    if (!link.tag.is("a") or !descriptionNodeAttributes(link,&.{"id","rel","href","title"}) or link.first_child != null or
        !equal(link.attributes.get("rel") orelse return null, "mw:WikiLink")) return null;
    const title = link.attributes.get("title") orelse return null;
    const href = link.attributes.get("href") orelse return null;
    const label = html[link.tag.end..link.inner_end orelse return null];
    if (title.len == 0 or title.len > 256 or label.len == 0 or label.len > 256 or ns.ofTitle(title).id != 0 or
        std.mem.indexOfAny(u8,title,"_#?%[]{}<>|&\r\n") != null or std.mem.indexOfAny(u8,label,"[]{}<>|&\r\n") != null or
        !equal(title,std.mem.trim(u8,title," \t")) or !equal(label,std.mem.trim(u8,label," \t"))) return null;
    const path = try std.mem.replaceOwned(u8,a,title," ","_");
    const base = (try missingStyleOrigin(a, ns.wiki)).origin;
    const absolute = try std.mem.concat(a,u8,&.{base,"/wiki/",path});
    const relative = try std.mem.concat(a,u8,&.{"./",path});
    if (!equal(href,absolute) and !equal(href,relative)) return null;
    return profile.selectedOrderedDefinition(a,keep,sheets,day,night,offset,
        @intCast(@as(usize,offset)+ol),@intCast(@as(usize,offset)+li),title,label);
}

// A source range is retained even when another paragraph contains the same
// dictionary link. Only the preceding physical line can own this example.
fn orderedDefinitionSource(a:A, full:[]const u8, line:[]const u8, recipe:profile.OrderedDefinition) !?[]const u8 {
    if (@intFromPtr(line.ptr)<@intFromPtr(full.ptr)) return null;
    const at=@intFromPtr(line.ptr)-@intFromPtr(full.ptr);
    if (at == 0 or at > full.len or full[at-1] != '\n') return null;
    const end=at-1;
    const start=if(std.mem.lastIndexOfScalar(u8,full[0..end],'\n')) |prior| prior+1 else 0;
    const original=full[start..end];
    const target_only=equal(recipe.target,recipe.label);
    const simple=try std.fmt.allocPrint(a,"# [[{s}]]",.{recipe.target});
    const labeled=try std.fmt.allocPrint(a,"# [[{s}|{s}]]",.{recipe.target,recipe.label});
    if ((!target_only or !equal(original,simple)) and !equal(original,labeled)) return null;
    return original[2..];
}

fn observedUsageExample(a: A, keep: A, ns: *const namespaces.Registry, body: []const u8, nodes: []const ObservedSiblingNode,
    wrapper: usize, sheets: *const profile.Profile, day: []const profile.ObservedStyleNode,
    night: []const profile.ObservedStyleNode, body_index: u32) !?profile.DescriptionExample {
    const shell = nodes[wrapper];
    const outer = shell.parent orelse return null;
    if (!nodes[outer].tag.is("dd") or !nodes[nodes[outer].parent orelse return null].tag.is("dl") or
        !equal(shell.attributes.get("typeof") orelse "", "mw:Transclusion")) return null;
    if (!descriptionNodeAttributes(shell,&.{"class","about","typeof","id","data-mw"}) or
        !equal(shell.attributes.get("class") orelse "", "usex-item") or
        !descriptionNodeAttributes(nodes[outer],&.{"id"})) return null;
    const only = headingElementChildren(body,nodes,outer,1,false) orelse return null;
    if (only[0] != wrapper) return null;
    const usage = shell.first_child orelse return null;
    if (!phonosClass(nodes[usage],"div","h-usage-example") or nodes[usage].start != shell.tag.end) return null;
    const parts = headingElementChildren(body,nodes,usage,2,false) orelse return null;
    if (!phonosClass(nodes[parts[0]],"i","e-example") or !nodes[parts[1]].tag.is("dl")) return null;
    const inner = (headingElementChildren(body,nodes,parts[1],1,false) orelse return null)[0];
    const trans = (headingElementChildren(body,nodes,inner,1,false) orelse return null)[0];
    if (!nodes[inner].tag.is("dd") or !phonosClass(nodes[trans],"span","e-translation")) return null;
    if(!descriptionNodeAttributes(nodes[usage],&.{"class"}) or !equal(nodes[usage].attributes.get("class") orelse "","h-usage-example") or
        !descriptionNodeAttributes(nodes[parts[0]],&.{"class","lang"}) or !descriptionNodeAttributes(nodes[parts[1]],&.{}) or
        !descriptionNodeAttributes(nodes[inner],&.{}) or !descriptionNodeAttributes(nodes[trans],&.{"class"})) return null;
    const meta = try json(a, shell.attributes.get("data-mw") orelse return null);
    const templates = try field(meta,"parts");
    if (templates != .array or templates.array.items.len != 1) return null;
    const params = try field(try field(templates.array.items[0],"template"),"params");
    const language = try string(try field(params,"1"),"wt");
    const line = try string(try field(params,"2"),"wt");
    const translation = try string(try field(params,"3"),"wt");
    const source_text = profile.DescriptionExample.Text.fromSource(line) orelse return null;
    const translation_text = profile.DescriptionExample.Text.fromSource(translation) orelse return null;
    if (!equal(nodes[parts[0]].attributes.get("lang") orelse "",language) or !exampleObservedText(body,nodes,parts[0],source_text) or
        !exampleObservedText(body,nodes,trans,translation_text)) return null;
    const usage_close = syntax.tagAt(body,nodes[usage].inner_end orelse return null) orelse return null;
    const cat = syntax.tagAt(body,usage_close.end) orelse return null;
    if (!cat.is("link") or cat.closing or !cat.self_closing or cat.end != (shell.inner_end orelse return null)) return null;
    const cat_attrs = try inventory(a,cat);
    if (cat_attrs.attributes.len != 2 or !equal(cat_attrs.get("rel") orelse "","mw:PageProp/Category")) return null;
    const href = cat_attrs.get("href") orelse return null;
    if (!std.mem.startsWith(u8,href,"./") or std.mem.indexOfAny(u8,href[2..],"/?%&") != null) return null;
    const hash = std.mem.indexOfScalar(u8,href,'#') orelse return null;
    const category = ns.ofTitle(href[2..hash]);
    if (category.id != 14 or category.text.len == 0 or hash + 1 == href.len) return null;
    const src_class = nodes[parts[0]].attributes.get("class") orelse return null;
    const trans_class = nodes[trans].attributes.get("class") orelse return null;
    for ([_][]const u8{language,src_class,trans_class}) |attr| {
        if (attr.len == 0 or attr.len > 256) return null;
        for (attr) |b| if (!std.ascii.isAlphanumeric(b) and b != ' ' and b != '-' and b != '_') return null;
    }
    const original = try std.mem.concat(keep,u8,&.{ "<div class=\"usex-item\"><div class=\"h-usage-example\"><i class=\"",src_class,
        "\" lang=\"",language,"\">",line,"</i><dl><dd><span class=\"",trans_class,"\">",translation,"</span></dd></dl></div>" });
    const outer_id = std.math.cast(u32,@as(usize,body_index) + outer) orelse return null;
    const inner_id = std.math.cast(u32,@as(usize,body_index) + inner) orelse return null;
    const wd = (try profile.observedDescriptionWrappers(a,sheets,day,body_index,
        @intCast(@as(usize,body_index)+wrapper),@intCast(@as(usize,body_index)+usage),@intCast(@as(usize,body_index)+parts[1]))) orelse return null;
    const wn = (try profile.observedDescriptionWrappers(a,sheets,night,body_index,
        @intCast(@as(usize,body_index)+wrapper),@intCast(@as(usize,body_index)+usage),@intCast(@as(usize,body_index)+parts[1]))) orelse return null;
    if (!std.meta.eql(wd,wn)) return null;
    const outer_day = (try profile.observedDescriptionBefore(a,sheets,day,body_index,outer_id)) orelse return null;
    const inner_day = (try profile.observedDescriptionBefore(a,sheets,day,body_index,inner_id)) orelse return null;
    const outer_night = (try profile.observedDescriptionBefore(a,sheets,night,body_index,outer_id)) orelse return null;
    const inner_night = (try profile.observedDescriptionBefore(a,sheets,night,body_index,inner_id)) orelse return null;
    for ([_]profile.DescriptionBeforeMetrics{ outer_day, inner_day }, [_]profile.DescriptionBeforeMetrics{ outer_night, inner_night }) |light,dark|
        inline for (.{ "owner_scale", "padding_left", "top", "bottom", "left", "width" }) |key| {
            if (!std.meta.eql(@field(light,key),@field(dark,key))) return null;
        };
    const wrapper_id: u32 = @intCast(@as(usize, body_index) + wrapper);
    const light_line = try profile.observedSubtreeLineHeight(a, sheets, day, body_index, wrapper_id);
    const dark_line = try profile.observedSubtreeLineHeight(a, sheets, night, body_index, wrapper_id);
    const held_line = try keep.dupe(u8,line);
    const held_translation = try keep.dupe(u8,translation);
    var od=outer_day; var id=inner_day;
    od.color.value = try keep.dupe(u8,outer_day.color.value.?);
    id.color.value = try keep.dupe(u8,inner_day.color.value.?);
    return .{ .start=original, .category=try std.mem.replaceOwned(u8,keep,category.text,"_"," "), .key=try keep.dupe(u8,href[hash+1..]),
        .source_text=profile.DescriptionExample.Text.fromSource(held_line).?, .translation_text=profile.DescriptionExample.Text.fromSource(held_translation).?,
        .language=try keep.dupe(u8,language), .outer_before=od, .inner_before=id, .usage_scale=wd.usage, .wrapper_scale=wd.wrapper,
        .ordered=try originalOrderedDefinition(a,keep,ns,body,nodes,outer,sheets,day,night,body_index),
        .wrapper_line_height=if (light_line == dark_line) light_line else null,
        .outer_ink=.{.light_dark=.{.light=od.color.value.?,.dark=try keep.dupe(u8,outer_night.color.value.?)}},
        .inner_ink=.{.light_dark=.{.light=id.color.value.?,.dark=try keep.dupe(u8,inner_night.color.value.?)}},
    };
}

// The audio action and its independent attribution already have their own
// source proof. Paint a list rail only when the very same two actions are the
// whole visible content of an original DD. Preserve an empty adjacent DD.
fn observePhonosDescriptions(a: A, keep: A, ns: *const namespaces.Registry, body: []const u8,
    nodes: []const ObservedSiblingNode, sheets: *const profile.Profile, day: []const profile.ObservedStyleNode,
    night: []const profile.ObservedStyleNode, root: u32, buttons: []profile.PhonosButton) !void {
    if (buttons.len == 0) return;
    var count: usize = 0;
    for (nodes) |node| if (equal(node.attributes.get("typeof") orelse "", "mw:Extension/phonos")) { count += 1; };
    if (count != buttons.len) return;
    var index: usize = 0;
    for (nodes, 0..) |node, i| {
        if (!equal(node.attributes.get("typeof") orelse "", "mw:Extension/phonos")) continue;
        const button = &buttons[index];
        index += 1;
        const owner = node.parent orelse continue;
        const dd = nodes[owner];
        if (!dd.tag.is("dd") or dd.attributes.attributes.len != 0 or dd.first_child != i or dd.tag.end != node.start or
            !nodes[dd.parent orelse continue].tag.is("dl")) continue;
        const close = syntax.tagAt(body, node.inner_end orelse continue) orelse continue;
        const end = dd.inner_end orelse continue;
        if (!close.closing or !close.is("span") or close.end > end) continue;
        const suffix: []const u8 = if (close.end == end) "" else category: {
            const tag = syntax.tagAt(body,close.end) orelse continue;
            if (!tag.is("link") or tag.closing or tag.end != end) continue;
            const attrs = try inventory(a,tag);
            if (attrs.attributes.len != 2 or !equal(attrs.get("rel") orelse continue,"mw:PageProp/Category")) continue;
            const href = attrs.get("href") orelse continue;
            if (!std.mem.startsWith(u8,href,"./") or ns.ofTitle(href[2..]).id != 14 or
                std.mem.indexOfAny(u8,href[2..],"%#[]|<>&\r\n") != null) continue;
            const title = try std.mem.replaceOwned(u8,a,href[2..],"_"," ");
            break :category try std.mem.concat(a,u8,&.{"[[",title,"]]"});
        };
        const physical: u32 = @intCast(@as(usize,root) + owner);
        const light = (try profile.observedDescriptionBefore(a,sheets,day,root,physical)) orelse continue;
        const dark = (try profile.observedDescriptionBefore(a,sheets,night,root,physical)) orelse continue;
        var same = true;
        inline for (.{"owner_scale","padding_left","top","bottom","left","width"}) |key|
            same = same and std.meta.eql(@field(light,key),@field(dark,key));
        if (same) {
            const light_color = try keep.dupe(u8,light.color.value orelse continue);
            const dark_color = try keep.dupe(u8,dark.color.value orelse continue);
            var before = light;
            before.color.value = light_color;
            const parts = headingElementChildren(body,nodes,i,2,false) orelse continue;
            const sup = parts[1];
            const anchor = (headingElementChildren(body,nodes,sup,1,false) orelse continue)[0];
            const lines = try profile.selectedPhonosLines(a,sheets,day,night,root,physical,
                @intCast(@as(usize,root)+i),@intCast(@as(usize,root)+sup),@intCast(@as(usize,root)+anchor));
            button.description = .{.suffix=try keep.dupe(u8,suffix),.before=before,.lines=lines,
                .ink=.{.light_dark=.{.light=light_color,.dark=dark_color}}};
        }
    }
}

pub fn selectedDescriptionsAlloc(a: A, keep: A, ns: *const namespaces.Registry, html: []const u8,
    ancestors: []const profile.ObservedStyleNode, sheets: *const profile.Profile, buttons: []profile.PhonosButton) ![]const profile.DescriptionExample {
    if (ancestors.len == 0 or (buttons.len == 0 and std.mem.indexOf(u8,html,"usex-item") == null)) return &.{};
    const envelope = try observedOuterPrefix(a,html,true);
    const base = envelope.root_start orelse return &.{};
    const opening = envelope.root_open_end orelse return &.{};
    const limit = try sourceParentOwnedRootEnd(html, html[0..opening]);
    const body = html[base..limit];
    var original: std.ArrayList(ObservedSiblingNode) = .empty; defer original.deinit(a);
    var end: usize = 0;
    _ = try observedClassRootTokens(a,ns,body,&original,&end,false,envelope.root,true,true,true);
    if (end != body.len) return &.{};
    const physical = (try observedArticleStyleNodes(a,ancestors,original.items)) orelse return &.{};
    const schemes = (try selectedArticleSchemeNodes(a,html,ns.wiki,physical)) orelse return &.{};
    try observePhonosDescriptions(a,keep,ns,body,original.items,sheets,schemes.day,schemes.night,@intCast(ancestors.len-1),buttons);
    var recipes: std.ArrayList(profile.DescriptionExample) = .empty;
    for (original.items,0..) |node,index| {
        if (!phonosClass(node,"div","usex-item")) continue;
        const value = (try observedUsageExample(a,a,ns,body,original.items,index,sheets,schemes.day,schemes.night,@intCast(ancestors.len-1))) orelse return &.{};
        try recipes.append(a,value);
    }
    const result=try keep.alloc(profile.DescriptionExample,recipes.items.len);
    for (result,recipes.items) |*held,recipe| {
        held.*=recipe;
        if(recipe.ordered) |ordered| {
            held.ordered.?.target=try keep.dupe(u8,ordered.target);
            held.ordered.?.label=try keep.dupe(u8,ordered.label);
        }
        inline for (.{ "start","category","key","language" }) |key| @field(held,key)=try keep.dupe(u8,@field(recipe,key));
        inline for (.{ "source_text","translation_text" }) |text_key| {
            inline for (.{ "before","bold","after" }) |key| @field(@field(held,text_key),key)=try keep.dupe(u8,@field(@field(recipe,text_key),key));
        }
        inline for (.{ "outer_ink","inner_ink" },.{ "outer_before","inner_before" }) |ink,metric| {
            @field(held,ink)=.{.light_dark=.{.light=try keep.dupe(u8,@field(recipe,ink).light_dark.light),
                .dark=try keep.dupe(u8,@field(recipe,ink).light_dark.dark)}};
            @field(held,metric).color.value=@field(held,ink).light_dark.light;
        }
    }
    return result;
}

// The authored wrapper, the generated DL, the DT and the inline file are
// distinct physical owners. Recover the worker's original list syntax only
// after confirming every visible piece and every trailing Parsoid category.
const IndexedTermShape = struct {
    wrapper: u32, list: u32, term: u32, icon: u32, image: ?u32,
    source: []const u8, label: []const u8, file: []const u8, width: u32,
};
fn indexedTermShape(a: A, ns: *const namespaces.Registry, body: []const u8,
    nodes: []const ObservedSiblingNode, root: usize, offset: usize) !?IndexedTermShape {
    const shell = nodes[root];
    if (!shell.tag.is("div") or !descriptionNodeAttributes(shell, &.{"class", "id", "about"})) return null;
    const classes = shell.attributes.get("class") orelse return null;
    const dl = (headingElementChildren(body, nodes, root, 1, false) orelse return null)[0];
    if (!nodes[dl].tag.is("dl") or nodes[dl].attributes.attributes.len != 0) return null;
    const dt = (headingElementChildren(body, nodes, dl, 1, false) orelse return null)[0];
    if (!nodes[dt].tag.is("dt") or nodes[dt].attributes.attributes.len != 0) return null;
    const icon = nodes[dt].first_child orelse return null;
    if (!nodes[icon].tag.is("span") or nodes[icon].start != nodes[dt].tag.end or nodes[icon].attributes.attributes.len != 1) return null;
    const icon_class = nodes[icon].attributes.get("class") orelse return null;
    for ([_][]const u8{classes,icon_class}) |value| {
        if (value.len == 0 or value.len > 256) return null;
        for (value) |c| if (!std.ascii.isAlphanumeric(c) and c != '-' and c != '_' and c != ' ') return null;
    }
    const file_span = (headingElementChildren(body, nodes, icon, 1, false) orelse return null)[0];
    if (!nodes[file_span].tag.is("span") or nodes[file_span].attributes.attributes.len != 1 or
        !equal(nodes[file_span].attributes.get("typeof") orelse return null, "mw:File")) return null;
    const holder = (headingElementChildren(body, nodes, file_span, 1, false) orelse return null)[0];
    if (!nodes[holder].tag.is("span") or nodes[holder].attributes.attributes.len != 0) return null;
    const img = syntax.tagAt(body, nodes[holder].tag.end) orelse return null;
    if (!img.is("img") or img.closing or !img.self_closing or img.end != (nodes[holder].inner_end orelse return null)) return null;
    const attrs = try inventory(a,img);
    const resource = attrs.get("resource") orelse return null;
    const origin = (try missingStyleOrigin(a,ns.wiki)).origin;
    if (!std.mem.startsWith(u8,resource,origin)) return null;
    const file = (try fileHref(a,ns,resource[origin.len..])) orelse return null;
    const width = std.fmt.parseInt(u32, attrs.get("width") orelse return null, 10) catch return null;
    if (width == 0 or width > 1024 or !equal(attrs.get("width").?,attrs.get("height") orelse return null)) return null;
    const intrinsic_w = std.fmt.parseInt(u32,attrs.get("data-file-width") orelse "",10) catch 0;
    const intrinsic_h = std.fmt.parseInt(u32,attrs.get("data-file-height") orelse "",10) catch 0;
    const image_index = nodes[holder].first_child;
    const eligible_image: ?u32=if(image_index!=null and nodes[image_index.?].tag.is("img") and
        nodes[image_index.?].parent==holder and nodes[image_index.?].start==nodes[holder].tag.end and
        intrinsic_w>0 and intrinsic_w==intrinsic_h) @intCast(offset+image_index.?) else null;
    const icon_end = (syntax.tagAt(body,nodes[icon].inner_end orelse return null) orelse return null).end;
    const label_end = std.mem.indexOfScalarPos(u8,body,icon_end,'<') orelse return null;
    const label = body[icon_end..label_end];
    if (label.len == 0 or label.len > 256 or !equal(label,std.mem.trim(u8,label," \t\r\n")) or std.mem.indexOfAny(u8,label,"&[]{}<>\r\n'") != null) return null;
    const entity = "<span typeof=\"mw:Entity\"> </span>";
    if (!std.mem.startsWith(u8,body[label_end..],entity)) return null;
    var at = label_end + entity.len;
    var original: std.Io.Writer.Allocating = .init(a);
    try original.writer.print("<div class=\"{s}\">\n; <span class=\"{s}\">[[File:{s}|{d}px|link=]]</span>{s}&#32;", .{classes,icon_class,ns.ofTitle(file).text,width,label});
    const end = nodes[dt].inner_end orelse return null;
    while (at < end) {
        const cat = syntax.tagAt(body,at) orelse return null;
        if (!cat.is("link") or cat.closing or !cat.self_closing or cat.end>end) return null;
        const meta = try inventory(a,cat);
        if (meta.attributes.len!=2 or !equal(meta.get("rel") orelse return null,"mw:PageProp/Category")) return null;
        const href=meta.get("href") orelse return null;
        if (!std.mem.startsWith(u8,href,"./") or std.mem.indexOfAny(u8,href[2..],"?%&[]{}\r\n|")!=null) return null;
        const hash=std.mem.indexOfScalar(u8,href,'#') orelse return null;
        if (hash<=2 or hash+1==href.len or ns.ofTitle(href[2..hash]).id!=14) return null;
        const title=try std.mem.replaceOwned(u8,a,href[2..hash],"_"," ");
        try original.writer.print("[[{s}|{s}]]",.{title,href[hash+1..]});
        at=cat.end;
    }
    try original.writer.writeAll("</div>");
    return .{.wrapper=@intCast(offset+root),.list=@intCast(offset+dl),.term=@intCast(offset+dt),.icon=@intCast(offset+icon),.image=eligible_image,
        .source=try original.toOwnedSlice(),.label=label,.file=ns.ofTitle(file).text,.width=width};
}

// This one edge is proved by the closed source elements on both sides. A
// STYLE in an otherwise empty SPAN has no parser-implied sibling elements.
// Neither absence of a previous element nor any outer sibling is inferred.
fn termPreviousStyleSibling(html: []const u8, nodes: []const ObservedSiblingNode, root: usize, offset: usize) ?u32 {
    const owner = nodes[root];
    const parent = owner.parent orelse return null;
    if (!nodes[parent].tag.is("section") or nodes[parent].parent != 0 or !nodes[0].tag.is("div")) return null;
    const index = owner.previous orelse return null;
    const previous = nodes[index];
    if (previous.parent != parent or !previous.tag.is("span") or previous.tag.self_closing) return null;
    const style = previous.first_child orelse return null;
    const child = nodes[style];
    if (style != index + 1 or root != style + 1 or child.parent != index or child.previous != null or
        !child.tag.is("style") or child.tag.self_closing or child.start < previous.tag.end or child.first_child != null or
        !figureSiblingGap(html[previous.tag.end..child.start], false)) return null;
    const style_end = child.tag.end;
    var closing = style_end;
    while (closing < html.len and !std.ascii.startsWithIgnoreCase(html[closing..], "</style")) : (closing += 1) {}
    const close_style = syntax.tagAt(html, closing) orelse return null;
    const close_span_at = previous.inner_end orelse return null;
    if (!close_style.is("style") or !close_style.closing or close_style.self_closing or close_style.attrs.len != 0 or
        close_style.end > close_span_at or !figureSiblingGap(html[close_style.end..close_span_at], false)) return null;
    const close_span = syntax.tagAt(html, close_span_at) orelse return null;
    if (!close_span.is("span") or !close_span.closing or close_span.self_closing or close_span.attrs.len != 0 or
        close_span.end > owner.start or !figureSiblingGap(html[close_span.end..owner.start], false)) return null;
    return @intCast(offset+index);
}

pub fn selectedTermsAlloc(a:A,keep:A,ns:*const namespaces.Registry,html:[]const u8,ancestors:[]const profile.ObservedStyleNode,sheets:*const profile.Profile) ![]const profile.SourceTerm {
    if(ancestors.len==0 or std.mem.indexOf(u8,html,"</dt>")==null)return &.{};
    const envelope=try observedOuterPrefix(a,html,true);
    const base=envelope.root_start orelse return &.{};const opening=envelope.root_open_end orelse return &.{};
    const limit=try sourceParentOwnedRootEnd(html,html[0..opening]);const body=html[base..limit];
    var original:std.ArrayList(ObservedSiblingNode)=.empty;defer original.deinit(a);var end:usize=0;
    _=try observedClassRootTokens(a,ns,body,&original,&end,false,envelope.root,true,true,true);
    if(end!=body.len)return &.{};
    const physical=(try observedArticleStyleNodes(a,ancestors,original.items)) orelse return &.{};
    const schemes=(try selectedArticleSchemeNodes(a,html,ns.wiki,physical)) orelse return &.{};
    var terms:std.ArrayList(profile.SourceTerm)=.empty;defer terms.deinit(a);
    for(original.items)|node|{
        if(!node.tag.is("dl"))continue;
        const root=node.parent orelse continue;
        const shape=(try indexedTermShape(a,ns,body,original.items,root,ancestors.len-1)) orelse continue;
        const paint=(try profile.selectedTermPaint(a,keep,sheets,schemes.day,schemes.night,@intCast(ancestors.len-1),.{shape.wrapper,shape.list,shape.term,shape.icon},termPreviousStyleSibling(body,original.items,root,ancestors.len-1))) orelse continue;
        const reserve=if(shape.image) |index| (try profile.termImageDimensionsUnchanged(a,sheets,schemes.day,@intCast(ancestors.len-1),index)) and
            (try profile.termImageDimensionsUnchanged(a,sheets,schemes.night,@intCast(ancestors.len-1),index)) else false;
        try terms.append(a,.{.height=if(reserve) shape.width else null,.source=try keep.dupe(u8,shape.source),.label=try keep.dupe(u8,shape.label),.file=try keep.dupe(u8,shape.file),.width=shape.width,.paint=paint});
    }
    return try keep.dupe(profile.SourceTerm,terms.items);
}

pub fn bindTerms(a:A,source:[]const u8,terms:[]const profile.SourceTerm)![]const profile.SelectedTerm {
    if(terms.len==0 or source.len>max_response)return &.{};
    var matches:std.ArrayList(profile.SelectedTerm)=.empty;
    defer matches.deinit(a);
    var pos:usize=0;
    // Match only the source opening and bound body. A page with thousands of
    // unrelated nested DIVs must not walk each entire subtree for this join.
    while(std.mem.indexOfPos(u8,source,pos,"<div"))|start|{
        pos=start+4;
        const tag=syntax.tagAt(source,start) orelse continue;
        if(!tag.is("div") or tag.closing)continue;
        for(terms)|term|if(std.mem.startsWith(u8,source[start..],term.source)){
            const candidate=source[start..][0..term.source.len];
            if(matches.items.len>=terms.len or !equal(terms[matches.items.len].source,candidate))return &.{};
            try matches.append(a,.{.source=candidate,.recipe=terms[matches.items.len]});
            pos=start+candidate.len;break;
        };
    }
    return if(matches.items.len==terms.len) try matches.toOwnedSlice(a) else &.{};
}

pub fn bindDescriptions(a: A, ns: *const namespaces.Registry, source: []const u8,
    recipes: []const profile.DescriptionExample) ![]const profile.SelectedDescriptionExample {
    if (recipes.len == 0 or source.len > max_response) return &.{};
    var found: std.ArrayList(profile.SelectedDescriptionExample) = .empty;
    defer found.deinit(a);
    var lines=std.mem.splitScalar(u8,source,'\n');
    while (lines.next()) |line| {
        const prefix="#: ";
        if (!std.mem.startsWith(u8,line,prefix)) continue;
        const raw = line[prefix.len..];
        if (!std.mem.startsWith(u8, raw,"<div class=\"usex-item\">")) continue;
        if (found.items.len>=recipes.len) return &.{};
        const r=recipes[found.items.len];
        if (!std.mem.startsWith(u8,raw,r.start)) return &.{};
        const tail=raw[r.start.len..];
        if (!std.mem.startsWith(u8,tail,"[[") or !std.mem.endsWith(u8,tail,"]]</div>")) return &.{};
        const category=tail[2..tail.len-"]]</div>".len];
        const pipe=std.mem.indexOfScalar(u8,category,'|') orelse return &.{};
        const title=ns.ofTitle(category[0..pipe]);
        if (title.id!=14 or !equal(title.text,r.category) or !equal(category[pipe+1..],r.key)) return &.{};
        try found.append(a,.{.source=raw,.recipe=r,.definition_source=if (r.ordered) |ordered| try orderedDefinitionSource(a,source,line,ordered) else null});
    }
    return if (found.items.len==recipes.len) try found.toOwnedSlice(a) else &.{};
}

pub fn selectedWrappedHeadingAlloc(a: A, ns: *const namespaces.Registry, html: []const u8,
    ancestors: []const profile.ObservedStyleNode, page_title: []const u8) !?WrappedHeadingObservation {
    if (ancestors.len == 0 or ancestors.len > 32) return null;
    const envelope = try observedOuterPrefix(a, html, true);
    const base = envelope.root_start orelse return null;
    const opening = envelope.root_open_end orelse return null;
    const limit = try sourceParentOwnedRootEnd(html, html[0..opening]);
    const body = html[base..limit];
    var original: std.ArrayList(ObservedSiblingNode) = .empty; defer original.deinit(a);
    var end: usize = 0;
    _ = try observedClassRootTokens(a, ns, body, &original, &end, false, envelope.root, true, true, true);
    if (end != body.len) return null;
    const nodes = original.items;
    var found: ?usize = null;
    for (nodes, 0..) |n,i| if (n.tag.is("h3") and equal(n.attributes.get("data-title") orelse "",page_title)) {
        if (found != null) return null;
        found = i;
    };
    const hi = found orelse return null;
    const h = nodes[hi]; const inner = h.parent orelse return null; const outer = nodes[inner].parent orelse return null;
    const section = nodes[outer].parent orelse return null;
    if (!nodes[section].tag.is("section") or nodes[section].parent != 0 or
        !nodes[outer].tag.is("div") or !nodes[inner].tag.is("div") or
        (headingElementChildren( body, nodes, outer, 1, false) orelse return null)[0] != inner or
        (headingElementChildren( body, nodes, inner, 1, false) orelse return null)[0] != hi) return null;
    const language = h.attributes.get("data-lang") orelse return null;
    const primary = h.attributes.get("id") orelse return null;
    if (language.len == 0 or primary.len == 0) return null;
    const title_children = (headingElementChildren(body,nodes,hi,2,false)) orelse return null;
    const fallback_node = nodes[title_children[0]]; const group = nodes[title_children[1]];
    const fallback = fallback_node.attributes.get("id") orelse return null;
    if (!fallback_node.tag.is("span") or !equal(fallback_node.attributes.get("typeof") orelse "", "mw:FallbackId") or
        fallback_node.attributes.attributes.len != 2 or !headingLeafText(body,fallback_node,"") or
        fallback.len == 0 or equal(fallback, primary) or !group.tag.is("span")) return null;
    if (!try headingAbsentFromContents(a, html, base, primary, fallback)) return null;
    const runs = (headingElementChildren(body,nodes,title_children[1],3,false)) orelse return null;
    const word = nodes[runs[0]]; const sub = nodes[runs[2]];
    if (!word.tag.is("span") or !headingLeafText(body,word,page_title) or
        !headingEntity(body,nodes[runs[1]]," ") or !sub.tag.is("sub")) return null;
    const brackets = (headingElementChildren(body,nodes,runs[2],2,true)) orelse return null;
    if (!headingEntity(body,nodes[brackets[0]],"[") or !headingEntity(body,nodes[brackets[1]],"]")) return null;
    const left = nodes[brackets[0]]; const right = nodes[brackets[1]];
    const left_close = syntax.tagAt(body,left.inner_end.?) orelse return null;
    const right_close = syntax.tagAt(body,right.inner_end.?) orelse return null;
    if (left.start != sub.tag.end or right_close.end != sub.inner_end.? or !equal(body[left_close.end..right.start],language)) return null;
    const offset = ancestors.len-1;
    const physical = (try observedArticleStyleNodes(a, ancestors, nodes)) orelse return null;
    return .{ .nodes=physical,.body=@intCast(offset),.outer=@intCast(offset+outer),.inner=@intCast(offset+inner),
        .heading=@intCast(offset+hi),.word=@intCast(offset+runs[0]),.sub=@intCast(offset+runs[2]),
        .title=page_title,.language=language,.primary=primary,.fallback=fallback };
}

// Compare the original worker's source with the authenticated served owners.
// Generated HTML ids/entity spans and transclusion metadata are never copied
// into the expanded source. All authored attributes and text must match.
fn headingSourceOpening(a: A, source: []const u8, cursor: *usize, witness: profile.ObservedStyleNode,
    fields: []const []const u8) !bool {
    while (cursor.* < source.len and std.ascii.isWhitespace(source[cursor.*])) cursor.* += 1;
    const tag = syntax.tagAt(source, cursor.*) orelse return false;
    if (tag.closing or tag.self_closing or !tag.is(witness.tag)) return false;
    const actual = try inventory(a,tag);
    if (actual.attributes.len != fields.len) return false;
    for (fields) |name| {
        const value = actual.get(name) orelse return false;
        var matched = false;
        for (witness.attributes) |attr| if (equal(attr.name,name)) {
            matched = equal(attr.value,value); break;
        };
        if (!matched) return false;
    }
    cursor.*=tag.end;
    return true;
}
fn headingSourceClose(source: []const u8, cursor: *usize, name: []const u8, blank: bool) bool {
    if (blank) while (cursor.* < source.len and std.ascii.isWhitespace(source[cursor.*])) { cursor.* += 1; };
    const tag=syntax.tagAt(source,cursor.*) orelse return false;
    if (!tag.is(name) or !tag.closing or tag.self_closing or std.mem.trim(u8,tag.attrs," \t\r\n").len!=0) return false;
    cursor.*=tag.end;
    return true;
}
fn headingSourceText(source: []const u8, cursor: *usize, expected: []const u8) bool {
    if (!std.mem.startsWith(u8,source[cursor.*..],expected)) return false;
    cursor.*+=expected.len;
    return true;
}
fn headingSourceAt(a: A, source: []const u8, start: usize, p: profile.WrappedHeadingRecipe) !?struct { end: usize, body_offset: usize } {
    var pos=start;
    if (!try headingSourceOpening(a,source,&pos,p.owners[0],&.{"class","title","style"}) or
        !try headingSourceOpening(a,source,&pos,p.owners[1],&.{"class","style"}) or
        !try headingSourceOpening(a,source,&pos,p.owners[2],&.{"data-lang","data-title","style"})) return null;
    const body_offset = pos-start;
    if (!try headingSourceOpening(a,source,&pos,p.owners[3],&.{"class"}) or
        !try headingSourceOpening(a,source,&pos,p.owners[4],&.{"style"}) or
        !headingSourceText(source,&pos,p.title) or !headingSourceClose(source,&pos,"span",false) or
        !headingSourceText(source,&pos,"&#32;") or
        !try headingSourceOpening(a,source,&pos,p.owners[5],&.{"style"}) or
        !headingSourceText(source,&pos,"&#91;") or !headingSourceText(source,&pos,p.language) or
        !headingSourceText(source,&pos,"&#93;") or !headingSourceClose(source,&pos,"sub",false) or
        !headingSourceClose(source,&pos,"span",false) or !headingSourceClose(source,&pos,"h3",true) or
        !headingSourceClose(source,&pos,"div",true) or !headingSourceClose(source,&pos,"div",true)) return null;
    return .{.end=pos,.body_offset=body_offset};
}
pub fn bindWrappedHeading(a: A, source: []const u8, p: profile.WrappedHeadingRecipe) !?profile.SelectedWrappedHeading {
    if (source.len == 0 or source.len > max_response or p.title.len == 0 or p.language.len == 0 or
        std.mem.indexOfAny(u8,p.title,"<>&[{}]'|\r\n")!=null or std.mem.indexOfAny(u8,p.language,"<>&[{}]'|\r\n")!=null) return null;
    var at:usize=0; var result:?profile.SelectedWrappedHeading=null;
    while (std.mem.indexOfPos(u8,source,at,"<div")) |start| {
        at=start+4;
        const end=headingSourceAt(a,source,start,p) catch |err| switch(err){error.OutOfMemory=>return err,else=>continue};
        if(end) |last| {
            if (result!=null) return null;
            result=.{.source=source[start..last.end],.body_offset=last.body_offset,.recipe=p};
        }
    }
    return result;
}

pub fn tableDirectionRootAlloc(a: A, ns: *const namespaces.Registry, bytes: []const u8,
    page_id: u64, revision_id: u64, resources: TableDirectionResources) !TableDirectionRoot
{
    // Revision identity and the complete lexical outer chain are independently
    // checked by the maintained prefix parser before retaining style attributes.
    const outer = try observedOuterPrefix(a, bytes, true);
    _ = try @import("page_language_prefix.zig").parseAlloc(a, bytes[0..outer.root_open_end orelse return invalid], page_id, revision_id);
    const root = outer.root orelse return invalid;
    const receipt = try json(a, resources.receipt);
    if (receipt != .object or receipt.object.count() != 4 or
        try field(receipt, "core") != .null or try field(receipt, "historical_equality_proven") != .bool or
        (try field(receipt, "historical_equality_proven")).bool) return invalid;
    const unrequested = try field(receipt, "unrequested");
    if (unrequested != .array or unrequested.array.items.len != 0) return invalid;
    const sources = try field(receipt, "sources");
    if (sources != .array or sources.array.items.len != resources.responses.len) return invalid;
    for (sources.array.items) |source| {
        if (!(try tableDirectionReceiptBool(source, "accepted")) or !(try tableDirectionReceiptBool(source, "response_complete")) or
            try tableDirectionReceiptBool(source, "unknown_response_outcome") or try number(source, "request_count") != 1) return invalid;
    }
    // Preserve the old validator's exact finite contract. The new receipt's
    // extra acquisition facts were validated above, not silently discarded.
    const neutral = try std.json.Stringify.valueAlloc(a, .{ .core = @as(?u8, null), .sources = sources }, .{});
    const served = try validateObservedStyleSet(a, .{ .responses = resources.responses, .receipt = neutral }, ns.wiki);
    const head_sources = try figureStyleGetHeadSources(a, ns, bytes, served);
    // All resources in this root's set must actually occur in its ordered head.
    // Sharing a superset is deliberately left to an explicit index selection.
    if (head_sources.len != served.responses.len) return invalid;
    const nodes = try a.alloc(profile.ObservedStyleNode, outer.ancestors.len + 1);
    for (outer.ancestors, 0..) |node, index| {
        for (node.attributes.attributes) |attribute| if (attribute.name.len >= 2 and std.ascii.eqlIgnoreCase(attribute.name[0..2], "on")) return invalid;
        const attributes = try a.alloc(profile.FigureObservedAttribute, node.attributes.attributes.len);
        for (node.attributes.attributes, attributes) |attribute, *out| out.* = .{ .name = attribute.name, .value = attribute.value };
        nodes[index] = .{ .tag = node.tag, .attributes = attributes,
            .parent = if (index == 0) null else @intCast(index - 1) };
    }
    const attributes = try a.alloc(profile.FigureObservedAttribute, root.attributes.len);
    for (root.attributes, attributes) |attribute, *out| {
        if (attribute.name.len >= 2 and std.ascii.eqlIgnoreCase(attribute.name[0..2], "on")) return invalid;
        out.* = .{ .name = attribute.name, .value = attribute.value };
    }
    nodes[outer.ancestors.len] = .{ .tag = "div", .attributes = attributes, .parent = @intCast(outer.ancestors.len - 1) };
    return .{ .nodes = nodes, .root = @intCast(nodes.len - 1), .sources = head_sources };
}

pub const TableDirectionLocalParent = struct { opening: []const u8, tag: []const u8, attributes: []const profile.FigureObservedAttribute };
// A source definition/example can start with a numeric reference marker. Only
// the complete indented note token is neutral; arbitrary brackets still refuse.
fn tableDirectionNoteEnd(source: []const u8, at: usize) ?usize {
    if (at == 0 or source[at - 1] != ':' or (at != 1 and source[at - 2] != '\n')) return null;
    var end = at + 1;
    while (end < source.len and std.ascii.isDigit(source[end])) : (end += 1) {}
    if (end == at + 1 or end - at > 10 or !std.mem.startsWith(u8, source[end..], "]:")) return null;
    return end + 2;
}

fn tableDirectionPlainHeading(line: []const u8) bool {
    const heading = syntax.controlHeading(line, null) orelse return false;
    const level: usize = heading.level;
    if (line.len != 2 * level + heading.title.len or std.mem.trim(u8, heading.title, " ").len == 0 or
        std.mem.indexOfAny(u8, heading.title, "=<>[]{}|'\x00\r\n\t") != null) return false;
    return true;
}

fn tableDirectionNoSourceStyles(a: A, ns: *const namespaces.Registry, source: []const u8) !bool {
    var at: usize = 0;
    while (at < source.len) {
        if (std.mem.startsWith(u8, source[at..], "<!--")) {
            at = (std.mem.indexOfPos(u8, source, at + 4, "-->") orelse return false) + 3;
            continue;
        }
        if (source[at] == '[') {
            if (tableDirectionNoteEnd(source, at)) |end| { at = end; continue; }
            at = (try authoredElementLinkEnd(a, ns, source, at, 0)) orelse return false;
            continue;
        }
        if (source[at] == '<') {
            const tag = syntax.tagAt(source, at) orelse return false;
            for ([_][]const u8{ "style", "script", "link", "meta", "base", "templatestyles", "template", "noscript" }) |name|
                if (tag.is(name)) return false;
            at = tag.end; continue;
        }
        if (std.mem.startsWith(u8, source[at..], "{{") or std.mem.startsWith(u8, source[at..], "}}")) return false;
        at += 1;
    }
    return true;
}
// This source grammar proves only closed raw DIV ancestry for a column-zero
// WikiTable. Completed earlier list/table blocks lend no parent identity.
pub fn tableDirectionLocalParentsAlloc(a: A, ns: *const namespaces.Registry, source: []const u8,
    opening_start: usize) A.Error!?[]const TableDirectionLocalParent
{
    return tableDirectionLocalParentsInnerAlloc(a, ns, source, opening_start) catch |err| switch (err) {
        error.OutOfMemory => error.OutOfMemory,
        else => null,
    };
}
fn tableDirectionLocalParentsInnerAlloc(a: A, ns: *const namespaces.Registry, source: []const u8,
    opening_start: usize) !?[]const TableDirectionLocalParent
{
    if (source.len > 4 * 1024 * 1024 or opening_start >= source.len or
        (opening_start != 0 and source[opening_start - 1] != '\n')) return null;
    if (!std.mem.startsWith(u8, source[opening_start..], "{|")) {
        const table = syntax.tagAt(source, opening_start) orelse return null;
        if (!table.is("table") or table.closing or table.self_closing) return null;
    }
    if (!try tableDirectionNoSourceStyles(a, ns, source)) return null;
    const Open = struct { tag: syntax.Tag, start: usize };
    var stack: [128]Open = undefined; var depth: usize = 0;
    var table_depths: [64]usize = undefined; var tables: usize = 0;
    var bold = false; var italic = false; var at: usize = 0;
    var after_heading: ?usize = null;
    var last_root_div_end: ?usize = null;
    while (at < opening_start) {
        if (std.mem.startsWith(u8, source[at..], "<!--")) {
            const end = std.mem.indexOfPos(u8, source, at + 4, "-->") orelse return null;
            if (end + 3 > opening_start) return null;
            at = end + 3; continue;
        }
        if (at == 0 or source[at - 1] == '\n') {
            if (tables == 0 and depth == 0 and !bold and !italic and source[at] == '=') {
                const eol = std.mem.indexOfScalarPos(u8, source, at, '\n') orelse return null;
                if (tableDirectionPlainHeading(source[at..eol])) after_heading = eol + 1;
            }
            var begin = at;
            while (begin < opening_start and std.mem.indexOfScalar(u8, ":*#; ", source[begin]) != null) : (begin += 1) {}
            if (std.mem.startsWith(u8, source[begin..], "{|")) {
                if (tables == table_depths.len) return null;
                const end = std.mem.indexOfScalarPos(u8, source, begin, '\n') orelse return null;
                const opening = try std.fmt.allocPrint(a, "<table {s}>", .{source[begin + 2..end]});
                try figureStyleLiteralAttributes(a, syntax.tagAt(opening, 0) orelse return null);
                table_depths[tables] = depth; tables += 1;
                at = end + 1;
                continue;
            }
            if (std.mem.startsWith(u8, source[begin..], "|}")) {
                if (tables == 0 or table_depths[tables - 1] != depth) return null;
                const end = std.mem.indexOfScalarPos(u8, source, begin, '\n') orelse return null;
                if (std.mem.trim(u8, source[begin + 2..end], " \t\r").len != 0) return null;
                tables -= 1; at = end + 1; continue;
            }
        }
        if (source[at] == '[') {
            if (tableDirectionNoteEnd(source, at)) |end| { at = end; continue; }
            const end = (try authoredElementLinkEnd(a, ns, source, at, 0)) orelse return null;
            if (end > opening_start) return null;
            at = end; continue;
        }
        if (source[at] == '<') {
            const tag = syntax.tagAt(source, at) orelse return null;
            if (tag.end > opening_start or tag.isOpaque()) return null;
            var supported = false;
            for ([_][]const u8{ "div", "span", "ul", "ol", "li", "b", "i", "em", "strong", "small", "sup", "sub", "br", "hr", "wbr" }) |name|
                if (tag.is(name)) { supported = true; break; };
            // An attribute-free HTML heading may wrap this entire wiki heading.
            // It must close on the same line, outside tables and other elements.
            if (tag.is("h3")) {
                if (tag.attrs.len != 0 or tag.self_closing or tables != 0) return null;
                if (!tag.closing) {
                    if (depth != 0 or at < 2 or !std.mem.eql(u8, source[at-2..at], "==") or
                        (at > 2 and source[at-3] != '\n')) return null;
                    const pair = syntax.matchingTag(source, tag) orelse return null;
                    if (pair.end + 2 >= source.len or !std.mem.eql(u8, source[pair.end..][0..3], "==\n") or
                        std.mem.indexOfAny(u8, source[tag.end..pair.inner_end], "<>\r\n") != null) return null;
                }
                supported = true;
            }
            if (!supported) return null;
            if (tag.closing) {
                if (depth == 0 or !tag.is(stack[depth - 1].tag.name) or tag.attrs.len != 0) return null;
                depth -= 1;
                if (depth == 0 and tables == 0 and tag.is("div")) last_root_div_end = tag.end;
            } else if (!tag.is("br") and !tag.is("hr") and !tag.is("wbr")) {
                if (tag.self_closing or depth == stack.len) return null;
                stack[depth] = .{ .tag = tag, .start = at }; depth += 1;
            }
            at = tag.end; continue;
        }
        if (source[at] == '\'') {
            var end = at; while (end < opening_start and source[end] == '\'') : (end += 1) {}
            switch (end - at) { 1 => {}, 2 => italic = !italic, 3 => bold = !bold, 5 => { bold = !bold; italic = !italic; }, else => return null }
            at = end; continue;
        }
        if (source[at] == '{' or source[at] == '}' or source[at] == ']' or source[at] == 0) return null;
        if (source[at] == '\n' and (bold or italic)) return null;
        at += 1;
    }
    if (tables != 0 or bold or italic) return null;
    if (depth == 0) {
        if (opening_start != 0 and (opening_start < 2 or !std.mem.eql(u8, source[opening_start - 2..opening_start], "\n\n"))) return null;
        return &.{};
    }
    const first = stack[0].start;
    if (first != 0 and after_heading != first and (first < 2 or !std.mem.eql(u8, source[first - 2..first], "\n\n"))) {
        // A closed root DIV is also an explicit block boundary. Only whitespace
        // may separate it from the selected parent; text cannot borrow that proof.
        const closed = last_root_div_end orelse return null;
        if (closed > first or std.mem.trim(u8, source[closed..first], " \t\r\n").len != 0) return null;
    }
    var cursor = first;
    const parents = try a.alloc(TableDirectionLocalParent, depth);
    for (stack[0..depth], parents) |open, *parent| {
        if (!open.tag.is("div") or std.mem.trim(u8, source[cursor..open.start], " \t\r\n").len != 0) return null;
        const inv = try outerInventory(a, open.tag);
        const attributes = try a.alloc(profile.FigureObservedAttribute, inv.attributes.len);
        for (inv.attributes, attributes) |attribute, *out| {
            if (attribute.name.len >= 2 and std.ascii.eqlIgnoreCase(attribute.name[0..2], "on")) return null;
            out.* = .{ .name = attribute.name, .value = attribute.value };
        }
        parent.* = .{ .opening = source[open.start..open.tag.end], .tag = open.tag.name, .attributes = attributes };
        cursor = open.tag.end;
    }
    if (std.mem.trim(u8, source[cursor..opening_start], " \t\r\n").len != 0) return null;
    return parents;
}



pub const RawTableRoot = struct {
    profile: []const u8,
    namespace_id: i32,
    page_id: u64,
    revision_id: u64,
    title: []const u8,
    raw_sha256: []const u8,
    source: []const u8,
    source_table: struct { start: usize, end: usize },
    observed_table: struct { start: usize, end: usize },
    response: []const u8,
    receipt: []const u8,
    styles: TableDirectionResources,
};
const TableRootParentContainer = struct {
    start: usize,
    end: usize,
    styles: *const profile.Profile,
    context: profile.TableContainingDirectionContext,
    element: u32,
    environment: profile.CustomEnvironment,
};

fn tableRootParentContainerAlloc(a: A, ns: *const namespaces.Registry, input: RawTableRoot,
    source_parent: TableDirectionLocalParent, html: []const u8, nodes: []const ObservedSiblingNode,
    parent_index: usize, table_index: usize, context: profile.TableContainingDirectionContext,
    sources: []const profile.Source) !?TableRootParentContainer
{
    const opening = syntax.tagAt(source_parent.opening, 0) orelse return null;
    const authored = try inventory(a, opening);
    if (authored.attributes.len != 1 or authored.get("style") == null) return null;
    const start = @intFromPtr(source_parent.opening.ptr) - @intFromPtr(input.source.ptr);
    const source_tag = syntax.tagAt(input.source, start) orelse return null;
    const source_pair = syntax.matchingTag(input.source, source_tag) orelse return null;
    if (source_pair.end <= source_tag.end or source_pair.end > input.source.len or
        source_tag.end > input.source_table.start or input.source_table.start >= source_pair.inner_end or
        std.mem.trim(u8, input.source[source_tag.end..input.source_table.start], ordered_html_space).len != 0 or
        std.mem.count(u8, input.source[source_tag.end..source_pair.inner_end], "\n{|") != 1) return null;
    const parent = nodes[parent_index];
    const inner_end = parent.inner_end orelse return null;
    const table_end = intrinsicTableCapturedNodeEnd(html, nodes[table_index]) orelse return null;
    if (parent.first_child != table_index or nodes[table_index].previous != null or
        parent.tag.end > nodes[table_index].start or table_end > inner_end or
        std.mem.trim(u8, html[parent.tag.end..nodes[table_index].start], ordered_html_space).len != 0 or
        std.mem.trim(u8, html[table_end..inner_end], ordered_html_space).len != 0) return null;
    const close = syntax.tagAt(input.source, source_pair.inner_end) orelse return null;
    if (!close.closing or !close.is("div") or close.attrs.len != 0 or close.end != source_pair.end) return null;
    // Reuse the complete ordered body correspondence, including every cell,
    // action and literal footer. Its comparison-only mode issues no cell/DIV
    // ancestry and does not borrow the Table's geometry proof.
    const graph = try a.alloc(profile.ObservedStyleNode, nodes.len);
    for (nodes, graph, 0..) |node, *out, index| {
        if (node.start >= html.len or node.tag.end > html.len or
            (if (node.parent) |owner| owner >= index else index != 0)) return null;
        out.* = .{ .tag = node.tag.name, .parent = if (node.parent) |owner| @intCast(owner) else null,
            .attributes = try figureObservedAttributes(a, node.attributes) };
    }
    var proofs: std.ArrayList(profile.SourceLiteralDivProof) = .empty;
    defer proofs.deinit(a);
    var join: OrderedLiteralDivJoin = .{ .a = a, .ns = ns, .source = input.source,
        .html = html, .nodes = nodes, .graph = graph, .proofs = &proofs,
        .current_origin = (try missingStyleOrigin(a, ns.wiki)).origin };
    const matches = join.body(source_tag.end, source_pair.inner_end, parent_index, start, 0, false, null) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory, else => return null,
    };
    if (!matches or proofs.items.len != 0) return null;
    const subject = context.nodes[context.table].parent orelse return null;
    if (subject == 0 or subject > 32 or subject >= context.table or subject >= context.nodes.len or !equal(context.nodes[subject].tag, "div")) return null;
    if (context.styles.page_style_parent != null or context.styles.custom_properties != null) return null;
    const styles = try a.create(profile.Profile);
    // The authenticated head was already parsed for this exact Table root.
    // Borrow its immutable rule inventory; own only this operation's custom
    // environment arena. Both lifetimes are bounded by the same Book owner.
    styles.* = context.styles.*;
    styles.arena = std.heap.ArenaAllocator.init(a);
    var retained = false;
    defer if (!retained) styles.deinit();
    const ancestors = try a.alloc(profile.CustomElement, subject);
    for (context.nodes[0..subject], ancestors, 0..) |node, *out, index| {
        if (if (node.parent) |owner| owner + 1 != index else index != 0) return null;
        out.* = .{ .tag = node.tag, .root = index == 0 };
        for (node.attributes) |attribute| {
            if (equal(attribute.name, "class")) out.classes = attribute.value;
            if (equal(attribute.name, "id")) out.id = attribute.value;
            if (equal(attribute.name, "style")) out.inline_css = attribute.value;
        }
    }
    profile.attachCustomProperties(styles, sources, .{ .dark = null, .ancestors = ancestors }) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory, else => return null,
    };
    const custom = @constCast(styles.custom_properties orelse return null);
    custom.page_title = try styles.arena.allocator().dupe(u8, input.title);
    var own: profile.CustomElement = .{ .tag = "div" };
    for (context.nodes[subject].attributes) |attribute| {
        if (equal(attribute.name, "class")) own.classes = attribute.value;
        if (equal(attribute.name, "id")) own.id = attribute.value;
        if (equal(attribute.name, "style")) own.inline_css = attribute.value;
    }
    const environment = try custom.element(a, custom.root_environment, own, own.inline_css);
    var selected = context; selected.styles = styles;
    retained = true;
    return .{ .start = start, .end = source_pair.end, .styles = styles, .context = selected,
        .element = subject, .environment = environment };
}

const PreparedTableRoot = struct {
    input: RawTableRoot,
    contexts: []const profile.TableContainingDirectionContext,
    parent: ?struct { start: usize, end: usize },
    parent_container: ?TableRootParentContainer = null,
};
const TableRootSignature = struct { table: Inventory, row: Inventory, header: Inventory, text: []const u8 };
fn sameTableRootSignature(left: TableRootSignature, right: TableRootSignature) bool {
    return sameSiblingAttributes(left.table, right.table) and sameSiblingAttributes(left.row, right.row) and
        sameSiblingAttributes(left.header, right.header) and equal(left.text, right.text);
}
fn sourceTableRootSignature(a: A, source: []const u8, at: usize) !?TableRootSignature {
    if (at >= source.len or (at != 0 and source[at - 1] != '\n') or !std.mem.startsWith(u8, source[at..], "{|")) return null;
    const end = std.mem.indexOfScalarPos(u8, source, at, '\n') orelse return null;
    const table = (try rootTableAttributes(a, source[at + 2..end])) orelse return null;
    var header_start = end + 1;
    var header_end = std.mem.indexOfScalarPos(u8, source, header_start, '\n') orelse return null;
    var row: Inventory = .{ .attributes = &.{} };
    if (std.mem.startsWith(u8, source[header_start..header_end], "|-")) {
        // A real first-row opener is part of the occurrence, including every
        // attribute. It cannot be discarded to find a later matching header.
        row = (try rootTableAttributes(a, source[header_start + 2..header_end])) orelse return null;
        header_start = header_end + 1;
        header_end = std.mem.indexOfScalarPos(u8, source, header_start, '\n') orelse return null;
    }
    const header = source[header_start..header_end];
    if (!std.mem.startsWith(u8, header, "!") or std.mem.startsWith(u8, header, "!!")) return null;
    const split = std.mem.indexOfScalar(u8, header, '|') orelse return null;
    const attributes = (try rootTableAttributesIn(a, header[1..split], true)) orelse return null;
    const text = (try rootTableLiteralText(a, std.mem.trim(u8, header[split + 1..], " \t\r"))) orelse return null;
    return .{ .table = table, .row = row, .header = attributes, .text = text };
}
fn observedTableRootSignature(a: A, html: []const u8, nodes: []const ObservedSiblingNode, index: usize) !?TableRootSignature {
    const table = nodes[index];
    if (!table.tag.is("table")) return null;
    var row_index = table.first_child orelse return null;
    if (nodes[row_index].tag.is("tbody")) row_index = nodes[row_index].first_child orelse return null;
    const row = nodes[row_index];
    if (!row.tag.is("tr")) return null;
    const header = nodes[row.first_child orelse return null];
    if (!header.tag.is("th") or header.first_child != null) return null;
    const end = header.inner_end orelse return null;
    const text = (try rootTableLiteralText(a, std.mem.trim(u8, html[header.tag.end..end], " \t\r\n"))) orelse return null;
    return .{ .table = table.attributes, .row = row.attributes, .header = header.attributes, .text = text };
}
fn literalTableRootParent(attributes: Inventory) bool {
    if (attributes.attributes.len != 1) return false;
    if (attributes.get("align")) |alignment| return equal(alignment, "center");
    // Retain authored style verbatim. This is occurrence correspondence only;
    // the ordinary compiler/Profile still owns every box and layout property.
    return siblingLiteralAttribute("style", attributes.get("style") orelse return false);
}
fn tableRootGeneratedSection(attributes: Inventory) bool {
    if (attributes.attributes.len != 3) return false;
    const ordinal = attributes.get("data-mw-section-id") orelse return false;
    if (ordinal.len == 0 or ordinal.len > 20 or (ordinal.len > 1 and ordinal[0] == '0')) return false;
    for (ordinal) |byte| if (!std.ascii.isDigit(byte)) return false;
    _ = std.fmt.parseInt(u64, ordinal, 10) catch return false;
    // The maintained complete-GET SECTION grammar admits real Unicode IDs
    // without changing them or granting any authored source parent.
    currentLiteralSection(attributes) catch return false;
    _ = attributes.get("aria-labelledby") orelse return false;
    return true;
}
fn tableRootCurrentReceipt(a: A, ns: *const namespaces.Registry, input: RawTableRoot) !void {
    if (!equal(input.profile, "canonical-current-root-table-v1") or input.namespace_id != 0 or input.page_id == 0 or
        input.revision_id == 0 or input.title.len == 0 or !lowerHex(input.raw_sha256, 64) or
        input.source.len == 0 or input.source.len > max_response or !std.unicode.utf8ValidateSlice(input.source) or
        std.mem.indexOfScalar(u8, input.source, 0) != null or input.response.len == 0 or input.response.len > max_response) return invalid;
    _ = ns.storedPageSpec(input.title, input.namespace_id) catch return invalid;
    const receipt = try json(a, input.receipt);
    if (receipt != .object or receipt.object.count() != 4 or try field(receipt, "core") != .null or
        try tableDirectionReceiptBool(receipt, "historical_equality_proven")) return invalid;
    const unrequested = try field(receipt, "unrequested");
    const sources = try field(receipt, "sources");
    if (unrequested != .array or unrequested.array.items.len != 0 or sources != .array or sources.array.items.len != 1) return invalid;
    const row = sources.array.items[0];
    try descriptor(input.response, row);
    if (!try tableDirectionReceiptBool(row, "accepted") or !try tableDirectionReceiptBool(row, "response_complete") or
        try tableDirectionReceiptBool(row, "unknown_response_outcome") or try number(row, "status") != 200 or
        try number(row, "request_count") != 1 or (try string(row, "retrieved_utc")).len == 0) return invalid;
    const origin = try missingStyleOrigin(a, ns.wiki);
    const url = try currentOuterCanonicalUrl(a, origin.language, input.title);
    if (!equal(try string(row, "url"), url) or !equal(try string(row, "final_url"), url)) return invalid;
    const headers = try field(row, "headers");
    if (headers != .object) return invalid;
    var mime: ?[]const u8 = null;
    var iterator = headers.object.iterator();
    while (iterator.next()) |entry| if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, "content-type")) {
        if (mime != null or entry.value_ptr.* != .string) return invalid;
        mime = entry.value_ptr.string;
    };
    const content_type = mime orelse return invalid;
    const end = std.mem.indexOfScalar(u8, content_type, ';') orelse content_type.len;
    if (!std.ascii.eqlIgnoreCase(std.mem.trim(u8, content_type[0..end], " \t"), "text/html")) return invalid;
}
fn preparedTableRootAlloc(a: A, ns: *const namespaces.Registry, input: RawTableRoot) !PreparedTableRoot {
    try tableRootCurrentReceipt(a, ns, input);
    const outer = try observedOuterPrefix(a, input.response, true);
    const root_start = outer.root_start orelse return invalid;
    const root_open_end = outer.root_open_end orelse return invalid;
    _ = @import("page_language_prefix.zig").parseCurrentAlloc(a, input.response[0..root_open_end],
        input.page_id, input.revision_id, input.title) catch |err| switch (err) { error.OutOfMemory => return err, else => return invalid };
    // Validate action/article/canonical page-name independently of current IDs.
    _ = @import("page_language_prefix.zig").parseSelectedOldidAlloc(a, input.response[0..root_open_end],
        input.page_id, input.revision_id, input.namespace_id, input.title) catch |err| switch (err) { error.OutOfMemory => return err, else => return invalid };
    const root = try tableDirectionRootAlloc(a, ns, input.response, input.page_id, input.revision_id, input.styles);
    var nodes: std.ArrayList(ObservedSiblingNode) = .empty;
    var body_end: usize = 0;
    _ = try observedTextClassScopeToEndWithSections(a, ns, input.response[root_start..], &nodes, &body_end, outer.root orelse return invalid, true);
    if (body_end == 0 or nodes.items.len == 0) return invalid;
    const body = input.response[root_start..][0..body_end];
    // The head is the complete selected stylesheet set; neither parser body
    // nor later skin markup may contribute an unselected sheet or second root.
    for ([_][]const u8{ input.response[outer.body_open_end..root_start], body, input.response[root_start + body_end..] }) |part| {
        var at: usize = 0;
        while (at < part.len) {
            if (std.mem.startsWith(u8, part[at..], "<!--")) {
                at = (std.mem.indexOfPos(u8, part, at + 4, "-->") orelse return invalid) + 3; continue;
            }
            if (part[at] != '<') { at += 1; continue; }
            const tag = syntax.tagAt(part, at) orelse return invalid;
            if (!tag.closing) {
                if (tag.is("style") or tag.is("base")) return invalid;
                const inv = try outerInventory(a, tag);
                if (tag.is("link") and (part.ptr != body.ptr or !tableRootCategoryLink(inv))) return invalid;
                if (profile.Profile.hasClass(inv.get("class") orelse "", "mw-parser-output") and
                    !(part.ptr == body.ptr and at == 0)) return invalid;
                if (tag.is("script")) { at = try outerRawTextEnd(part, tag); continue; }
            }
            at = tag.end;
        }
    }
    // Reuse the closed source grammar. It refuses styles, generators, unclosed
    // local holders and uncompiled source before any correspondence is issued.
    const parents = (try tableDirectionLocalParentsAlloc(a, ns, input.source, input.source_table.start)) orelse return invalid;
    if (parents.len > 1) return invalid;
    if (parents.len == 1) {
        const tag = syntax.tagAt(parents[0].opening, 0) orelse return invalid;
        if (!tag.is("div") or !literalTableRootParent(try outerInventory(a, tag))) return invalid;
    }
    const source_end = std.mem.indexOfScalarPos(u8, input.source, input.source_table.start, '\n') orelse return invalid;
    if (input.source_table.end != source_end) return invalid;
    const signature = (try sourceTableRootSignature(a, input.source, input.source_table.start)) orelse return invalid;
    var source_matches: usize = 0;
    var cursor: usize = 0;
    while (std.mem.indexOfPos(u8, input.source, cursor, "{|")) |at| {
        cursor = at + 2;
        if (try sourceTableRootSignature(a, input.source, at)) |candidate|
            if (sameTableRootSignature(signature, candidate)) { source_matches += 1; };
    }
    if (source_matches != 1) return invalid;
    var observed: ?usize = null;
    for (nodes.items, 0..) |_, index| if (try observedTableRootSignature(a, body, nodes.items, index)) |candidate| {
        if (sameTableRootSignature(signature, candidate)) {
            if (observed != null) return invalid;
            observed = index;
        }
    };
    const table_index = observed orelse return invalid;
    const table = nodes.items[table_index];
    if (root_start + table.start != input.observed_table.start or root_start + table.tag.end != input.observed_table.end) return invalid;
    const parent_index = table.parent orelse return invalid;
    var section_parent = parent_index;
    var no_previous_table = false;
    if (parents.len == 1) {
        const parent = nodes.items[parent_index];
        if (!parent.tag.is("div")) return invalid;
        const source_parent = try outerInventory(a, syntax.tagAt(parents[0].opening, 0) orelse return invalid);
        const authored = source_parent.attributes[0];
        if (!equal(parent.attributes.get(authored.name) orelse return invalid, authored.value)) return invalid;
        // The existing source-parent parser requires only whitespace from the
        // exact DIV opening to this TABLE. Independently require the captured
        // TABLE to be that same DIV's first element, with a literal empty gap.
        no_previous_table = equal(authored.name, "style") and parent.first_child == table_index and
            table.previous == null and parent.tag.end <= table.start and
            std.mem.trim(u8, body[parent.tag.end..table.start], " \t\r\n").len == 0;
        section_parent = parent.parent orelse return invalid;
        // Keep both the exact authored attribute and every observed Parsoid
        // attribute in the cascade. Extra authored attributes cannot borrow it.
        for (parent.attributes.attributes) |attribute| {
            var known = equal(attribute.name, authored.name);
            for ([_][]const u8{ "about", "typeof", "id", "data-mw" }) |name|
                if (equal(attribute.name, name)) { known = true; break; };
            if (!known) return invalid;
        }
    }
    // Generated SECTIONs are observed ancestors, not authored source parents.
    // Keep their exact attributes and order for the complete CSS cascade.
    var section_path: [32]usize = undefined;
    var section_count: usize = 0;
    while (section_parent != 0) {
        if (section_parent >= nodes.items.len or section_count == section_path.len) return invalid;
        const node = nodes.items[section_parent];
        if (!node.tag.is("section") or !tableRootGeneratedSection(node.attributes)) return invalid;
        section_path[section_count] = section_parent;
        section_count += 1;
        const next = node.parent orelse return invalid;
        if (next >= section_parent) return invalid;
        section_parent = next;
    }
    // No sibling/descendant completeness is lent by this ancestor-only graph.
    const graph = try a.alloc(profile.ObservedStyleNode, root.nodes.len + section_count + parents.len + 1);
    @memcpy(graph[0..root.nodes.len], root.nodes);
    var at = root.nodes.len;
    var graph_parent = root.root;
    while (section_count != 0) {
        section_count -= 1;
        const node = nodes.items[section_path[section_count]];
        graph[at] = .{ .tag = "section", .attributes = try tableDirectionCopiedAttributes(a, node.attributes), .parent = graph_parent };
        graph_parent = @intCast(at); at += 1;
    }
    if (parents.len == 1) {
        graph[at] = .{ .tag = "div", .attributes = try tableDirectionCopiedAttributes(a, nodes.items[parent_index].attributes), .parent = graph_parent };
        graph_parent = @intCast(at); at += 1;
    }
    const selected_table: u32 = @intCast(at);
    graph[at] = .{ .tag = "table", .attributes = try tableDirectionCopiedAttributes(a, table.attributes), .parent = graph_parent,
        .known_no_previous_element_sibling = no_previous_table };
    const styles = try a.create(profile.Profile);
    styles.* = try profile.parseSourcesForTargetAlloc(a, root.sources, .screen);
    const contexts = try a.alloc(profile.TableContainingDirectionContext, 1);
    contexts[0] = .{ .styles = styles, .nodes = graph, .root = root.root, .table = selected_table };
    const parent_container = if (parents.len == 1)
        (tableRootParentContainerAlloc(a, ns, input, parents[0], body, nodes.items,
            parent_index, table_index, contexts[0], root.sources) catch |err| switch (err) {
                error.OutOfMemory => return error.OutOfMemory, else => null,
            }) else null;
    return .{ .input = input, .contexts = contexts, .parent_container = parent_container, .parent = if (parents.len == 1) .{
        .start = @intFromPtr(parents[0].opening.ptr) - @intFromPtr(input.source.ptr),
        .end = @intFromPtr(parents[0].opening.ptr) - @intFromPtr(input.source.ptr) + parents[0].opening.len } else null };
}
fn tableDirectionCopiedAttributes(a: A, inventory_value: Inventory) ![]const profile.FigureObservedAttribute {
    const attributes = try a.alloc(profile.FigureObservedAttribute, inventory_value.attributes.len);
    for (inventory_value.attributes, attributes) |attribute, *out| out.* = .{ .name = attribute.name, .value = attribute.value };
    return attributes;
}
fn selectedTableRootAlloc(a: A, selected: *const PreparedTableRoot, source: []const u8) !compiler.TableContainingDirectionSource {
    const Bound = struct {
        source: []const u8,
        selected: *const PreparedTableRoot,
        fn container(raw: ?*const anyopaque, _: A, operation: compiler.AuthoredElementStyleOperation) A.Error!?compiler.TableParentContainerObservation {
            const self: *const @This() = @ptrCast(@alignCast(raw orelse return null));
            const parent = self.selected.parent_container orelse return null;
            if (operation.source.ptr != self.source.ptr or operation.source.len != self.source.len or
                !equal(self.source, self.selected.input.source) or parent.start >= parent.end or parent.end > self.source.len or
                operation.element.ptr != self.source[parent.start..].ptr or operation.element.len != parent.end - parent.start) return null;
            return .{ .context = parent.context, .element = parent.element, .environment = parent.environment };
        }
        fn observe(raw: ?*const anyopaque, alloc: A, whole: []const u8, at: usize) A.Error!?compiler.TableContainingDirectionObservation {
            const self: *const @This() = @ptrCast(@alignCast(raw orelse return null));
            if (whole.ptr != self.source.ptr or whole.len != self.source.len or at != self.selected.input.source_table.start) return null;
            const parents = try alloc.alloc([]const u8, @intFromBool(self.selected.parent != null));
            if (self.selected.parent) |range| parents[0] = whole[range.start..range.end];
            return .{ .contexts = self.selected.contexts, .parents = parents };
        }
    };
    const bound = try a.create(Bound); bound.* = .{ .source = source, .selected = selected };
    return .{ .root_only = true, .source = source, .context = bound, .observe = Bound.observe,
        .observe_parent_container = if (selected.parent_container != null) Bound.container else null };
}


const TableRootTesting = struct {
    const namespace = @embedFile("testdata/fr-table-root/namespace-registry.tsv");
    const raw = @embedFile("testdata/fr-table-root/raw.wikitext");
    const expanded = @embedFile("testdata/fr-table-root/expanded.wikitext");
    fn input(a: A) !RawTableRoot {
        const parsed = try std.json.parseFromSlice(RawTableRoot, a, @embedFile("testdata/fr-table-root/table-root.json"), .{ .allocate = .alloc_always });
        return parsed.value;
    }
};

test "actual FR independent table root binds current GET source opening centered parent and selected allocation" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var ns = try namespaces.Registry.init(a, TableRootTesting.namespace); defer ns.deinit();
    const input = try TableRootTesting.input(a);
    try std.testing.expectEqualStrings(TableRootTesting.expanded, input.source);
    try std.testing.expect(digestMatches(TableRootTesting.raw, input.raw_sha256));
    const prepared = try preparedTableRootAlloc(a, &ns, input);
    try std.testing.expectEqual(@as(usize, 1), prepared.contexts.len);
    const parent = prepared.parent orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("<div align=\"center\">", input.source[parent.start..parent.end]);
    const context = prepared.contexts[0];
    const observed_parent = context.nodes[context.nodes[context.table].parent.?];
    try std.testing.expectEqualStrings("div", observed_parent.tag);
    var metadata: usize = 0;
    for (observed_parent.attributes) |attribute| {
        if (equal(attribute.name, "about") or equal(attribute.name, "typeof") or equal(attribute.name, "id") or equal(attribute.name, "data-mw")) metadata += 1;
    }
    try std.testing.expectEqual(@as(usize, 4), metadata);
    const near_section = context.nodes[observed_parent.parent.?];
    const far_section = context.nodes[near_section.parent.?];
    try std.testing.expectEqualStrings("section", near_section.tag);
    try std.testing.expectEqualStrings("section", far_section.tag);
    try std.testing.expectEqual(@as(?u32, context.root), far_section.parent);
    for ([_]struct { node: profile.ObservedStyleNode, ordinal: []const u8, id: []const u8, label: []const u8 }{
        .{ .node = far_section, .ordinal = "3", .id = "mwFg", .label = "Conventions_internationales" },
        .{ .node = near_section, .ordinal = "5", .id = "mwLw", .label = "Voir_aussi" },
    }) |expected| {
        try std.testing.expectEqual(@as(usize, 3), expected.node.attributes.len);
        for (expected.node.attributes) |attribute| {
            const value = if (equal(attribute.name, "data-mw-section-id")) expected.ordinal
                else if (equal(attribute.name, "id")) expected.id
                else if (equal(attribute.name, "aria-labelledby")) expected.label
                else return error.TestUnexpectedResult;
            try std.testing.expectEqualStrings(value, attribute.value);
        }
    }
    const selected_source = try a.dupe(u8, input.source);
    const selected = try selectedTableRootAlloc(a, &prepared, selected_source);
    const observation = (try selected.observe(selected.context, a, selected_source, input.source_table.start)) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 1), observation.parents.len);
    try std.testing.expectEqual(@intFromPtr(selected_source.ptr) + parent.start, @intFromPtr(observation.parents[0].ptr));
    try std.testing.expect((try selected.observe(selected.context, a, input.source, input.source_table.start)) == null);
    try std.testing.expect((try selected.observe(selected.context, a, selected_source, input.source_table.start + 1)) == null);
    const defaults: [32]u8 = @splat(0);
    const roots = [_]PreparedTableRoot{prepared};
    const book: Book = .{ .arena = undefined, .namespace_sha256 = ns.source_sha256, .defaults_sha256 = defaults,
        .default_width = 220, .pages = &.{}, .table_roots = &roots, .missing_link_paint = null };
    try std.testing.expect((try book.selectTableRoot(a, &ns, 0, input.page_id, input.revision_id, input.title,
        TableRootTesting.raw, selected_source, defaults)) != null);
    try std.testing.expect((try book.selectTableRoot(a, &ns, 0, input.page_id, input.revision_id + 1, input.title,
        TableRootTesting.raw, selected_source, defaults)) == null);
    try std.testing.expect((try book.selectTableRoot(a, &ns, 0, input.page_id, input.revision_id, input.title,
        "foreign raw", selected_source, defaults)) == null);
