    var wrong = try a.dupe(ObservedSiblingNode, nodes.items);
    wrong[2].parent = 2;
    try std.testing.expectError(invalid, currentLiteralFrameRootPath(html, wrong, 3));
    wrong[2] = nodes.items[2]; wrong[2].inner_end = nodes.items[3].start;
    try std.testing.expectError(invalid, currentLiteralFrameRootPath(html, wrong, 3));
}

