            1 => ranges[1] = ranges[0],
            2 => std.mem.swap(FigureStyleRange, &ranges[0], &ranges[1]),
            3 => ranges[1].end -= 1,
            4 => ranges[1].start += 1,
            5 => ranges[1].media_kind = .missing,
