    try std.testing.expect(!try orderedDivInlineCorresponds(a, &ns, "[[Target#part|label]]",
        "<a href='/w/index.php?title=Other&amp;action=edit&amp;redlink=1' class='new' title='Other (missing)'>label</a>", 0, false));
